import { apiClient } from './api';

// Types for notifications
export interface Notification {
  id: string;
  type: 'access_request' | 'approval' | 'rejection' | 'system' | 'alert';
  title: string;
  message: string;
  userId: string;
  resourceId?: string;
  isRead: boolean;
  createdAt: string;
  readAt?: string;
}

export interface NotificationResponse {
  success: boolean;
  message?: string;
  notification?: Notification;
  notifications?: Notification[];
  unreadCount?: number;
}

// Cache para notificações
const notificationCache = {
  notifications: null as any | null,
  unreadCount: null as number | null,
  lastFetchAll: 0,
  lastFetchCount: 0,
  countTTL: 300000, // 5 minutos para contadores
  fullTTL: 60000,   // 1 minuto para notificações completas
  
  // Verificar se o cache de contadores é válido
  isCountValid: () => {
    return notificationCache.unreadCount !== null && 
           (Date.now() - notificationCache.lastFetchCount < notificationCache.countTTL);
  },
  
  // Verificar se o cache de notificações completas é válido
  isFullValid: () => {
    return notificationCache.notifications !== null && 
           (Date.now() - notificationCache.lastFetchAll < notificationCache.fullTTL);
  },
  
  // Limpar todo o cache
  clearCache: () => {
    notificationCache.notifications = null;
    notificationCache.unreadCount = null;
    notificationCache.lastFetchAll = 0;
    notificationCache.lastFetchCount = 0;
  }
};

// Notification service for API communication with optimized caching
const notificationService = {
  // Get all notifications for the current user
  getNotifications: async (limit: number = 20, forceRefresh = false): Promise<NotificationResponse> => {
    // Return cached notifications if available and not expired
    if (!forceRefresh && notificationCache.isFullValid()) {
      return notificationCache.notifications;
    }
    
    try {
      // Use lower priority for this request since it's not critical
      const response = await apiClient.get(`/api/notifications?limit=${limit}`, {
        headers: { 'X-Priority': 'low' }
      });
      
      // Update cache
      notificationCache.notifications = response.data;
      notificationCache.lastFetchAll = Date.now();
      
      // Update unread count cache as well since we have this data
      if (response.data.unreadCount !== undefined) {
        notificationCache.unreadCount = response.data.unreadCount;
        notificationCache.lastFetchCount = Date.now();
      }
      
      return response.data;
    } catch (error) {
      console.error('Error fetching notifications:', error);
      return { success: false, message: 'Failed to fetch notifications' };
    }
  },

  // Get unread notification count with caching
  getUnreadCount: async (forceRefresh = false): Promise<number> => {
    // Return cached count if available and not expired
    if (!forceRefresh && notificationCache.isCountValid()) {
      return notificationCache.unreadCount as number;
    }
    
    try {
      const response = await apiClient.get('/api/notifications/unread/count', {
        headers: { 'X-Priority': 'low' }
      });
      
      // Update cache
      notificationCache.unreadCount = response.data.unreadCount || 0;
      notificationCache.lastFetchCount = Date.now();
      
      return response.data.unreadCount || 0;
    } catch (error) {
      console.error('Error fetching unread notification count:', error);
      return notificationCache.unreadCount || 0; // Return cached value even if expired
    }
  },

  // Mark a notification as read
  markAsRead: async (id: string): Promise<boolean> => {
    try {
      const response = await apiClient.put(`/api/notifications/${id}`);
      
      // Update notifications cache if available
      if (notificationCache.notifications && 
          notificationCache.notifications.notifications) {
        // Find and update the notification in cache
        const notifications = notificationCache.notifications.notifications;
        const index = notifications.findIndex((n: Notification) => n.id === id);
        if (index !== -1) {
          notifications[index].isRead = true;
          
          // Update unread count if available
          if (notificationCache.unreadCount !== null && notificationCache.unreadCount > 0) {
            notificationCache.unreadCount--;
          }
        }
      }
      
      return response.data.success;
    } catch (error) {
      console.error('Error marking notification as read:', error);
      return false;
    }
  },

  // Mark multiple notifications as read
  markMultipleAsRead: async (ids: string[]): Promise<boolean> => {
    try {
      const response = await apiClient.post('/api/notifications/mark-read', { ids });
      
      // Update notifications cache if available
      if (response.data.success && ids.length > 0) {
        if (notificationCache.notifications && 
            notificationCache.notifications.notifications) {
          // Find and update each notification in cache
          const notifications = notificationCache.notifications.notifications;
          let updatedCount = 0;
          
          ids.forEach((id: string) => {
            const index = notifications.findIndex((n: Notification) => n.id === id);
            if (index !== -1 && !notifications[index].isRead) {
              notifications[index].isRead = true;
              updatedCount++;
            }
          });
          
          // Update unread count if available
          if (notificationCache.unreadCount !== null && updatedCount > 0) {
            notificationCache.unreadCount = Math.max(0, notificationCache.unreadCount - updatedCount);
          }
        } else {
          // If no cache available, simply clear count cache to force refresh
          notificationCache.unreadCount = null;
        }
      }
      
      return response.data.success;
    } catch (error) {
      console.error('Error marking notifications as read:', error);
      return false;
    }
  },
  
  // Clear notification cache
  clearCache: () => {
    notificationCache.clearCache();
  }
};

export default notificationService;