import axios from 'axios';
// Removida a importação circular com api.ts

// Níveis de log
export enum LogLevel {
  DEBUG = 'DEBUG',
  INFO = 'INFO',
  WARN = 'WARN',
  ERROR = 'ERROR',
  FATAL = 'FATAL'
}

// Configuração do logger
interface LoggerConfig {
  minLevel: LogLevel;
  enableConsole: boolean;
  enableFileLogging: boolean;
  enableRemoteLogging: boolean;
  remoteLogEndpoint?: string;
  component?: string;
}

// Entrada de log
interface LogEntry {
  timestamp: string;
  level: LogLevel;
  message: string;
  component: string;
  data?: Record<string, any>;
  stackTrace?: string;
}

// Configuração padrão
const defaultConfig: LoggerConfig = {
  minLevel: process.env.REACT_APP_LOG_LEVEL === 'DEBUG' ? LogLevel.DEBUG : LogLevel.INFO,
  enableConsole: true,
  enableFileLogging: true,
  enableRemoteLogging: process.env.REACT_APP_ENABLE_REMOTE_LOGGING === 'true',
  remoteLogEndpoint: process.env.REACT_APP_API_URL ? `${process.env.REACT_APP_API_URL}/v1/logs` : '/v1/logs',
  component: 'frontend'
};

class Logger {
  private config: LoggerConfig;
  private logBuffer: LogEntry[] = [];
  private flushInterval: NodeJS.Timeout | null = null;
  private logFilePath: string = './logs/frontend/app.log';

  constructor(config: Partial<LoggerConfig> = {}) {
    this.config = { ...defaultConfig, ...config };
    
    // Iniciar o buffer de logs
    if (this.config.enableFileLogging || this.config.enableRemoteLogging) {
      this.startBufferFlush();
    }

    // Log inicial
    this.info('Logger initialized', { config: this.config });
  }

  // Configurar o logger
  configure(config: Partial<LoggerConfig>): void {
    this.config = { ...this.config, ...config };
    this.info('Logger reconfigured', { config: this.config });
  }

  // Método privado para criar uma entrada de log
  private createLogEntry(level: LogLevel, message: string, data?: Record<string, any>): LogEntry {
    const entry: LogEntry = {
      timestamp: new Date().toISOString(),
      level,
      message,
      component: this.config.component || 'frontend',
      data
    };

    // Adicionar stack trace para erros
    if (level === LogLevel.ERROR || level === LogLevel.FATAL) {
      entry.stackTrace = new Error().stack;
    }

    return entry;
  }

  // Método privado para processar uma entrada de log
  private processLogEntry(entry: LogEntry): void {
    // Verificar o nível mínimo de log
    const levelOrder: Record<LogLevel, number> = {
      [LogLevel.DEBUG]: 0,
      [LogLevel.INFO]: 1,
      [LogLevel.WARN]: 2,
      [LogLevel.ERROR]: 3,
      [LogLevel.FATAL]: 4
    };

    if (levelOrder[entry.level] < levelOrder[this.config.minLevel]) {
      return;
    }

    // Log no console apenas se não estiver em produção ou for erro/fatal
    if (this.config.enableConsole &&
        (process.env.NODE_ENV !== 'production' ||
         entry.level === LogLevel.ERROR ||
         entry.level === LogLevel.FATAL)) {
      this.logToConsole(entry);
    }

    // Adicionar ao buffer para logging em arquivo ou remoto
    if (this.config.enableFileLogging || this.config.enableRemoteLogging) {
      this.logBuffer.push(entry);
    }
  }

  // Método privado para log no console
  private logToConsole(entry: LogEntry): void {
    const { timestamp, level, component, message, data, stackTrace } = entry;

    // Formatar a mensagem - versão simplificada para produção
    let formattedMessage = process.env.NODE_ENV === 'production'
      ? `[${level}] ${message}`
      : `[${timestamp}] [${level}] [${component}] ${message}`;

    // Adicionar dados extras se existirem e não for produção, ou se for erro
    if (data && (process.env.NODE_ENV !== 'production' || level === LogLevel.ERROR || level === LogLevel.FATAL)) {
      formattedMessage += `\nData: ${JSON.stringify(data, null, 2)}`;
    }

    // Adicionar stack trace se existir
    if (stackTrace && (process.env.NODE_ENV !== 'production' || level === LogLevel.ERROR || level === LogLevel.FATAL)) {
      formattedMessage += `\nStack Trace: ${stackTrace}`;
    }
    
    // Escolher o método de console apropriado
    switch (level) {
      case LogLevel.DEBUG:
        console.debug(formattedMessage);
        break;
      case LogLevel.INFO:
        console.info(formattedMessage);
        break;
      case LogLevel.WARN:
        console.warn(formattedMessage);
        break;
      case LogLevel.ERROR:
      case LogLevel.FATAL:
        console.error(formattedMessage);
        break;
    }
  }

  // Método privado para iniciar o flush do buffer
  private startBufferFlush(): void {
    if (this.flushInterval) {
      clearInterval(this.flushInterval);
    }
    
    // Flush a cada 5 segundos
    this.flushInterval = setInterval(() => this.flushBuffer(), 5000);
  }

  // Método privado para flush do buffer
  private async flushBuffer(): Promise<void> {
    if (this.logBuffer.length === 0) {
      return;
    }
    
    // Limitar o número de entradas a processar para evitar problemas de memória
    const maxBatchSize = 100;
    const entriesToProcess = this.logBuffer.length > maxBatchSize 
      ? this.logBuffer.slice(0, maxBatchSize) 
      : this.logBuffer;
    
    const entries = [...entriesToProcess];
    // Remover as entradas processadas do buffer
    this.logBuffer = this.logBuffer.slice(entriesToProcess.length);

    // Log em arquivo
    if (this.config.enableFileLogging) {
      try {
        // No ambiente do navegador, não podemos escrever diretamente em arquivos
        // Então vamos enviar para o backend para salvar
        if (this.config.enableRemoteLogging) {
          // Ajustado para seguir a nova API que recebe apenas filtros
          const filters = { entries: JSON.stringify(entries) };
          // Usar axios diretamente em vez de logService para evitar dependência circular
          await axios.post('/api/v1/logs/file', filters);
        }
      } catch (error) {
        console.error('Failed to write logs to file:', error);
        // Limitar o tamanho do buffer para evitar problemas de memória
        // Adicionar apenas os últimos 100 registros se o buffer ficar muito grande
        const maxBufferSize = 100;
        if (entries.length + this.logBuffer.length > maxBufferSize) {
          const entriesToAdd = entries.slice(Math.max(0, entries.length - maxBufferSize));
          this.logBuffer = [...entriesToAdd, ...this.logBuffer.slice(0, maxBufferSize - entriesToAdd.length)];
        } else {
          this.logBuffer = [...entries, ...this.logBuffer];
        }
      }
    }

    // Log remoto
    if (this.config.enableRemoteLogging) {
      try {
        // Convertendo para o formato esperado pela nova API
        const emailData = { logs: JSON.stringify(entries) };
        // Usar axios diretamente em vez de logService para evitar dependência circular
        await axios.post('/api/v1/logs', emailData);
      } catch (error) {
        console.error('Failed to send logs to remote endpoint:', error);
        // Limitar o tamanho do buffer para evitar problemas de memória
        // Adicionar apenas os últimos 100 registros se o buffer ficar muito grande
        const maxBufferSize = 100;
        if (entries.length + this.logBuffer.length > maxBufferSize) {
          const entriesToAdd = entries.slice(Math.max(0, entries.length - maxBufferSize));
          this.logBuffer = [...entriesToAdd, ...this.logBuffer.slice(0, maxBufferSize - entriesToAdd.length)];
        } else {
          this.logBuffer = [...entries, ...this.logBuffer];
        }
      }
    }
  }

  // Métodos públicos para diferentes níveis de log
  debug(message: string, data?: Record<string, any>): void {
    const entry = this.createLogEntry(LogLevel.DEBUG, message, data);
    this.processLogEntry(entry);
  }

  info(message: string, data?: Record<string, any>): void {
    const entry = this.createLogEntry(LogLevel.INFO, message, data);
    this.processLogEntry(entry);
  }

  warn(message: string, data?: Record<string, any>): void {
    const entry = this.createLogEntry(LogLevel.WARN, message, data);
    this.processLogEntry(entry);
  }

  error(message: string, data?: Record<string, any>): void {
    const entry = this.createLogEntry(LogLevel.ERROR, message, data);
    this.processLogEntry(entry);
  }

  fatal(message: string, data?: Record<string, any>): void {
    const entry = this.createLogEntry(LogLevel.FATAL, message, data);
    this.processLogEntry(entry);
  }

  // Método para forçar o flush do buffer
  async flush(): Promise<void> {
    await this.flushBuffer();
  }
}

// Instância global do logger
export const logger = new Logger({
  minLevel: LogLevel.ERROR, // Alterado de INFO para ERROR para reduzir logs
  enableConsole: true,
  enableFileLogging: false,
  enableRemoteLogging: false,
  remoteLogEndpoint: '/api/v1/logs',
  component: 'frontend'
});

// Exportar a instância global
export default logger;