import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import {
  Card,
  CardHeader,
  CardContent,
  Avatar,
  Typography,
  Divider,
  Grid,
  TextField,
  FormControlLabel,
  Switch,
  Button,
  CircularProgress,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Snackbar,
  Alert,
  Box,
  useTheme,
  alpha
} from '@mui/material';
import {
  Email as EmailIcon,
  Send as SendIcon,
  Save as SaveIcon,
  Refresh as RefreshIcon
} from '@mui/icons-material';

import { configurationService } from '../../services/api';

const SMTPConfigPanel: React.FC = () => {
  const { t } = useTranslation('settings');
  const theme = useTheme();

  // Estado para configuração SMTP
  const [smtpConfig, setSmtpConfig] = useState({
    server: '',
    port: 25,
    use_tls: false,
    use_auth: false,
    username: '',
    password: '',
    from_email: '',
    display_name: 'DB-Manager Notifications',
    system_url: window.location.origin,
    email_logo_url: 'https://i.ibb.co/KjtdPzvW/dbmanager2.png'
  });

  // Estado para controle do painel
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [testEmailOpen, setTestEmailOpen] = useState(false);
  const [testEmailValue, setTestEmailValue] = useState('');
  const [useHtmlEmail, setUseHtmlEmail] = useState(true);
  const [testingSmtp, setTestingSmtp] = useState(false);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [hasChanges, setHasChanges] = useState(false);

  // Carrega as configurações SMTP iniciais
  useEffect(() => {
    fetchSMTPConfig();
  }, []);

  // Obtém as configurações SMTP do servidor
  const fetchSMTPConfig = async () => {
    setLoading(true);
    try {
      const response = await configurationService.getConfiguration('smtp');
      console.log('SMTP config response:', response, 'URL endpoint usado:', `/api/configuration/smtp`);
      
      if (response && response.smtp) {
        // Utilizar diretamente o formato snake_case que já vem do backend
        const formattedConfig = {
          server: response.smtp.server || '',
          port: response.smtp.port || 25,
          use_tls: response.smtp.use_tls || false,
          use_auth: response.smtp.use_auth || false,
          username: response.smtp.username || '',
          password: response.smtp.password || '',
          from_email: response.smtp.from_email || '',
          display_name: response.smtp.display_name || 'DB-Manager Notifications',
          system_url: response.smtp.system_url || window.location.origin,
          email_logo_url: response.smtp.email_logo_url || 'https://i.ibb.co/KjtdPzvW/dbmanager2.png'
        };
        
        setSmtpConfig(formattedConfig);
        setHasChanges(false);
      }
    } catch (error) {
      console.error('Erro ao buscar configuração SMTP:', error);
      setErrorMessage(t('sections.smtp.errors.loadError'));
    } finally {
      setLoading(false);
    }
  };

  // Salva a configuração SMTP
  const handleSaveSMTPConfig = async () => {
    setSaving(true);
    setErrorMessage(null);
    
    try {
      // Valida campos obrigatórios
      if (!smtpConfig.server) {
        setErrorMessage(t('sections.smtp.errors.serverRequired'));
        setSaving(false);
        return;
      }
      
      if (!smtpConfig.from_email) {
        setErrorMessage(t('sections.smtp.errors.fromEmailRequired'));
        setSaving(false);
        return;
      }
      
      // Utilizar o formato snake_case que o backend espera
      const formattedConfig = {
        server: smtpConfig.server,
        port: smtpConfig.port,
        use_tls: smtpConfig.use_tls,
        use_auth: smtpConfig.use_auth,
        username: smtpConfig.username,
        password: smtpConfig.password,
        from_email: smtpConfig.from_email,
        display_name: smtpConfig.display_name,
        system_url: smtpConfig.system_url,
        email_logo_url: smtpConfig.email_logo_url
      };
      
      // Envia a configuração para o servidor com a estrutura aninhada correta
      const response = await configurationService.updateConfiguration({ smtp: formattedConfig });
      
      console.log('Resposta ao salvar configuração SMTP:', response, 'Dados enviados:', { smtp: formattedConfig });
      setSuccessMessage(t('sections.smtp.success.saved'));
      setHasChanges(false);
    } catch (error) {
      console.error('Erro ao salvar configuração SMTP:', error);
      setErrorMessage(t('sections.smtp.errors.saveError'));
    } finally {
      setSaving(false);
    }
  };

  // Testa a configuração SMTP
  const handleTestSmtp = async () => {
    if (!testEmailValue) {
      setErrorMessage(t('sections.smtp.errors.testEmailRequired'));
      return;
    }
    
    setTestingSmtp(true);
    setErrorMessage(null);
    
    try {
      const result = await configurationService.testSMTP(testEmailValue, useHtmlEmail);
      setSuccessMessage(result.message || t('sections.smtp.success.emailSent'));
      setTestEmailOpen(false);
    } catch (error) {
      console.error('Erro ao testar SMTP:', error);
      setErrorMessage(t('sections.smtp.errors.testError', { error: error instanceof Error ? error.message : String(error) }));
    } finally {
      setTestingSmtp(false);
    }
  };

  // Manipula mudanças nos campos de texto
  const handleTextChange = (field: string, value: string) => {
    setSmtpConfig(prev => ({
      ...prev,
      [field]: value
    }));
    setHasChanges(true);
  };

  // Manipula mudanças nos campos numéricos
  const handleNumberChange = (field: string, value: string) => {
    const numValue = parseInt(value, 10);
    if (!isNaN(numValue)) {
      setSmtpConfig(prev => ({
        ...prev,
        [field]: numValue
      }));
      setHasChanges(true);
    }
  };

  // Manipula mudanças nos toggles
  const handleToggleChange = (field: string, checked: boolean) => {
    setSmtpConfig(prev => ({
      ...prev,
      [field]: checked
    }));
    
    // Define a porta padrão baseada no TLS
    if (field === 'use_tls') {
      setSmtpConfig(prev => ({
        ...prev,
        [field]: checked,
        port: checked ? 587 : 25
      }));
    }
    
    setHasChanges(true);
  };

  return (
    <Card sx={{ 
      borderRadius: 2, 
      mb: 3, 
      boxShadow: 2,
      overflow: 'hidden',
      transition: 'box-shadow 0.3s ease-in-out',
      '&:hover': {
        boxShadow: 5
      }
    }}>
      <CardHeader
        avatar={
          <Avatar sx={{ 
            bgcolor: alpha(theme.palette.primary.main, 0.1),
            color: theme.palette.primary.main,
            width: 48,
            height: 48
          }}>
            <EmailIcon />
          </Avatar>
        }
        title={
          <Typography variant="h6" sx={{ fontWeight: 600 }}>
            {t('sections.smtp.title', 'Configuração SMTP')}
          </Typography>
        }
        subheader={t('sections.smtp.description', 'Configure o serviço SMTP para envio de emails')}
        action={
          <Box sx={{ display: 'flex', gap: 1 }}>
            <Button
              variant="outlined"
              size="small"
              startIcon={<RefreshIcon />}
              onClick={fetchSMTPConfig}
              disabled={loading}
              sx={{ borderRadius: 8 }}
            >
              {t('common:refresh', 'Atualizar')}
            </Button>
            <Button
              variant="contained"
              size="small"
              startIcon={saving ? <CircularProgress size={16} /> : <SaveIcon />}
              onClick={handleSaveSMTPConfig}
              disabled={saving || !hasChanges}
              sx={{ 
                borderRadius: 8,
                fontWeight: 'bold',
                color: 'white'
              }}
            >
              {t('common:save', 'Salvar')}
            </Button>
          </Box>
        }
      />
      <Divider />
      <CardContent sx={{ p: 3 }}>
        {errorMessage && (
          <Alert severity="error" sx={{ mb: 3 }} onClose={() => setErrorMessage(null)}>
            {errorMessage}
          </Alert>
        )}
        
        {loading ? (
          <Box display="flex" justifyContent="center" p={4}>
            <CircularProgress />
          </Box>
        ) : (
          <>
            <Typography variant="subtitle2" gutterBottom>
              {t('sections.smtp.serverSettings', 'Configurações do Servidor')}
            </Typography>
            <Box sx={{ mb: 3 }}>
              <Grid container spacing={2} sx={{ mb: 3 }}>
                <Grid item xs={12} md={8}>
                  <TextField
                    fullWidth
                    label={t('sections.smtp.settings.server', 'Servidor SMTP')}
                    value={smtpConfig.server}
                    onChange={(e) => handleTextChange('server', e.target.value)}
                    placeholder="smtp.example.com"
                    variant="outlined"
                    size="small"
                  />
                </Grid>
                <Grid item xs={12} md={4}>
                  <TextField
                    fullWidth
                    label={t('sections.smtp.settings.port', 'Porta')}
                    type="number"
                    value={smtpConfig.port}
                    onChange={(e) => handleNumberChange('port', e.target.value)}
                    variant="outlined"
                    size="small"
                  />
                </Grid>
              </Grid>
              
              <Grid container spacing={2} sx={{ mb: 3 }}>
                <Grid item xs={12} md={6}>
                  <FormControlLabel
                    control={
                      <Switch
                        checked={smtpConfig.use_tls}
                        onChange={(e) => handleToggleChange('use_tls', e.target.checked)}
                      />
                    }
                    label={t('sections.smtp.settings.useTls', 'Usar TLS')}
                  />
                </Grid>
                <Grid item xs={12} md={6}>
                  <FormControlLabel
                    control={
                      <Switch
                        checked={smtpConfig.use_auth}
                        onChange={(e) => handleToggleChange('use_auth', e.target.checked)}
                      />
                    }
                    label={t('sections.smtp.settings.useAuth', 'Requer Autenticação')}
                  />
                </Grid>
              </Grid>
              
              {smtpConfig.use_auth && (
                <Grid container spacing={2} sx={{ mb: 3 }}>
                  <Grid item xs={12} md={6}>
                    <TextField
                      fullWidth
                      label={t('sections.smtp.settings.username', 'Usuário')}
                      value={smtpConfig.username}
                      onChange={(e) => handleTextChange('username', e.target.value)}
                      variant="outlined"
                      size="small"
                    />
                  </Grid>
                  <Grid item xs={12} md={6}>
                    <TextField
                      fullWidth
                      type="password"
                      label={t('sections.smtp.settings.password', 'Senha')}
                      value={smtpConfig.password}
                      onChange={(e) => handleTextChange('password', e.target.value)}
                      variant="outlined"
                      size="small"
                    />
                  </Grid>
                </Grid>
              )}
            </Box>
            
            <Divider sx={{ my: 3 }} />
            
            <Typography variant="subtitle2" gutterBottom>
              {t('sections.smtp.emailSettings', 'Configurações de Email')}
            </Typography>
            <Box>
              <Grid container spacing={2} sx={{ mb: 3 }}>
                <Grid item xs={12} md={6}>
                  <TextField
                    fullWidth
                    label={t('sections.smtp.settings.fromEmail', 'Email de Origem')}
                    value={smtpConfig.from_email}
                    onChange={(e) => handleTextChange('from_email', e.target.value)}
                    placeholder="no-reply@example.com"
                    variant="outlined"
                    size="small"
                  />
                </Grid>
                <Grid item xs={12} md={6}>
                  <TextField
                    fullWidth
                    label={t('sections.smtp.settings.displayName', 'Nome de Exibição')}
                    value={smtpConfig.display_name}
                    onChange={(e) => handleTextChange('display_name', e.target.value)}
                    placeholder="DB-Manager Notifications"
                    variant="outlined"
                    size="small"
                  />
                </Grid>
              </Grid>
              
              <Grid container spacing={2}>
                <Grid item xs={12}>
                  <TextField
                    fullWidth
                    label={t('sections.smtp.settings.systemUrl', 'URL do Sistema')}
                    value={smtpConfig.system_url}
                    onChange={(e) => handleTextChange('system_url', e.target.value)}
                    helperText={t('sections.smtp.systemUrlHelp', 'URL base usada para links em emails')}
                    variant="outlined"
                    size="small"
                  />
                </Grid>
                <Grid item xs={12}>
                  <TextField
                    fullWidth
                    label={t('sections.smtp.settings.emailLogoUrl', 'URL do Logo')}
                    value={smtpConfig.email_logo_url}
                    onChange={(e) => handleTextChange('email_logo_url', e.target.value)}
                    helperText={t('sections.smtp.logoUrlHelp', 'URL da imagem para cabeçalho dos emails')}
                    variant="outlined"
                    size="small"
                  />
                </Grid>
              </Grid>
            </Box>
            
            <Box sx={{ mt: 4, display: 'flex', justifyContent: 'center' }}>
              <Button
                variant="contained"
                color="primary"
                startIcon={<SendIcon />}
                onClick={() => setTestEmailOpen(true)}
                disabled={loading || testingSmtp}
                sx={{
                  borderRadius: 8,
                  px: 3,
                  py: 1,
                  fontWeight: 'bold',
                  boxShadow: 3
                }}
              >
                {testingSmtp ? 
                  <CircularProgress size={24} /> : 
                  t('sections.smtp.testConnection', 'Testar Conexão')}
              </Button>
            </Box>
          </>
        )}
      </CardContent>

      {/* Diálogo para enviar email de teste */}
      <Dialog open={testEmailOpen} onClose={() => setTestEmailOpen(false)}>
        <DialogTitle sx={{ 
          bgcolor: theme.palette.primary.main, 
          color: 'white',
          display: 'flex',
          alignItems: 'center',
          gap: 1,
          pb: 2
        }}>
          <EmailIcon />
          {t('sections.smtp.testEmailDialog.title', 'Enviar Email de Teste')}
        </DialogTitle>
        <DialogContent sx={{ pt: 3 }}>
          <TextField
            autoFocus
            margin="dense"
            label={t('sections.smtp.testEmailDialog.recipient', 'Email do Destinatário')}
            type="email"
            fullWidth
            variant="outlined"
            value={testEmailValue}
            onChange={(e) => setTestEmailValue(e.target.value)}
            helperText={t('sections.smtp.testEmailDialog.help', 'Um email de teste será enviado para este endereço')}
          />
          <FormControlLabel
            control={
              <Switch
                checked={useHtmlEmail}
                onChange={(e) => setUseHtmlEmail(e.target.checked)}
                color="primary"
              />
            }
            label={t('sections.smtp.testEmailDialog.useHtml', 'Usar formato HTML (modelo de convite)')}
            sx={{ mt: 2 }}
          />
        </DialogContent>
        <DialogActions sx={{ px: 3, pb: 3 }}>
          <Button onClick={() => setTestEmailOpen(false)} color="inherit">
            {t('common:cancel', 'Cancelar')}
          </Button>
          <Button 
            onClick={handleTestSmtp} 
            color="primary" 
            variant="contained"
            disabled={testingSmtp || !testEmailValue}
            startIcon={testingSmtp ? <CircularProgress size={20} /> : <SendIcon />}
            sx={{ 
              fontWeight: 'bold',
              borderRadius: 6,
              px: 2
            }}
          >
            {t('sections.smtp.testEmailDialog.send', 'Enviar Email de Teste')}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Notificação de sucesso */}
      <Snackbar 
        open={!!successMessage} 
        autoHideDuration={6000} 
        onClose={() => setSuccessMessage(null)}
        anchorOrigin={{ vertical: 'top', horizontal: 'center' }}
      >
        <Alert onClose={() => setSuccessMessage(null)} severity="success" sx={{ width: '100%' }}>
          {successMessage}
        </Alert>
      </Snackbar>
    </Card>
  );
};

export default SMTPConfigPanel;
