import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import {
  Box,
  Container,
  Paper,
  Typography,
  Tabs,
  Tab,
  TextField,
  InputAdornment,
  IconButton,
  Button,
  Card,
  CardContent,
  Avatar,
  List,
  ListItem,
  ListItemAvatar,
  ListItemText,
  ListItemSecondaryAction,
  Chip,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  CircularProgress,
  Alert,
  Tooltip,
  Fade,
  Grid,
  Badge,
  Stack,
  Collapse,
  useTheme,
  alpha,
  Divider,
} from '@mui/material';
import {
  Search as SearchIcon,
  Add as AddIcon,
  Storage as StorageIcon,
  Person as PersonIcon,
  ExpandMore as ExpandMoreIcon,
  ExpandLess as ExpandLessIcon,
  Security as SecurityIcon,
  Close as CloseIcon,
  FilterList as FilterIcon,
  Download as DownloadIcon,
  Refresh as RefreshIcon,
  AccountTree as TreeIcon,
} from '@mui/icons-material';
// No TreeView needed anymore - using cards instead

// Types
interface Permission {
  id: string;
  user_id: string;
  server_id: string;
  server_name?: string;
  database_name: string;
  schema?: string;
  table: string;
  operations: string[];
  level?: string;
  status: string;
  created_at: string;
  updated_at?: string;
  expires_at?: string;
  created_by?: string;
  is_permanent?: boolean;
}

interface User {
  id: string;
  username: string;
  email: string;
  avatar_url?: string;
}

interface Server {
  id: string;
  name: string;
  type: string;
  host: string;
  port: number;
}

interface TabPanelProps {
  children?: React.ReactNode;
  index: number;
  value: number;
}

// Tab Panel Component
function TabPanel(props: TabPanelProps) {
  const { children, value, index, ...other } = props;

  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`permissions-tabpanel-${index}`}
      aria-labelledby={`permissions-tab-${index}`}
      {...other}
    >
      {value === index && <Box sx={{ py: 3 }}>{children}</Box>}
    </div>
  );
}

// Helper function to get color based on operations
const getPermissionColor = (operations: string[]): 'error' | 'warning' | 'success' | 'info' | 'primary' | 'secondary' | 'default' | undefined => {
  const hasDelete = operations.some(op => 
    op.toUpperCase() === 'DELETE' || op.toUpperCase() === 'DROP'
  );
  const hasWrite = operations.some(op => 
    ['INSERT', 'UPDATE', 'CREATE', 'ALTER'].includes(op.toUpperCase())
  );
  const hasRead = operations.some(op => 
    op.toUpperCase() === 'SELECT' || op.toUpperCase() === 'READ'
  );

  if (hasDelete) return 'error'; // red
  if (hasWrite) return 'warning'; // yellow/orange
  if (hasRead) return 'success'; // green
  return 'info'; // blue for special permissions
};

// Main Component
const PermissionsPageNew: React.FC = () => {
  const { t } = useTranslation(['permissions', 'common']);
  const theme = useTheme();

  // State
  const [tabValue, setTabValue] = useState(0);
  const [permissions, setPermissions] = useState<Permission[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [servers, setServers] = useState<Server[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedUser, setSelectedUser] = useState<User | null>(null);
  const [modalOpen, setModalOpen] = useState(false);
  const [expandedServers, setExpandedServers] = useState<Set<string>>(new Set());

  // Fetch data
  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setLoading(true);
    try {
      // Get permissions directly from API
      const permissionsRes = await fetch('/api/permissions', {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
        credentials: 'include',
      });

      // Get users from API
      const usersRes = await fetch('/api/users', {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
        credentials: 'include',
      });

      // Get service users from API
      const serviceUsersRes = await fetch('/api/service-users', {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
        credentials: 'include',
      });

      // Get servers from API
      const serversRes = await fetch('/api/servers', {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
        credentials: 'include',
      });

      if (!permissionsRes.ok || !usersRes.ok || !serversRes.ok) {
        throw new Error('Failed to fetch data');
      }

      // Service users endpoint may return 404 if no service users exist
      let serviceUsersData = { service_users: [] };
      if (serviceUsersRes.ok) {
        serviceUsersData = await serviceUsersRes.json();
      }

      const [permissionsData, usersData, serversData] = await Promise.all([
        permissionsRes.json(),
        usersRes.json(),
        serversRes.json()
      ]);

      console.log('Permissions data:', permissionsData);
      console.log('Users data:', usersData);
      console.log('Servers data:', serversData);
      console.log('Service users data:', serviceUsersData);
      
      // Log detalhado das permissões
      if (permissionsData.permissions && permissionsData.permissions.length > 0) {
        console.log('First permission structure:', permissionsData.permissions[0]);
      }
      
      // Combine regular users and service users
      const allUsers: User[] = [
        ...(usersData.users || []),
        ...(serviceUsersData.service_users || []).map((su: any) => ({
          id: su.id,
          username: su.username || 'Unknown Service User',
          email: su.description || `Service User: ${su.username || 'Unknown'}`,
          role: 'service_user',
          status: 'active',
          full_name: su.username || 'Unknown Service User',
          is_service_user: true
        }))
      ];
      
      setPermissions(permissionsData.permissions || []);
      setUsers(allUsers);
      setServers(serversData.servers || []);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An error occurred');
    } finally {
      setLoading(false);
    }
  };

  // Computed data
  const serverPermissionsData = useMemo(() => {
    const data = new Map<string, {
      server: Server;
      userPermissions: Map<string, Permission[]>;
    }>();

    servers.forEach(server => {
      data.set(server.id, {
        server,
        userPermissions: new Map()
      });
    });

    permissions.forEach(permission => {
      const serverData = data.get(permission.server_id);
      if (serverData) {
        if (!serverData.userPermissions.has(permission.user_id)) {
          serverData.userPermissions.set(permission.user_id, []);
        }
        serverData.userPermissions.get(permission.user_id)?.push(permission);
      }
    });

    return data;
  }, [permissions, servers]);

  const userPermissionsData = useMemo(() => {
    const data = new Map<string, {
      user: User;
      serverPermissions: Map<string, Permission[]>;
    }>();

    users.forEach(user => {
      data.set(user.id, {
        user,
        serverPermissions: new Map()
      });
    });

    permissions.forEach(permission => {
      const userData = data.get(permission.user_id);
      if (userData) {
        if (!userData.serverPermissions.has(permission.server_id)) {
          userData.serverPermissions.set(permission.server_id, []);
        }
        userData.serverPermissions.get(permission.server_id)?.push(permission);
      }
    });

    return data;
  }, [permissions, users]);

  // Handlers
  const handleTabChange = (event: React.SyntheticEvent, newValue: number) => {
    setTabValue(newValue);
  };

  const handleSearchChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setSearchTerm(event.target.value);
  };

  const handleUserClick = (user: User) => {
    console.log('User clicked:', user);
    const userData = userPermissionsData.get(user.id);
    console.log('User permissions data:', userData);
    setSelectedUser(user);
    setModalOpen(true);
  };

  const handleModalClose = () => {
    setModalOpen(false);
    setSelectedUser(null);
  };

  const toggleServerExpansion = (serverId: string) => {
    const newExpanded = new Set(expandedServers);
    if (newExpanded.has(serverId)) {
      newExpanded.delete(serverId);
    } else {
      newExpanded.add(serverId);
    }
    setExpandedServers(newExpanded);
  };

  // Filter data based on search
  const filteredServers = servers.filter(server =>
    server.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const filteredUsers = users.filter(user =>
    (user.username || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
    (user.email || '').toLowerCase().includes(searchTerm.toLowerCase())
  );

  // Render server permissions tab
  const renderServerTab = () => (
    <Grid container spacing={3}>
      {filteredServers.map(server => {
        const serverData = serverPermissionsData.get(server.id);
        const userCount = serverData?.userPermissions.size || 0;
        const permissionCount = Array.from(serverData?.userPermissions.values() || [])
          .reduce((sum, perms) => sum + perms.length, 0);
        const isExpanded = expandedServers.has(server.id);

        return (
          <Grid item xs={12} key={server.id}>
            <Card
              elevation={2}
              sx={{
                borderRadius: 2,
                transition: 'all 0.3s',
                '&:hover': {
                  transform: 'translateY(-2px)',
                  boxShadow: theme.shadows[4],
                },
              }}
            >
              <CardContent
                sx={{
                  cursor: 'pointer',
                  '&:hover': {
                    bgcolor: alpha(theme.palette.primary.main, 0.02),
                  },
                }}
                onClick={() => toggleServerExpansion(server.id)}
              >
                <Box display="flex" alignItems="center" justifyContent="space-between">
                  <Box display="flex" alignItems="center" gap={2}>
                    <Avatar sx={{ bgcolor: theme.palette.primary.main }}>
                      <StorageIcon />
                    </Avatar>
                    <Box>
                      <Typography variant="h6" fontWeight="bold">
                        {server.name}
                      </Typography>
                      <Stack direction="row" spacing={2}>
                        <Chip
                          size="small"
                          label={server.type}
                          color="primary"
                          variant="outlined"
                        />
                        <Typography variant="body2" color="text.secondary">
                          {t('server.users', { count: userCount })}
                        </Typography>
                        <Typography variant="body2" color="text.secondary">
                          {t('server.permissions', { count: permissionCount })}
                        </Typography>
                      </Stack>
                    </Box>
                  </Box>
                  <IconButton>
                    {isExpanded ? <ExpandLessIcon /> : <ExpandMoreIcon />}
                  </IconButton>
                </Box>
              </CardContent>
              
              <Collapse in={isExpanded}>
                <Divider />
                <Box p={2}>
                  {serverData && serverData.userPermissions.size > 0 ? (
                    <List>
                      {Array.from(serverData.userPermissions.entries()).map(([userId, userPerms]) => {
                        const user = users.find(u => u.id === userId);
                        if (!user) return null;

                        return (
                          <ListItem key={userId}>
                            <ListItemAvatar>
                              <Avatar src={user.avatar_url} alt={user.username}>
                                {user.username.charAt(0).toUpperCase()}
                              </Avatar>
                            </ListItemAvatar>
                            <ListItemText
                              primary={
                                <Box display="flex" alignItems="center" gap={1}>
                                  {user.username}
                                  {(user as any).is_service_user && (
                                    <Chip 
                                      size="small" 
                                      label="Service User" 
                                      color="info" 
                                      variant="filled"
                                      sx={{ height: 20 }}
                                    />
                                  )}
                                </Box>
                              }
                              secondaryTypographyProps={{ component: 'div' }}
                              secondary={
                                <Stack direction="row" spacing={1} flexWrap="wrap">
                                  {userPerms.map(perm => (
                                    <Chip
                                      key={perm.id}
                                      size="small"
                                      label={perm.schema ? 
                                        `${perm.database_name || ''}.${perm.schema || ''}.${perm.table || ''}` : 
                                        `${perm.database_name || ''}.${perm.table || ''}`
                                      }
                                      color={getPermissionColor(perm.operations || [])}
                                    />
                                  ))}
                                </Stack>
                              }
                            />
                          </ListItem>
                        );
                      })}
                    </List>
                  ) : (
                    <Typography variant="body2" color="text.secondary" textAlign="center" py={3}>
                      {t('noPermissions')}
                    </Typography>
                  )}
                </Box>
              </Collapse>
            </Card>
          </Grid>
        );
      })}
    </Grid>
  );

  // Render user permissions tab
  const renderUserTab = () => (
    <List>
      {filteredUsers.map(user => {
        const userData = userPermissionsData.get(user.id);
        const serverCount = userData?.serverPermissions.size || 0;
        const permissionCount = Array.from(userData?.serverPermissions.values() || [])
          .reduce((sum, perms) => sum + perms.length, 0);

        return (
          <ListItem
            key={user.id}
            onClick={() => handleUserClick(user)}
            sx={{
              borderRadius: 2,
              mb: 1,
              cursor: 'pointer',
              '&:hover': {
                bgcolor: alpha(theme.palette.primary.main, 0.08),
              },
            }}
          >
            <ListItemAvatar>
              <Avatar src={user.avatar_url} alt={user.username}>
                {user.username.charAt(0).toUpperCase()}
              </Avatar>
            </ListItemAvatar>
            <ListItemText
              primary={
                <Box display="flex" alignItems="center" gap={1}>
                  {user.username}
                  {(user as any).is_service_user && (
                    <Chip 
                      size="small" 
                      label="Service User" 
                      color="info" 
                      variant="filled"
                      sx={{ height: 20 }}
                    />
                  )}
                </Box>
              }
              secondary={user.email}
            />
            <ListItemSecondaryAction>
              <Stack direction="row" spacing={2} alignItems="center">
                <Chip
                  size="small"
                  label={t('user.servers', { count: serverCount })}
                  color="primary"
                  variant="outlined"
                />
                <Chip
                  size="small"
                  label={t('user.permissions', { count: permissionCount })}
                  color="secondary"
                  variant="outlined"
                />
              </Stack>
            </ListItemSecondaryAction>
          </ListItem>
        );
      })}
    </List>
  );

  // Render permission tree for user modal
  const renderPermissionTree = () => {
    if (!selectedUser) return null;

    const userData = userPermissionsData.get(selectedUser.id);
    console.log('Rendering tree for user:', selectedUser.id);
    console.log('User data:', userData);
    
    if (!userData) {
      return (
        <Typography color="text.secondary" p={2}>
          {t('noPermissionsForUser')}
        </Typography>
      );
    }

    // Check if user has any permissions
    if (userData.serverPermissions.size === 0) {
      return (
        <Typography color="text.secondary" p={2}>
          {t('noPermissionsForUser')}
        </Typography>
      );
    }
    
    console.log('Server permissions size:', userData.serverPermissions.size);
    console.log('Server permissions:', Array.from(userData.serverPermissions.entries()));

    // Add a check to see if servers array is populated
    console.log('Available servers:', servers);
    console.log('Number of servers:', servers.length);

    return (
      <Box sx={{ width: '100%', overflowY: 'auto' }}>
        {Array.from(userData.serverPermissions.entries()).map(([serverId, permissions]) => {
          console.log('Processing server:', serverId);
          console.log('Permissions for server:', permissions);
          const server = servers.find(s => s.id === serverId);
          console.log('Found server:', server);
          if (!server) {
            console.log('Server not found for ID:', serverId);
            console.log('Available server IDs:', servers.map(s => s.id));
            // Even if server is not found, we can still show the permissions
            const serverName = permissions[0]?.server_name || serverId;
            console.log('Using server name from permission:', serverName);
          }

          // Group permissions by database and schema
          const dbPermissions = new Map<string, Map<string, Permission[]>>();
          console.log('Grouping permissions:', permissions);
          permissions.forEach(perm => {
            console.log('Processing permission:', perm);
            // Log all fields to find the correct database field
            console.log('Permission fields:', Object.keys(perm));
            console.log('Full permission object:', perm);
            // Use database_name field for grouping - if not present, use server database
            const dbKey = perm.database_name || (permissions.length === 1 ? 'Banco Principal' : 'Banco de Dados');
            const schemaKey = perm.schema || '';
            console.log('Database key:', dbKey, 'Schema key:', schemaKey);
            
            if (!dbPermissions.has(dbKey)) {
              dbPermissions.set(dbKey, new Map());
            }
            
            const dbMap = dbPermissions.get(dbKey)!;
            if (!dbMap.has(schemaKey)) {
              dbMap.set(schemaKey, []);
            }
            
            dbMap.get(schemaKey)?.push(perm);
          });
          console.log('Grouped permissions:', dbPermissions);

          const serverName = server?.name || permissions[0]?.server_name || serverId;
          const serverType = server?.type || 'unknown';
          
          return (
            <Card key={serverId} sx={{ mb: 2 }}>
              <CardContent>
                <Box display="flex" alignItems="center" gap={1} mb={2}>
                  <StorageIcon fontSize="small" color="primary" />
                  <Typography variant="h6">{serverName}</Typography>
                  <Chip size="small" label={serverType} />
                </Box>
                
                {Array.from(dbPermissions.entries()).map(([dbName, schemaMap]) => {
                  console.log(`Rendering database: ${dbName}`);
                  console.log('Schema map:', schemaMap);
                  return (
                    <Box key={`${serverId}-${dbName}`} sx={{ ml: 2, mb: 2 }}>
                      <Typography variant="subtitle1" fontWeight="medium" sx={{ mb: 1 }}>
                        {dbName}
                      </Typography>
                      
                      {Array.from(schemaMap.entries()).map(([schemaName, schemaPerms]) => {
                        console.log(`Rendering schema: ${schemaName} with ${schemaPerms.length} permissions`);
                        return (
                          <Box key={`${serverId}-${dbName}-${schemaName}`} sx={{ ml: 2 }}>
                            {schemaName && schemaName !== '' && schemaName !== 'tables' && (
                              <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
                                {t('schema')}: {schemaName}
                              </Typography>
                            )}
                            
                            <Grid container spacing={1}>
                              {schemaPerms.map(perm => {
                                console.log(`Rendering table permission: ${perm.table}`);
                                return (
                                  <Grid item xs={12} key={perm.id}>
                                    <Paper variant="outlined" sx={{ p: 1.5 }}>
                                      <Box display="flex" alignItems="center" justifyContent="space-between">
                                        <Typography variant="body1">{perm.table}</Typography>
                                        <Stack direction="row" spacing={0.5}>
                                          {perm.operations.map(op => (
                                            <Chip
                                              key={op}
                                              size="small"
                                              label={op}
                                              color={getPermissionColor([op])}
                                            />
                                          ))}
                                        </Stack>
                                      </Box>
                                    </Paper>
                                  </Grid>
                                );
                              })}
                            </Grid>
                          </Box>
                        );
                      })}
                    </Box>
                  );
                })}
              </CardContent>
            </Card>
          );
        })}
      </Box>
    );
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" height="50vh">
        <CircularProgress />
      </Box>
    );
  }

  if (error) {
    return (
      <Alert severity="error" sx={{ m: 3 }}>
        {error}
      </Alert>
    );
  }

  return (
    <Box sx={{ width: '100%' }}>
      <Paper sx={{ p: 3, width: '100%' }}>
        {/* Header */}
        <Box display="flex" justifyContent="space-between" alignItems="center" mb={3}>
          <Typography variant="h4" component="h1" display="flex" alignItems="center" gap={1}>
            <SecurityIcon color="primary" fontSize="large" />
            {t('title')}
          </Typography>
          <Stack direction="row" spacing={2}>
            <Button
              variant="outlined"
              startIcon={<RefreshIcon />}
              onClick={fetchData}
            >
              {t('common:refresh')}
            </Button>
            <Button
              variant="contained"
              startIcon={<AddIcon />}
            >
              {t('addPermission')}
            </Button>
          </Stack>
        </Box>

        {/* Search */}
        <Box mb={3}>
          <TextField
            fullWidth
            placeholder={t('searchPlaceholder') as string}
            value={searchTerm}
            onChange={handleSearchChange}
            InputProps={{
              startAdornment: (
                <InputAdornment position="start">
                  <SearchIcon />
                </InputAdornment>
              ),
            }}
          />
        </Box>

        {/* Tabs */}
        <Box sx={{ borderBottom: 1, borderColor: 'divider' }}>
          <Tabs value={tabValue} onChange={handleTabChange}>
            <Tab label={t('tabs.byServer')} />
            <Tab label={t('tabs.byUser')} />
          </Tabs>
        </Box>

        {/* Tab Panels */}
        <TabPanel value={tabValue} index={0}>
          {renderServerTab()}
        </TabPanel>
        <TabPanel value={tabValue} index={1}>
          {renderUserTab()}
        </TabPanel>
      </Paper>

      {/* User Permissions Modal */}
      <Dialog
        open={modalOpen}
        onClose={handleModalClose}
        maxWidth="lg"
        fullWidth
      >
        <DialogTitle>
          <Box display="flex" justifyContent="space-between" alignItems="center">
            <Typography variant="h6" display="flex" alignItems="center" gap={1}>
              <PersonIcon />
              {selectedUser?.username} - {t('modal.title')}
            </Typography>
            <IconButton onClick={handleModalClose}>
              <CloseIcon />
            </IconButton>
          </Box>
        </DialogTitle>
        <DialogContent sx={{ minHeight: '400px', pt: 3 }}>
          <Box sx={{ height: '100%' }}>
            {renderPermissionTree()}
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleModalClose}>
            {t('modal.close')}
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default PermissionsPageNew;
