import React from 'react';
import { useTranslation } from '../../i18n/i18n';
import { 
  Box, 
  Paper, 
  Tabs, 
  Tab, 
  Divider,
} from '@mui/material';
import { 
  Storage as StorageIcon,
  Sync as SyncIcon,
  Security as SecurityIcon,
  Ballot as BallotIcon
} from '@mui/icons-material';
import ElasticsearchConfigPanel from '../../components/Settings/ElasticsearchConfigPanel';
import ForwardingConfigPanel from '../../components/Settings/ForwardingConfigPanel';
import AuditPoliciesPanel from '../../components/Settings/AuditPoliciesPanel';
import ConfigPageTemplate from '../../components/Settings/ConfigPageTemplate';

// Interface para as propriedades da Tab
interface TabPanelProps {
  children?: React.ReactNode;
  index: number;
  value: number;
}

// Componente TabPanel
function TabPanel(props: TabPanelProps) {
  const { children, value, index, ...other } = props;

  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`audit-tabpanel-${index}`}
      aria-labelledby={`audit-tab-${index}`}
      {...other}
    >
      {value === index && (
        <Box sx={{ p: 3 }}>
          {children}
        </Box>
      )}
    </div>
  );
}

const AuditConfigPage: React.FC = () => {
  const { t } = useTranslation('audit');
  const [tabValue, setTabValue] = React.useState(0);

  const handleTabChange = (event: React.SyntheticEvent, newValue: number) => {
    setTabValue(newValue);
  };

  return (
    <ConfigPageTemplate
      title={t('title')}
      icon={<BallotIcon sx={{ fontSize: 32 }} />}
      description={t('description')}
    >
      <Paper sx={{ borderRadius: 2 }}>
        <Box>
          <Tabs
            value={tabValue}
            onChange={handleTabChange}
            variant="scrollable"
            scrollButtons="auto"
            aria-label="audit configuration tabs"
          >
            <Tab 
              icon={<StorageIcon />} 
              label={t('tabs.elasticsearch')} 
              id="audit-tab-0"
              aria-controls="audit-tabpanel-0" 
            />
            <Tab 
              icon={<SyncIcon />} 
              label={t('tabs.forwarding')} 
              id="audit-tab-1"
              aria-controls="audit-tabpanel-1" 
            />
            <Tab 
              icon={<SecurityIcon />} 
              label={t('tabs.policies')} 
              id="audit-tab-2"
              aria-controls="audit-tabpanel-2" 
            />
          </Tabs>
          
          <Divider />
          
          <TabPanel value={tabValue} index={0}>
            <ElasticsearchConfigPanel />
          </TabPanel>
          
          <TabPanel value={tabValue} index={1}>
            <ForwardingConfigPanel />
          </TabPanel>
          
          <TabPanel value={tabValue} index={2}>
            <AuditPoliciesPanel />
          </TabPanel>
        </Box>
      </Paper>
    </ConfigPageTemplate>
  );
};

export default AuditConfigPage;