import React from 'react';
import ReactDOM from 'react-dom/client';
import './index.css';
import App from './App';
import reportWebVitals from './reportWebVitals';
import './i18n/i18n'; // Importar configuração do i18n

// Preload authentication state for faster startup
const preloadAuthState = () => {
  // Try to preload user data from localStorage to avoid delays during render
  try {
    const authToken = localStorage.getItem('authToken');
    const userJson = localStorage.getItem('currentUser');
    
    // If we have both auth token and user data, preload them into the window object
    // This allows components to access them synchronously during first render
    if (authToken && userJson) {
      const user = JSON.parse(userJson);
      // @ts-ignore - Ignoring type checking for window property
      window.__preloadedAuthState = {
        isAuthenticated: true,
        user: user
      };
    }
  } catch (e) {
    // Ignore errors during preload
  }
};

// Preload translations
const preloadTranslations = () => {
  try {
    const savedLanguage = localStorage.getItem('language') || 'en';
    
    // @ts-ignore - Ignoring type checking for window property
    window.__preloadedLanguage = savedLanguage;
  } catch (e) {
    // Ignore errors during preload
  }
};

// Preload data before rendering
preloadAuthState();
preloadTranslations();

// Get the root element
const rootElement = document.getElementById('root') as HTMLElement;

// Create the React root
const root = ReactDOM.createRoot(rootElement);

// Render the app
const renderApp = () => {
  root.render(
    // Remove StrictMode for production builds to avoid double renders
    process.env.NODE_ENV === 'development' ? (
      <React.StrictMode>
        <App />
      </React.StrictMode>
    ) : (
      <App />
    )
  );
};

// Use requestIdleCallback if available, or setTimeout as fallback
if (typeof window.requestIdleCallback === 'function') {
  window.requestIdleCallback(() => {
    renderApp();
  });
} else {
  setTimeout(renderApp, 1);
}

// Report vitals only in production and not during development
if (process.env.NODE_ENV !== 'development') {
  reportWebVitals();
}