import React, { useState, useRef, useEffect } from 'react';
import {
  Typography,
  Grid,
  Card,
  CardContent,
  Box,
  Chip,
  Avatar,
  CircularProgress,
  Zoom,
  alpha,
  useTheme,
  styled,
  Paper,
  Collapse,
  CardActionArea,
  Button,
  TextField,
  InputAdornment,
  IconButton
} from '@mui/material';
import {
  Storage as StorageIcon,
  Dns as DnsIcon,
  DataObject as DataObjectIcon,
  CheckCircle as CheckCircleIcon,
  ErrorOutline as ErrorIcon,
  Dataset as DatasetIcon,
  ArrowForward as ArrowForwardIcon,
  Search as SearchIcon,
  Clear as ClearIcon
} from '@mui/icons-material';
import { useTranslation } from 'react-i18next';
import { StepProps, DatabaseType } from '../../types';
import StepLayout from '../shared/StepLayout';
import EnvironmentBadge from '../../../common/EnvironmentBadge';
import EnvironmentFilter from '../../../common/EnvironmentFilter';
import { Environment } from '../../../../types/environment';

// Selectable card with hover effects
const StyledCard = styled(Card)(({ theme }) => ({
  transition: 'all 0.25s ease',
  position: 'relative',
  overflow: 'hidden',
  height: '100%',
  minHeight: '160px',
  cursor: 'pointer',
  '&:hover': {
    transform: 'translateY(-4px)',
    boxShadow: theme.shadows[4],
  },
  '&::after': {
    content: '""',
    position: 'absolute',
    inset: 0,
    transition: 'opacity 0.3s ease',
    opacity: 0,
    background: `linear-gradient(45deg, ${alpha(theme.palette.primary.main, 0.1)}, ${alpha(theme.palette.primary.light, 0.15)})`,
  },
  '&:hover::after': {
    opacity: 1,
  }
}));

// Selected card with highlight effect
const SelectedCard = styled(Card)(({ theme }) => ({
  border: `2px solid ${theme.palette.primary.main}`,
  boxShadow: `0 0 12px ${alpha(theme.palette.primary.main, 0.4)}`,
  position: 'relative',
  overflow: 'hidden',
  height: '100%',
  minHeight: '160px',
  cursor: 'pointer',
  '&::after': {
    content: '""',
    position: 'absolute',
    inset: 0,
    background: `linear-gradient(45deg, ${alpha(theme.palette.primary.main, 0.15)}, ${alpha(theme.palette.primary.light, 0.2)})`,
  }
}));

// Error container with shake animation
const ErrorContainer = styled(Paper)(({ theme }) => ({
  padding: theme.spacing(1.5),
  marginTop: theme.spacing(2),
  backgroundColor: alpha(theme.palette.error.main, 0.1),
  border: `1px solid ${theme.palette.error.light}`,
  borderRadius: theme.shape.borderRadius,
  '@keyframes shake': {
    '0%, 100%': { transform: 'translateX(0)' },
    '10%, 30%, 50%, 70%, 90%': { transform: 'translateX(-5px)' },
    '20%, 40%, 60%, 80%': { transform: 'translateX(5px)' }
  }
}));

/**
 * Component for the server selection step in the request flow
 */
const ServerStep: React.FC<StepProps> = ({ state, dispatch, onNext }) => {
  const { t } = useTranslation(['requests', 'common', 'error']);
  const [shakeError, setShakeError] = useState(false);
  const [environmentFilter, setEnvironmentFilter] = useState<Environment | 'all'>('all');
  const [searchTerm, setSearchTerm] = useState('');
  const theme = useTheme();
  const errorRef = useRef<HTMLDivElement>(null);
  const selectedCardRef = useRef<HTMLDivElement>(null);

  // Scroll to selected card when selected
  useEffect(() => {
    if (state.serverId && selectedCardRef.current) {
      selectedCardRef.current.scrollIntoView({
        behavior: 'smooth',
        block: 'nearest'
      });
    }
  }, [state.serverId]);

  // Handler for server change
  const handleServerChange = async (serverId: string) => {
    console.log("Server selected:", serverId);

    // Show loading state
    dispatch({ type: 'SET_LOADING', payload: true });

    // Clear any previous error
    if (state.errors.serverId) {
      dispatch({
        type: 'SET_ERRORS',
        payload: { serverId: '' }
      });
    }

    try {
      // Get the selected server's details
      const selectedServer = state.servers.find(s => s.id === serverId);

      if (!selectedServer) {
        throw new Error("Selected server not found");
      }

      console.log("Selected server details:", selectedServer);

      // Determine database type from server type
      const dbType = selectedServer.type.toLowerCase() === 'postgres'
        ? DatabaseType.POSTGRESQL
        : selectedServer.type.toLowerCase() === 'mssql'
          ? DatabaseType.MSSQL
          : selectedServer.type.toLowerCase() === 'oracle'
            ? DatabaseType.ORACLE
            : DatabaseType.MYSQL;

      console.log("Database type identified:", dbType);

      // Update state with selected server
      dispatch({ type: 'SET_SERVER', payload: serverId });
      dispatch({ type: 'SET_DATABASE_TYPE', payload: dbType });

      // Reset dependent values
      dispatch({ type: 'SET_DATABASE_NAME', payload: '' });
      dispatch({ type: 'SET_SCHEMA', payload: dbType === DatabaseType.POSTGRESQL ? 'public' : '' });
      dispatch({ type: 'SET_TABLES', payload: [] });

      // Fetch databases directly using the API service
      try {
        const { serverService } = await import('../../../../services/api');
        console.log("Fetching databases for server:", serverId);
        const response = await serverService.getDatabases(serverId);

        // Process the response to update the state
        if (response && Array.isArray(response)) {
          const databasesList = response.map((db: any) => ({
            id: `${serverId}:${db.name || db}`,
            name: db.name || db,
            serverId
          }));

          console.log("Databases found:", databasesList);
          dispatch({ type: 'SET_DATABASES', payload: databasesList });

          // If there's only one database, select it automatically
          if (databasesList.length === 1) {
            dispatch({ type: 'SET_DATABASE_NAME', payload: databasesList[0].name });
          }
        } else {
          console.warn("No databases found or invalid response format:", response);
          dispatch({ type: 'SET_DATABASES', payload: [] });
        }
        console.log("Database fetching completed");
      } catch (error) {
        console.error("Error fetching databases:", error);
        dispatch({ type: 'SET_DATABASES', payload: [] });
      }
    } catch (error) {
      console.error("Error processing server change:", error);
      dispatch({
        type: 'SET_ERRORS',
        payload: { serverId: t('error.failedToLoadDatabases') }
      });
    } finally {
      dispatch({ type: 'SET_LOADING', payload: false });
    }
  };

  // Removida a função handleNext para evitar duplicação de botões
  // A validação é feita no componente principal do modal

  // Get icon and color for database type
  const getServerIconAndColor = (type: string) => {
    const serverType = type.toLowerCase();
    if (serverType === 'postgres' || serverType === 'postgresql') {
      return {
        icon: <DataObjectIcon />,
        color: '#3f51b5', // Indigo for PostgreSQL
        name: 'PostgreSQL'
      };
    } else if (serverType === 'mysql') {
      return {
        icon: <DnsIcon />,
        color: '#f44336', // Red for MySQL
        name: 'MySQL'
      };
    } else if (serverType === 'mssql' || serverType === 'sqlserver') {
      return {
        icon: <StorageIcon />,
        color: '#2196f3', // Blue for SQL Server
        name: 'SQL Server'
      };
    } else if (serverType === 'oracle') {
      return {
        icon: <DataObjectIcon />,
        color: '#f80000', // Red for Oracle
        name: 'Oracle'
      };
    } else {
      return {
        icon: <StorageIcon />,
        color: '#9e9e9e', // Gray for others
        name: type || 'Unknown'
      };
    }
  };

  // Find selected server
  const selectedServer = state.serverId
    ? state.servers.find(server => server.id === state.serverId)
    : null;

  // Get icon and color info for selected server
  const selectedServerData = selectedServer
    ? getServerIconAndColor(selectedServer.type)
    : null;

  return (
    <StepLayout
      title={String(t('wizard.steps.server'))}
      subtitle={String(t('wizard.serverStepSubtitle'))}
      icon="server"
    >
      <Grid container spacing={3}>
        {state.servers.length === 0 ? (
          <Grid item xs={12}>
            <Box
              sx={{
                display: 'flex',
                alignItems: 'center',
                p: 2,
                bgcolor: alpha(theme.palette.error.light, 0.1),
                color: theme.palette.error.main,
                borderRadius: 2,
                boxShadow: '0 2px 8px rgba(0,0,0,0.08)'
              }}
            >
              <ErrorIcon sx={{ mr: 1 }} />
              <Typography>
                {t('wizard.error.noServersAvailable')}
              </Typography>
            </Box>
          </Grid>
        ) : (
          <Grid item xs={12}>
            <Box display="flex" justifyContent="space-between" alignItems="center" mb={3}>
              <Typography variant="h6" sx={{ fontWeight: 500 }}>
                {t('wizard.selectServer')}
              </Typography>
              <EnvironmentFilter
                value={environmentFilter}
                onChange={setEnvironmentFilter}
                size="small"
              />
            </Box>

            {/* Search Filter */}
            <Box sx={{ mb: 3 }}>
              <TextField
                fullWidth
                size="small"
                placeholder={t('common:search') || 'Pesquisar servidores...'}
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                InputProps={{
                  startAdornment: (
                    <InputAdornment position="start">
                      <SearchIcon color="action" />
                    </InputAdornment>
                  ),
                  endAdornment: searchTerm && (
                    <InputAdornment position="end">
                      <IconButton
                        size="small"
                        onClick={() => setSearchTerm('')}
                        edge="end"
                      >
                        <ClearIcon />
                      </IconButton>
                    </InputAdornment>
                  ),
                }}
                sx={{
                  '& .MuiOutlinedInput-root': {
                    backgroundColor: 'background.paper',
                    '&:hover': {
                      backgroundColor: 'background.paper',
                    },
                  },
                }}
              />
            </Box>

            {/* Scrollable Server List Container */}
            <Box sx={{ 
              maxHeight: '400px', 
              overflowY: 'auto', 
              pr: 1,
              '&::-webkit-scrollbar': {
                width: '6px',
              },
              '&::-webkit-scrollbar-track': {
                background: '#f1f1f1',
                borderRadius: '3px',
              },
              '&::-webkit-scrollbar-thumb': {
                background: '#c1c1c1',
                borderRadius: '3px',
                '&:hover': {
                  background: '#a8a8a8',
                },
              },
            }}>
              <Grid container spacing={3}>
                {state.servers
                  .filter(server => {
                    const environmentMatch = environmentFilter === 'all' || server.environment === environmentFilter;
                    const searchMatch = searchTerm === '' || 
                      server.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                      getServerIconAndColor(server.type).name.toLowerCase().includes(searchTerm.toLowerCase());
                    return environmentMatch && searchMatch;
                  })
                  .map((server, index) => {
                const serverData = getServerIconAndColor(server.type);
                const isSelected = state.serverId === server.id;
                const CardComponent = isSelected ? SelectedCard : StyledCard;

                return (
                  <Zoom
                    in={true}
                    style={{ transitionDelay: `${index * 50}ms` }}
                    key={server.id}
                  >
                    <Grid item xs={12} sm={6} md={4} lg={3}
                      ref={isSelected ? selectedCardRef : undefined}
                    >
                      <CardComponent
                        elevation={isSelected ? 3 : 1}
                        onClick={() => handleServerChange(server.id)}
                      >
                        <CardActionArea
                          sx={{
                            height: '100%',
                            display: 'flex',
                            flexDirection: 'column',
                            alignItems: 'stretch',
                            p: 0.5
                          }}
                        >
                          <CardContent sx={{ pb: 1.5, pt: 2 }}>
                            <Box display="flex" alignItems="flex-start" mb={1.5}>
                              <Avatar
                                sx={{
                                  bgcolor: alpha(serverData.color, 0.2),
                                  color: serverData.color,
                                  width: 56,
                                  height: 56,
                                  mr: 2,
                                  mt: 0.5,
                                  boxShadow: isSelected ? `0 0 0 2px ${alpha(serverData.color, 0.5)}` : 'none'
                                }}
                              >
                                {serverData.icon}
                              </Avatar>
                              <Box flex={1}>
                                <Typography
                                  variant="h6"
                                  component="div"
                                  sx={{ 
                                    mb: 0.5, 
                                    fontWeight: isSelected ? 600 : 500,
                                    fontSize: '1.1rem',
                                    lineHeight: 1.2
                                  }}
                                >
                                  {server.name}
                                </Typography>
                                <Typography 
                                  variant="caption" 
                                  color="text.secondary"
                                  sx={{ 
                                    fontWeight: 500,
                                    letterSpacing: '0.5px'
                                  }}
                                >
                                  {serverData.name}
                                </Typography>
                              </Box>
                            </Box>

                            <Box display="flex" justifyContent="space-between" alignItems="center" mt={1}>
                              <Box display="flex" gap={1}>
                                {server.environment && (
                                  <EnvironmentBadge
                                    environment={server.environment}
                                    size="small"
                                  />
                                )}
                              </Box>

                              {isSelected && (
                                <Chip
                                  icon={<CheckCircleIcon fontSize="small" />}
                                  label={t('common:selected')}
                                  size="small"
                                  color="success"
                                />
                              )}
                            </Box>
                          </CardContent>
                        </CardActionArea>
                      </CardComponent>
                    </Grid>
                  </Zoom>
                );
                })}
              </Grid>
            </Box>

            {/* Error message with shake animation */}
            <Collapse in={!!state.errors.serverId}>
              <Box ref={errorRef}>
                <ErrorContainer
                  sx={{
                    mt: 2,
                    animation: shakeError ? 'shake 0.5s' : 'none'
                  }}
                >
                  <Box display="flex" alignItems="center">
                    <ErrorIcon color="error" fontSize="small" sx={{ mr: 1 }} />
                    <Typography color="error" variant="body2">
                      {state.errors.serverId}
                    </Typography>
                  </Box>
                </ErrorContainer>
              </Box>
            </Collapse>

            {/* O botão de navegação foi removido para evitar duplicação com os botões do modal principal */}

          </Grid>
        )}

        {state.isLoading && (
          <Grid item xs={12} sx={{ display: 'flex', justifyContent: 'center', mt: 3 }}>
            <CircularProgress size={40} thickness={4} />
          </Grid>
        )}
      </Grid>
    </StepLayout>
  );
};

export default ServerStep;
