import React from 'react';
import {
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  SelectChangeEvent,
  Box,
  Chip
} from '@mui/material';
import { useTranslation } from 'react-i18next';
import { 
  Environment, 
  ENVIRONMENTS,
  ENVIRONMENT_COLORS 
} from '../../types/environment';

interface EnvironmentFilterProps {
  value: Environment | 'all';
  onChange: (value: Environment | 'all') => void;
  showAll?: boolean;
  label?: string;
  size?: 'small' | 'medium';
  fullWidth?: boolean;
  variant?: 'outlined' | 'standard' | 'filled';
}

const EnvironmentFilter: React.FC<EnvironmentFilterProps> = ({ 
  value, 
  onChange, 
  showAll = true,
  label,
  size = 'medium',
  fullWidth = false,
  variant = 'outlined'
}) => {
  const { t } = useTranslation('common');

  const handleChange = (event: SelectChangeEvent<string>) => {
    onChange(event.target.value as Environment | 'all');
  };

  const getEnvironmentLabel = (env: Environment | 'all') => {
    if (env === 'all') {
      return t('environment.all');
    }
    switch (env) {
      case 'dev':
        return t('environment.dev');
      case 'qa':
        return t('environment.qa');
      case 'prod':
        return t('environment.prod');
      default:
        return env;
    }
  };

  return (
    <FormControl 
      size={size} 
      fullWidth={fullWidth}
      variant={variant}
    >
      <InputLabel id="environment-filter-label">
        {label || t('environment.filterByEnvironment')}
      </InputLabel>
      <Select
        labelId="environment-filter-label"
        id="environment-filter"
        value={value}
        onChange={handleChange}
        label={label || t('environment.filterByEnvironment')}
        renderValue={(selected) => (
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            {selected !== 'all' && (
              <Box
                sx={{
                  width: 12,
                  height: 12,
                  borderRadius: '50%',
                  backgroundColor: ENVIRONMENT_COLORS[selected as Environment],
                  flexShrink: 0
                }}
              />
            )}
            {getEnvironmentLabel(selected as Environment | 'all')}
          </Box>
        )}
      >
        {showAll && (
          <MenuItem value="all">
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
              {t('environment.all')}
            </Box>
          </MenuItem>
        )}
        {ENVIRONMENTS.map((env) => (
          <MenuItem key={env} value={env}>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
              <Box
                sx={{
                  width: 12,
                  height: 12,
                  borderRadius: '50%',
                  backgroundColor: ENVIRONMENT_COLORS[env],
                  flexShrink: 0
                }}
              />
              {getEnvironmentLabel(env)}
            </Box>
          </MenuItem>
        ))}
      </Select>
    </FormControl>
  );
};

export default EnvironmentFilter;