import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { 
  Box, 
  Grid, 
  Paper, 
  Typography, 
  Card, 
  CardContent,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Button,
  TextField,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  SelectChangeEvent
} from '@mui/material';
import { RefreshOutlined as RefreshIcon } from '@mui/icons-material';
import { 
  Chart as ChartJS, 
  CategoryScale, 
  LinearScale, 
  PointElement, 
  LineElement, 
  Title, 
  Tooltip, 
  Legend, 
  ArcElement 
} from 'chart.js';
import { Line, Pie } from 'react-chartjs-2';

// Registrar componentes do Chart.js
ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
  ArcElement
);

// Dados simulados para demonstração
const generateMockData = () => {
  const now = new Date();
  const labels = Array(24).fill(0).map((_, i) => {
    const date = new Date(now);
    date.setHours(date.getHours() - (23 - i));
    return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  });

  return {
    queryCount: 1250,
    avgQueryTime: 42.5,
    errorCount: 15,
    connectionCount: 35,
    queryCountData: {
      labels,
      datasets: [
        {
          label: 'Query Count',
          data: Array(24).fill(0).map(() => Math.floor(Math.random() * 100) + 20),
          borderColor: 'rgb(75, 192, 192)',
          tension: 0.1,
          fill: false
        }
      ]
    },
    queryDurationData: {
      labels,
      datasets: [
        {
          label: 'Query Duration (ms)',
          data: Array(24).fill(0).map(() => Math.floor(Math.random() * 80) + 10),
          borderColor: 'rgb(255, 99, 132)',
          tension: 0.1,
          fill: false
        }
      ]
    },
    queryTypesData: {
      labels: ['SELECT', 'INSERT', 'UPDATE', 'DELETE', 'Other'],
      datasets: [
        {
          data: [65, 12, 18, 5, 2],
          backgroundColor: [
            'rgb(54, 162, 235)',
            'rgb(75, 192, 192)',
            'rgb(255, 205, 86)',
            'rgb(255, 99, 132)',
            'rgb(201, 203, 207)'
          ]
        }
      ]
    },
    errorTypesData: {
      labels: ['Syntax Error', 'Permission Error', 'Connection Error', 'Timeout', 'Other'],
      datasets: [
        {
          data: [5, 7, 2, 1, 0],
          backgroundColor: [
            'rgb(255, 99, 132)',
            'rgb(255, 159, 64)',
            'rgb(255, 205, 86)',
            'rgb(75, 192, 192)',
            'rgb(201, 203, 207)'
          ]
        }
      ]
    },
    topQueries: [
      { 
        query: 'SELECT * FROM users WHERE status = ?', 
        count: 325, 
        avgTime: 12.5, 
        totalTime: 4062.5 
      },
      { 
        query: 'INSERT INTO logs (user_id, action, timestamp) VALUES (?, ?, ?)', 
        count: 215, 
        avgTime: 18.3, 
        totalTime: 3934.5 
      },
      { 
        query: 'SELECT id, name, email FROM customers WHERE created_at > ?', 
        count: 187, 
        avgTime: 24.7, 
        totalTime: 4618.9 
      }
    ]
  };
};

const timeRangeOptions = [
  { value: '1h', label: 'Last Hour' },
  { value: '6h', label: 'Last 6 Hours' },
  { value: '12h', label: 'Last 12 Hours' },
  { value: '24h', label: 'Last 24 Hours' },
  { value: '7d', label: 'Last 7 Days' },
  { value: '30d', label: 'Last 30 Days' },
  { value: 'custom', label: 'Custom Range' }
];

const databaseOptions = [
  { value: 'all', label: 'All Databases' },
  { value: 'mysql-test', label: 'MySQL Test' },
  { value: 'postgres-test', label: 'PostgreSQL Test' },
  { value: 'mssql-test', label: 'MSSQL Test' }
];

const MonitoringPage: React.FC = () => {
  const { i18n } = useTranslation();
  const [data, setData] = useState(generateMockData());
  const [timeRange, setTimeRange] = useState('24h');
  const [database, setDatabase] = useState('all');
  const [showCustomRange, setShowCustomRange] = useState(false);
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [loading, setLoading] = useState(false);

  // Função auxiliar para tradução compatível com a versão atual
  const translate = (key: string) => {
    try {
      // @ts-ignore - Ignoring type checking for this line due to i18n version compatibility
      return i18n.t(key);
    } catch (error) {
      console.warn(`Translation key not found: ${key}`);
      return key;
    }
  };

  useEffect(() => {
    fetchData();
  }, [timeRange, database]);

  const fetchData = async () => {
    setLoading(true);
    try {
      // Simulando uma chamada à API
      await new Promise(resolve => setTimeout(resolve, 500));
      // Em uma implementação real, substituiríamos por:
      // const response = await api.get('/monitoring', { params: { timeRange, database } });
      // setData(response.data);
      setData(generateMockData());
    } catch (error) {
      console.error('Error fetching monitoring data:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleTimeRangeChange = (event: SelectChangeEvent) => {
    const newValue = event.target.value;
    setTimeRange(newValue);
    setShowCustomRange(newValue === 'custom');
  };

  const handleDatabaseChange = (event: SelectChangeEvent) => {
    setDatabase(event.target.value);
  };

  const handleRefresh = () => {
    fetchData();
  };

  const handleApplyCustomRange = () => {
    if (startDate && endDate) {
      fetchData();
    }
  };

  return (
    <Box>
      <Typography variant="h4" gutterBottom>
        {translate('monitoring.title')}
      </Typography>

      <Paper sx={{ p: 2, mb: 3 }}>
        <Grid container spacing={2} alignItems="flex-end">
          <Grid item xs={12} md={4}>
            <FormControl fullWidth>
              <InputLabel id="time-range-label">{translate('monitoring.filters.timeRange')}</InputLabel>
              <Select
                labelId="time-range-label"
                id="time-range"
                value={timeRange}
                label={translate('monitoring.filters.timeRange')}
                onChange={handleTimeRangeChange}
              >
                {timeRangeOptions.map(option => (
                  <MenuItem key={option.value} value={option.value}>
                    {option.label}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
          </Grid>
          <Grid item xs={12} md={4}>
            <FormControl fullWidth>
              <InputLabel id="database-label">{translate('monitoring.filters.database')}</InputLabel>
              <Select
                labelId="database-label"
                id="database"
                value={database}
                label={translate('monitoring.filters.database')}
                onChange={handleDatabaseChange}
              >
                {databaseOptions.map(option => (
                  <MenuItem key={option.value} value={option.value}>
                    {option.label}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
          </Grid>
          <Grid item xs={12} md={4}>
            <Button
              variant="contained"
              startIcon={<RefreshIcon />}
              onClick={handleRefresh}
              fullWidth
              disabled={loading}
            >
              {translate('monitoring.filters.refreshButton')}
            </Button>
          </Grid>
          
          {showCustomRange && (
            <Grid container item spacing={2} xs={12}>
              <Grid item xs={12} md={5}>
                <TextField
                  label="Start Date"
                  type="datetime-local"
                  value={startDate}
                  onChange={(e) => setStartDate(e.target.value)}
                  InputLabelProps={{ shrink: true }}
                  fullWidth
                />
              </Grid>
              <Grid item xs={12} md={5}>
                <TextField
                  label="End Date"
                  type="datetime-local"
                  value={endDate}
                  onChange={(e) => setEndDate(e.target.value)}
                  InputLabelProps={{ shrink: true }}
                  fullWidth
                />
              </Grid>
              <Grid item xs={12} md={2}>
                <Button 
                  variant="outlined" 
                  onClick={handleApplyCustomRange}
                  fullWidth
                >
                  Apply
                </Button>
              </Grid>
            </Grid>
          )}
        </Grid>
      </Paper>

      <Grid container spacing={3}>
        {/* Métricas */}
        <Grid item xs={6} sm={3}>
          <Card>
            <CardContent sx={{ textAlign: 'center' }}>
              <Typography variant="h4" component="div">
                {data.queryCount.toLocaleString()}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                {translate('monitoring.metrics.queries')}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={6} sm={3}>
          <Card>
            <CardContent sx={{ textAlign: 'center' }}>
              <Typography variant="h4" component="div">
                {data.avgQueryTime.toFixed(2)} ms
              </Typography>
              <Typography variant="body2" color="text.secondary">
                {translate('monitoring.metrics.avgQueryTime')}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={6} sm={3}>
          <Card>
            <CardContent sx={{ textAlign: 'center' }}>
              <Typography variant="h4" component="div">
                {data.errorCount.toLocaleString()}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                {translate('monitoring.metrics.errors')}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={6} sm={3}>
          <Card>
            <CardContent sx={{ textAlign: 'center' }}>
              <Typography variant="h4" component="div">
                {data.connectionCount.toLocaleString()}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                {translate('monitoring.metrics.connections')}
              </Typography>
            </CardContent>
          </Card>
        </Grid>

        {/* Gráficos de linha */}
        <Grid item xs={12} md={6}>
          <Paper sx={{ p: 2 }}>
            <Typography variant="h6" gutterBottom>
              {translate('monitoring.charts.queryCount')}
            </Typography>
            <Box sx={{ height: 300 }}>
              <Line
                data={data.queryCountData}
                options={{
                  responsive: true,
                  maintainAspectRatio: false,
                  plugins: {
                    legend: {
                      position: 'top' as const,
                    }
                  }
                }}
              />
            </Box>
          </Paper>
        </Grid>
        <Grid item xs={12} md={6}>
          <Paper sx={{ p: 2 }}>
            <Typography variant="h6" gutterBottom>
              {translate('monitoring.charts.queryDuration')}
            </Typography>
            <Box sx={{ height: 300 }}>
              <Line
                data={data.queryDurationData}
                options={{
                  responsive: true,
                  maintainAspectRatio: false,
                  plugins: {
                    legend: {
                      position: 'top' as const,
                    }
                  }
                }}
              />
            </Box>
          </Paper>
        </Grid>

        {/* Gráficos de pizza */}
        <Grid item xs={12} md={6}>
          <Paper sx={{ p: 2 }}>
            <Typography variant="h6" gutterBottom>
              {translate('monitoring.charts.queryTypes')}
            </Typography>
            <Box sx={{ height: 300, display: 'flex', justifyContent: 'center' }}>
              <Box sx={{ width: '70%' }}>
                <Pie
                  data={data.queryTypesData}
                  options={{
                    responsive: true,
                    maintainAspectRatio: false,
                    plugins: {
                      legend: {
                        position: 'right' as const,
                      }
                    }
                  }}
                />
              </Box>
            </Box>
          </Paper>
        </Grid>
        <Grid item xs={12} md={6}>
          <Paper sx={{ p: 2 }}>
            <Typography variant="h6" gutterBottom>
              {translate('monitoring.charts.errorTypes')}
            </Typography>
            <Box sx={{ height: 300, display: 'flex', justifyContent: 'center' }}>
              <Box sx={{ width: '70%' }}>
                <Pie
                  data={data.errorTypesData}
                  options={{
                    responsive: true,
                    maintainAspectRatio: false,
                    plugins: {
                      legend: {
                        position: 'right' as const,
                      }
                    }
                  }}
                />
              </Box>
            </Box>
          </Paper>
        </Grid>

        {/* Tabela de consultas principais */}
        <Grid item xs={12}>
          <Paper sx={{ p: 2 }}>
            <Typography variant="h6" gutterBottom>
              {translate('monitoring.topQueries.title')}
            </Typography>
            <TableContainer>
              <Table>
                <TableHead>
                  <TableRow>
                    <TableCell>{translate('monitoring.topQueries.table.query')}</TableCell>
                    <TableCell align="right">{translate('monitoring.topQueries.table.count')}</TableCell>
                    <TableCell align="right">{translate('monitoring.topQueries.table.avgTime')}</TableCell>
                    <TableCell align="right">{translate('monitoring.topQueries.table.totalTime')}</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {data.topQueries.map((query, index) => (
                    <TableRow key={index}>
                      <TableCell component="th" scope="row" sx={{ maxWidth: 400, overflow: 'hidden', textOverflow: 'ellipsis' }}>
                        {query.query}
                      </TableCell>
                      <TableCell align="right">{query.count.toLocaleString()}</TableCell>
                      <TableCell align="right">{query.avgTime.toFixed(2)} ms</TableCell>
                      <TableCell align="right">{query.totalTime.toFixed(2)} ms</TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          </Paper>
        </Grid>
      </Grid>
    </Box>
  );
};

export default MonitoringPage;