import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import {
  Card,
  CardHeader,
  CardContent,
  Avatar,
  Typography,
  Divider,
  Grid,
  FormControlLabel,
  Switch,
  Button,
  CircularProgress,
  Snackbar,
  Alert,
  Box,
  useTheme,
  alpha,
  Tooltip,
  IconButton,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Paper,
} from '@mui/material';
import {
  ViewQuilt as ViewQuiltIcon,
  Save as SaveIcon,
  Refresh as RefreshIcon,
  Info as InfoIcon,
  Language as LanguageIcon,
  Palette as PaletteIcon,
  AutoAwesome as AutoAwesomeIcon,
  FormatSize as FormatSizeIcon,
} from '@mui/icons-material';

import { configurationService } from '../../services/api';

interface InterfaceConfig {
  theme: string;
  animations: boolean;
  density: string;
}

interface LocalizationConfig {
  defaultLanguage: string;
}

const InterfaceConfigPanel: React.FC = () => {
  const { t, i18n } = useTranslation(['settings', 'common']);
  const theme = useTheme();

  // Estado para configuração de interface
  const [interfaceConfig, setInterfaceConfig] = useState<InterfaceConfig>({
    theme: 'light',
    animations: true,
    density: 'standard'
  });

  // Estado para configuração de localização
  const [localizationConfig, setLocalizationConfig] = useState<LocalizationConfig>({
    defaultLanguage: 'en'
  });

  // Estado para controle do painel
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [hasChanges, setHasChanges] = useState(false);

  // Carrega as configurações de interface iniciais
  useEffect(() => {
    fetchInterfaceConfig();
  }, []);

  // Obtém as configurações de interface do servidor
  const fetchInterfaceConfig = async () => {
    setLoading(true);
    try {
      // Buscar configurações gerais
      const response = await configurationService.getConfiguration();
      console.log('Interface config response:', response);
      
      if (response) {
        // Atualizar configurações de interface
        if (response.interface) {
          setInterfaceConfig(response.interface);
        }
        
        // Atualizar configurações de localização
        if (response.localization) {
          setLocalizationConfig(response.localization);
        }
        
        setHasChanges(false);
      }
      
      // Também buscar preferências do usuário
      try {
        const userPrefs = await configurationService.getUserPreferences();
        console.log('User preferences:', userPrefs);
        
        if (userPrefs) {
          // Aplicar preferências do usuário se existirem
          const newInterfaceConfig = { ...interfaceConfig };
          
          if (userPrefs.theme) {
            newInterfaceConfig.theme = userPrefs.theme;
          }
          
          if (userPrefs.animations !== undefined) {
            newInterfaceConfig.animations = userPrefs.animations;
          }
          
          if (userPrefs.density) {
            newInterfaceConfig.density = userPrefs.density;
          }
          
          setInterfaceConfig(newInterfaceConfig);
          
          // Atualizar idioma se disponível
          if (userPrefs.language) {
            setLocalizationConfig({
              ...localizationConfig,
              defaultLanguage: userPrefs.language
            });
          }
        }
      } catch (error) {
        console.error('Erro ao buscar preferências do usuário:', error);
      }
      
    } catch (error) {
      console.error('Erro ao buscar configurações de interface:', error);
      setErrorMessage('Erro ao carregar configurações de interface');
    } finally {
      setLoading(false);
    }
  };

  // Salva as configurações de interface
  const handleSaveInterfaceConfig = async () => {
    setSaving(true);
    setErrorMessage(null);
    
    try {
      // Salvar configurações globais do sistema
      await configurationService.updateConfiguration({
        interface: interfaceConfig,
        localization: localizationConfig
      });
      
      // Salvar preferências do usuário
      await configurationService.updateUserPreferences({
        theme: interfaceConfig.theme,
        animations: interfaceConfig.animations,
        density: interfaceConfig.density,
        language: localizationConfig.defaultLanguage
      });
      
      setSuccessMessage(t('interface.saveSuccess'));
      setHasChanges(false);
      
      // Aplicar mudança de idioma imediatamente
      if (i18n.language !== localizationConfig.defaultLanguage) {
        i18n.changeLanguage(localizationConfig.defaultLanguage);
        localStorage.setItem('userLanguage', localizationConfig.defaultLanguage);
      }
      
      // Se o tema foi alterado, recarregar a página para aplicar
      const currentTheme = localStorage.getItem('userTheme');
      if (currentTheme !== interfaceConfig.theme) {
        localStorage.setItem('userTheme', interfaceConfig.theme);
        setTimeout(() => {
          window.location.reload();
        }, 1000);
      }
      
    } catch (error) {
      console.error('Erro ao salvar configurações de interface:', error);
      setErrorMessage(t('interface.saveError'));
    } finally {
      setSaving(false);
    }
  };

  // Manipula alterações na configuração de interface
  const handleInterfaceConfigChange = (field: keyof InterfaceConfig, value: any) => {
    setInterfaceConfig(prev => ({
      ...prev,
      [field]: value
    }));
    setHasChanges(true);
  };

  // Manipula alterações na configuração de localização
  const handleLocalizationConfigChange = (field: keyof LocalizationConfig, value: any) => {
    setLocalizationConfig(prev => ({
      ...prev,
      [field]: value
    }));
    setHasChanges(true);
  };

  // Preview de tema
  const renderThemePreview = (selectedTheme: string) => {
    const isDark = selectedTheme === 'dark';
    const colors = {
      light: {
        bg: '#FFFFFF',
        text: '#333333',
        primary: theme.palette.primary.main,
        secondary: alpha(theme.palette.primary.main, 0.1)
      },
      dark: {
        bg: '#121212',
        text: '#FFFFFF',
        primary: theme.palette.primary.main,
        secondary: alpha(theme.palette.primary.main, 0.2)
      },
      system: {
        bg: alpha('#808080', 0.1),
        text: '#555555',
        primary: theme.palette.primary.main,
        secondary: alpha(theme.palette.primary.main, 0.15) 
      }
    };
    
    // Escolher o conjunto de cores com base no tema selecionado
    let colorSet = colors.light;
    if (selectedTheme === 'dark') {
      colorSet = colors.dark;
    } else if (selectedTheme === 'system') {
      colorSet = colors.system;
    }
    
    return (
      <Paper
        sx={{
          width: '100%',
          height: 100,
          backgroundColor: colorSet.bg,
          borderRadius: 2,
          p: 2,
          border: `1px solid ${alpha(theme.palette.divider, 0.1)}`,
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'space-between',
          boxShadow: 2
        }}
      >
        {/* Header do preview */}
        <Box
          sx={{
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            p: 1,
            borderRadius: 1,
            backgroundColor: colorSet.secondary
          }}
        >
          <Box
            sx={{
              display: 'flex',
              alignItems: 'center',
              gap: 1
            }}
          >
            <Box
              sx={{
                width: 8,
                height: 8,
                borderRadius: '50%',
                backgroundColor: colorSet.primary
              }}
            />
            <Box
              sx={{
                width: 40,
                height: 6,
                borderRadius: 1,
                backgroundColor: colorSet.text,
                opacity: 0.7
              }}
            />
          </Box>
          
          <Box
            sx={{
              display: 'flex',
              gap: 1
            }}
          >
            <Box
              sx={{
                width: 12,
                height: 12,
                borderRadius: 0.5,
                backgroundColor: colorSet.text,
                opacity: 0.5
              }}
            />
            <Box
              sx={{
                width: 12,
                height: 12,
                borderRadius: 0.5,
                backgroundColor: colorSet.text,
                opacity: 0.5
              }}
            />
          </Box>
        </Box>
        
        {/* Conteúdo do preview */}
        <Box sx={{ display: 'flex', justifyContent: 'space-between', px: 1 }}>
          <Box>
            <Box
              sx={{
                width: 60,
                height: 6,
                borderRadius: 1,
                backgroundColor: colorSet.text,
                mb: 1
              }}
            />
            <Box
              sx={{
                width: 100,
                height: 4,
                borderRadius: 1,
                backgroundColor: colorSet.text,
                opacity: 0.5
              }}
            />
          </Box>
          
          <Box
            sx={{
              width: 20,
              height: 20,
              borderRadius: '50%',
              backgroundColor: colorSet.primary,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center'
            }}
          >
            <Box
              sx={{
                width: 10,
                height: 10,
                borderRadius: '50%',
                backgroundColor: 'white'
              }}
            />
          </Box>
        </Box>
      </Paper>
    );
  };

  // Preview de densidade
  const renderDensityPreview = (density: string) => {
    let spacing = 2;
    
    if (density === 'compact') {
      spacing = 1;
    } else if (density === 'comfortable') {
      spacing = 3;
    }
    
    return (
      <Paper 
        sx={{
          p: 2,
          width: '100%',
          height: 100,
          borderRadius: 2,
          boxShadow: 2
        }}
      >
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: spacing }}>
          <Box
            sx={{
              width: '100%',
              height: 8,
              borderRadius: 1,
              backgroundColor: alpha(theme.palette.primary.main, 0.1)
            }}
          />
          <Box
            sx={{
              width: '100%',
              height: 8,
              borderRadius: 1,
              backgroundColor: alpha(theme.palette.primary.main, 0.2)
            }}
          />
          <Box
            sx={{
              width: '100%',
              height: 8,
              borderRadius: 1,
              backgroundColor: alpha(theme.palette.primary.main, 0.3)
            }}
          />
          <Box
            sx={{
              width: '100%',
              height: 8,
              borderRadius: 1,
              backgroundColor: alpha(theme.palette.primary.main, 0.4)
            }}
          />
        </Box>
      </Paper>
    );
  };

  return (
    <Box>
      {/* Seção de Localização */}
      <Card sx={{ 
        borderRadius: 2, 
        mb: 3, 
        boxShadow: 2,
        overflow: 'hidden',
        transition: 'box-shadow 0.3s ease-in-out',
        '&:hover': {
          boxShadow: 5
        }
      }}>
        <CardHeader
          avatar={
            <Avatar sx={{ 
              bgcolor: alpha(theme.palette.primary.main, 0.1),
              color: theme.palette.primary.main,
              width: 48,
              height: 48
            }}>
              <LanguageIcon />
            </Avatar>
          }
          title={
            <Typography variant="h6" sx={{ fontWeight: 600 }}>
              {t('general.language.title')}
            </Typography>
          }
          subheader={t('general.language.description')}
        />
        <Divider />
        <CardContent sx={{ p: 3 }}>
          {errorMessage && (
            <Alert severity="error" sx={{ mb: 3 }} onClose={() => setErrorMessage(null)}>
              {errorMessage}
            </Alert>
          )}
          
          {loading ? (
            <Box display="flex" justifyContent="center" p={4}>
              <CircularProgress />
            </Box>
          ) : (
            <>
              <Grid container spacing={3}>
                <Grid item xs={12} md={6}>
                  <FormControl fullWidth variant="outlined">
                    <InputLabel>{t('general.language.options.defaultLanguage')}</InputLabel>
                    <Select
                      value={localizationConfig.defaultLanguage}
                      onChange={(e) => handleLocalizationConfigChange('defaultLanguage', e.target.value)}
                      label={t('general.language.options.defaultLanguage')}
                      disabled={loading}
                    >
                      <MenuItem value="en">English</MenuItem>
                      <MenuItem value="pt">Português</MenuItem>
                      <MenuItem value="es">Español</MenuItem>
                    </Select>
                  </FormControl>
                </Grid>
                <Grid item xs={12} md={6} display="flex" alignItems="center">
                  <Box 
                    sx={{ 
                      display: 'flex', 
                      flexDirection: 'column', 
                      height: '100%',
                      justifyContent: 'center'
                    }}
                  >
                    <Typography variant="body2" color="textSecondary" gutterBottom>
                      {t('general.language.current')}: 
                      <Typography component="span" fontWeight="bold" sx={{ ml: 1 }}>
                        {localizationConfig.defaultLanguage === 'en' ? 'English' : 
                         localizationConfig.defaultLanguage === 'pt' ? 'Português' : 
                         'Español'}
                      </Typography>
                    </Typography>
                    <Typography variant="caption" color="textSecondary">
                      {t('general.language.defaultDescription')}
                    </Typography>
                  </Box>
                </Grid>
              </Grid>
            </>
          )}
        </CardContent>
      </Card>

      {/* Seção de Interface */}
      <Card sx={{ 
        borderRadius: 2, 
        mb: 3, 
        boxShadow: 2,
        overflow: 'hidden',
        transition: 'box-shadow 0.3s ease-in-out',
        '&:hover': {
          boxShadow: 5
        }
      }}>
        <CardHeader
          avatar={
            <Avatar sx={{ 
              bgcolor: alpha(theme.palette.primary.main, 0.1),
              color: theme.palette.primary.main,
              width: 48,
              height: 48
            }}>
              <ViewQuiltIcon />
            </Avatar>
          }
          title={
            <Typography variant="h6" sx={{ fontWeight: 600 }}>
              {t('sections.interface.title')}
            </Typography>
          }
          subheader={t('sections.interface.description')}
          action={
            <Box sx={{ display: 'flex', gap: 1 }}>
              <Button
                variant="outlined"
                size="small"
                startIcon={<RefreshIcon />}
                onClick={fetchInterfaceConfig}
                disabled={loading}
                sx={{ borderRadius: 8 }}
              >
                {t('common:refresh')}
              </Button>
              <Button
                variant="contained"
                size="small"
                startIcon={saving ? <CircularProgress size={16} /> : <SaveIcon />}
                onClick={handleSaveInterfaceConfig}
                disabled={saving || !hasChanges}
                sx={{ 
                  borderRadius: 8,
                  fontWeight: 'bold',
                  color: 'white'
                }}
              >
                {t('common:save')}
              </Button>
            </Box>
          }
        />
        <Divider />
        <CardContent sx={{ p: 3 }}>
          {loading ? (
            <Box display="flex" justifyContent="center" p={4}>
              <CircularProgress />
            </Box>
          ) : (
            <>
              <Typography variant="subtitle1" sx={{ 
                display: 'flex', 
                alignItems: 'center', 
                mb: 2,
                fontWeight: 600,
                color: theme.palette.primary.main
              }}>
                <PaletteIcon fontSize="small" sx={{ mr: 1 }} />
                {t('general.theme.title')}
              </Typography>
              
              <Grid container spacing={3} sx={{ mb: 4 }}>
                <Grid item xs={12} md={6}>
                  <FormControl fullWidth variant="outlined">
                    <InputLabel>{t('general.theme.title')}</InputLabel>
                    <Select
                      value={interfaceConfig.theme}
                      onChange={(e) => handleInterfaceConfigChange('theme', e.target.value)}
                      label={t('general.theme.title')}
                      disabled={loading}
                    >
                      <MenuItem value="light">{t('general.theme.options.light')}</MenuItem>
                      <MenuItem value="dark">{t('general.theme.options.dark')}</MenuItem>
                      <MenuItem value="system">{t('general.theme.options.system')}</MenuItem>
                    </Select>
                  </FormControl>
                  <Typography variant="caption" color="textSecondary" sx={{ mt: 1, display: 'block' }}>
                    {t('general.theme.description')}
                  </Typography>
                </Grid>
                <Grid item xs={12} md={6}>
                  {renderThemePreview(interfaceConfig.theme)}
                </Grid>
              </Grid>
              
              <Divider sx={{ my: 3 }} />
              
              <Typography variant="subtitle1" sx={{ 
                display: 'flex', 
                alignItems: 'center', 
                mb: 2,
                fontWeight: 600,
                color: theme.palette.primary.main
              }}>
                <AutoAwesomeIcon fontSize="small" sx={{ mr: 1 }} />
                {t('interface.animations.title')}
              </Typography>
              
              <Grid container spacing={3} sx={{ mb: 4 }}>
                <Grid item xs={12}>
                  <FormControlLabel
                    control={
                      <Switch
                        checked={interfaceConfig.animations}
                        onChange={(e) => handleInterfaceConfigChange('animations', e.target.checked)}
                        disabled={loading}
                      />
                    }
                    label={
                      <Box>
                        <Typography>{t('interface.animations.title')}</Typography>
                        <Typography variant="caption" color="textSecondary">
                          {t('interface.animations.description')}
                        </Typography>
                      </Box>
                    }
                  />
                </Grid>
              </Grid>
              
              <Divider sx={{ my: 3 }} />
              
              <Typography variant="subtitle1" sx={{ 
                display: 'flex', 
                alignItems: 'center', 
                mb: 2,
                fontWeight: 600,
                color: theme.palette.primary.main
              }}>
                <FormatSizeIcon fontSize="small" sx={{ mr: 1 }} />
                {t('interface.density.title')}
              </Typography>
              
              <Grid container spacing={3}>
                <Grid item xs={12} md={6}>
                  <FormControl fullWidth variant="outlined">
                    <InputLabel>{t('interface.density.title')}</InputLabel>
                    <Select
                      value={interfaceConfig.density}
                      onChange={(e) => handleInterfaceConfigChange('density', e.target.value)}
                      label={t('interface.density.title')}
                      disabled={loading}
                    >
                      <MenuItem value="compact">{t('interface.density.options.compact')}</MenuItem>
                      <MenuItem value="standard">{t('interface.density.options.standard')}</MenuItem>
                      <MenuItem value="comfortable">{t('interface.density.options.comfortable')}</MenuItem>
                    </Select>
                  </FormControl>
                  <Typography variant="caption" color="textSecondary" sx={{ mt: 1, display: 'block' }}>
                    {t('interface.density.description')}
                  </Typography>
                </Grid>
                <Grid item xs={12} md={6}>
                  {renderDensityPreview(interfaceConfig.density)}
                </Grid>
              </Grid>
            </>
          )}
        </CardContent>
      </Card>

      {/* Notificação de sucesso */}
      <Snackbar 
        open={!!successMessage} 
        autoHideDuration={6000} 
        onClose={() => setSuccessMessage(null)}
        anchorOrigin={{ vertical: 'top', horizontal: 'center' }}
      >
        <Alert onClose={() => setSuccessMessage(null)} severity="success" sx={{ width: '100%' }}>
          {successMessage}
        </Alert>
      </Snackbar>
    </Box>
  );
};

export default InterfaceConfigPanel;
