import React, { ReactNode, useState, useEffect, useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { 
  AppBar, 
  Box, 
  CssBaseline, 
  Drawer, 
  IconButton, 
  Toolbar, 
  Typography, 
  Divider, 
  List, 
  ListItem, 
  ListItemButton, 
  ListItemIcon, 
  ListItemText,
  Menu,
  MenuItem,
  Avatar,
  Badge,
  useTheme,
  useMediaQuery,
  Paper,
  Tooltip,
  alpha,
  CircularProgress,
  Breadcrumbs,
  Link as MuiLink,
  Button,
  Alert
} from '@mui/material';
import { api } from '../../services/api';
import {
  Menu as MenuIcon,
  ChevronLeft as ChevronLeftIcon,
  Dashboard as DashboardIcon,
  People as PeopleIcon,
  Storage as StorageIcon,
  VpnKey as VpnKeyIcon,
  ListAlt as ListAltIcon,
  History as HistoryIcon,
  Settings as SettingsIcon,
  Person as PersonIcon,
  Logout as LogoutIcon,
  Language as LanguageIcon,
  Notifications as NotificationsIcon,
  Shield as ShieldIcon,
  SyncAlt as SyncIcon,
  CheckCircle as CheckCircleIcon,
  HelpOutline as HelpOutlineIcon,
  NavigateNext as NavigateNextIcon,
  Assessment,
  Home as HomeIcon,
  Close as CloseIcon,
  Warning as WarningIcon
} from '@mui/icons-material';
import { useNavigate, useLocation, Link as RouterLink } from 'react-router-dom';
import notificationService, { Notification } from '../../services/notificationService';
import { authService } from '../../services/auth';
import { licenseService, getBaseUrl } from '../../services/api';
// Commented out framer-motion import until package is installed
// import { motion, AnimatePresence } from 'framer-motion';

const drawerWidth = 280;

interface MainLayoutProps {
  children: ReactNode;
  onLogout?: () => void;
}

const MainLayout: React.FC<MainLayoutProps> = ({ children, onLogout = () => {} }) => {
  const theme = useTheme();
  const { t, i18n } = useTranslation(['navigation', 'discrepancy', 'common', 'permissions', 'notifications']);
  const navigate = useNavigate();
  const location = useLocation();
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const [open, setOpen] = useState(!isMobile);
  const [anchorEl, setAnchorEl] = useState<null | HTMLElement>(null);
  const [notificationAnchorEl, setNotificationAnchorEl] = useState<null | HTMLElement>(null);
  const [languageAnchorEl, setLanguageAnchorEl] = useState<null | HTMLElement>(null);
  
  // Notification state
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [unreadCount, setUnreadCount] = useState<number>(0);
  const [loading, setLoading] = useState<boolean>(false);
  const [isRoleValidated, setIsRoleValidated] = useState<boolean>(false);
  
  // License state
  const [licenseStatus, setLicenseStatus] = useState<any>(null);
  const [showLicenseBanner, setShowLicenseBanner] = useState<boolean>(false);
  
  // Version state
  const [appVersion, setAppVersion] = useState<string>('1.4.19');

  const handleDrawerToggle = () => {
    setOpen(!open);
  };

  const handleProfileMenuOpen = (event: React.MouseEvent<HTMLElement>) => {
    setAnchorEl(event.currentTarget);
  };

  const handleMenuClose = () => {
    setAnchorEl(null);
  };

  const handleNotificationMenuOpen = (event: React.MouseEvent<HTMLElement>) => {
    setNotificationAnchorEl(event.currentTarget);
  };

  const handleNotificationMenuClose = () => {
    setNotificationAnchorEl(null);
  };
  
  const handleNotificationClick = (id: string) => {
    markAsRead(id);
    handleNotificationMenuClose();
  };

  const handleLanguageMenuOpen = (event: React.MouseEvent<HTMLElement>) => {
    setLanguageAnchorEl(event.currentTarget);
  };

  const handleLanguageMenuClose = () => {
    setLanguageAnchorEl(null);
  };

  const changeLanguage = (lng: string) => {
    // Importamos a função do i18n.ts mas não temos acesso direta, então usamos i18n diretamente
    i18n.changeLanguage(lng);
    localStorage.setItem('language', lng); // Persistir o idioma escolhido
    handleLanguageMenuClose();
  };

  const handleLogout = () => {
    onLogout();
    handleMenuClose();
  };

  const navigateTo = (path: string) => {
    // Remover quaisquer hashes na URL atual antes de navegar
    const cleanPath = path.split('#')[0];
    navigate(cleanPath);
    if (isMobile) {
      setOpen(false);
    }
  };

  // Fetch notification data
  const fetchNotifications = async () => {
    setLoading(true);
    try {
      const response = await notificationService.getNotifications();
      if (response.success && response.notifications) {
        setNotifications(response.notifications);
        setUnreadCount(response.unreadCount || 0);
      }
    } catch (error) {
      console.error('Error fetching notifications:', error);
    } finally {
      setLoading(false);
    }
  };

  // Fetch unread count only
  const fetchUnreadCount = async () => {
    try {
      const count = await notificationService.getUnreadCount();
      setUnreadCount(count);
    } catch (error) {
      console.error('Error fetching unread count:', error);
    }
  };

  // Mark a notification as read
  const markAsRead = async (id: string) => {
    try {
      const success = await notificationService.markAsRead(id);
      if (success) {
        // Update local state
        setNotifications(prev => 
          prev.map(notification => 
            notification.id === id 
              ? { ...notification, isRead: true } 
              : notification
          )
        );
        fetchUnreadCount(); // Update count
      }
    } catch (error) {
      console.error('Error marking notification as read:', error);
    }
  };

  // Handle viewing all notifications
  const handleViewAllNotifications = () => {
    handleNotificationMenuClose();
    // This would navigate to a notifications page if one exists
    // navigate('/notifications');
  };

  useEffect(() => {
    if (isMobile) {
      setOpen(false);
    } else {
      setOpen(true);
    }
  }, [isMobile]);
  
  // Verificar status da licença ao montar o componente
  useEffect(() => {
    const checkLicenseStatus = async () => {
      try {
        const response = await licenseService.getLicenseStatus();
        setLicenseStatus(response);
        
        // Mostrar banner se não houver licença
        if (response.status === 'no_license' || response.demo_mode) {
          setShowLicenseBanner(true);
        }
      } catch (error) {
        console.error('Error checking license status:', error);
      }
    };
    
    checkLicenseStatus();
    
    // Verificar licença a cada 5 minutos
    const interval = setInterval(checkLicenseStatus, 300000);
    
    return () => clearInterval(interval);
  }, []);
  
  // Buscar versão do sistema
  useEffect(() => {
    const fetchVersion = async () => {
      try {
        const response = await api.get('/api/version');
        if (response.data?.version) {
          setAppVersion(response.data.version);
        }
      } catch (error) {
        console.error('Error fetching version:', error);
      }
    };
    
    fetchVersion();
  }, []);
  
  // Fetch notifications only when needed with optimized polling
  useEffect(() => {
    let mounted = true;
    
    // Função para verificar notificações quando necessário
    const checkNotifications = async () => {
      if (!mounted) return;
      
      if (notificationAnchorEl) {
        // Menu de notificações está aberto - buscar detalhes completos
        await fetchNotifications();
      } else if (!unreadCount) {
        // Se não temos contagem ainda, buscar apenas o contador
        // que é uma operação mais leve
        await fetchUnreadCount();
      }
    };
    
    // Executar verificação inicial
    checkNotifications();
    
    // Setup polling - mas com frequência reduzida e apenas quando o componente está visível
    const interval = setInterval(() => {
      // Verificar se o documento está visível para o usuário
      // para evitar atualizações desnecessárias quando o usuário não está vendo a interface
      if (document.visibilityState === 'visible') {
        fetchUnreadCount();
      }
    }, 300000); // 5 minutos
    
    // Limpar recursos quando o componente é desmontado
    return () => {
      mounted = false;
      clearInterval(interval);
    };
  }, [notificationAnchorEl]);

  // Define all menu items with their required roles
  // Using useMemo to recreate menu items when language changes
  const allMenuItems = useMemo(() => [
    { 
      text: t('navigation:dashboard'), 
      icon: <DashboardIcon />, 
      path: '/dashboard',
      roles: [] // Empty array means available to all authenticated users
    },
    { 
      text: t('navigation:servers'), // Atualizado: "databases" -> "servers"
      icon: <StorageIcon />, 
      path: '/servers', // Atualizado: "/databases" -> "/servers"
      roles: ['admin', 'approver']
    },
    { 
      text: t('navigation:users'), 
      icon: <PeopleIcon />, 
      path: '/users',
      roles: ['admin']
    },
    { 
      text: t('navigation:permissions'), 
      icon: <VpnKeyIcon />, 
      path: '/permissions',
      roles: ['admin', 'approver']
    },
    { 
      text: t('permissions:userPermissions.title'), 
      icon: <VpnKeyIcon />, 
      path: '/user_permissions',
      roles: ['requester'] // Only for requesters
    },
    { 
      text: t('navigation:requests'), 
      icon: <ListAltIcon />, 
      path: '/requests',
      roles: [] // Available to all users
    },
    { 
      text: t('navigation:logs'), 
      icon: <HistoryIcon />, 
      path: '/logs',
      roles: ['admin', 'approver']
    },
    { 
      text: t('navigation:reports'), 
      icon: <Assessment />, 
      path: '/reports/user-queries',
      roles: ['admin', 'approver']
    },
    { 
      text: t('navigation:queryAudit'), 
      icon: <HistoryIcon />, 
      path: '/query-audit',
      roles: ['admin', 'power_user']
    },
    { 
      text: t('navigation:sync'), 
      icon: <SyncIcon />, 
      path: '/sync',
      roles: ['admin']
    },
    { 
      text: t('discrepancy:dashboard'), 
      icon: <WarningIcon />, 
      path: '/discrepancies',
      roles: ['admin']
    },
    { 
      text: t('navigation:settings'), 
      icon: <SettingsIcon />, 
      path: '/settings',
      roles: ['admin']
    },
    // Audit link removed - now part of settings
  ], [t, i18n.language]); // Recreate when language changes
  
  // State for user role and filtered menu items
  const [userRole, setUserRole] = useState<string | null>(null);
  const [menuItems, setMenuItems] = useState<Array<any>>([]);
  const [userProfile, setUserProfile] = useState<any>(null);
  
  // Effect to get the user role and filter menu items - optimized to reduce API calls
  useEffect(() => {
    let mounted = true;
    
    const getUserInfo = async () => {
      if (!mounted) return;
      
      try {
        // Sempre validar role crítica com o servidor
        console.log('[MainLayout] Starting user validation...');
        const serverUser = await authService.getCurrentUserFromServer();
        
        console.log('[MainLayout] Server response:', {
          serverUser,
          mounted,
          hasUser: !!serverUser,
          hasRole: serverUser?.role ? true : false
        });
        
        if (serverUser && serverUser.role) {
          // Verificar se o componente ainda está montado antes de atualizar o estado
          if (mounted) {
            console.log('[MainLayout] Setting userProfile:', {
              username: serverUser.username,
              avatar_url: serverUser.avatar_url,
              full_data: serverUser
            });
            setUserRole(serverUser.role.toLowerCase());
            setUserProfile(serverUser);
          }
          console.log('[MainLayout] User data validated from server:', { 
            username: serverUser.username, 
            role: serverUser.role,
            avatar_url: serverUser.avatar_url,
            validated: true,
            mounted: mounted
          });
          
          // Atualizar localStorage com dados validados
          localStorage.setItem('currentUser', JSON.stringify(serverUser));
        } else {
          // Diagnosticar por que não conseguiu validar
          console.log('[MainLayout] Server validation incomplete:', {
            mounted,
            serverUser,
            serverUserRole: serverUser?.role,
            reason: !mounted ? 'component unmounted' : !serverUser ? 'no user data' : 'no role'
          });
          
          // Se não conseguir validar com servidor mas temos dados do servidor, usar esses dados
          if (serverUser && serverUser.role) {
            console.log('[MainLayout] Using server data despite mounted state');
            const userRole = serverUser.role.toLowerCase();
            
            // Se o componente está desmontado, não podemos atualizar o estado
            // mas podemos salvar no localStorage para a próxima vez
            if (mounted) {
              setUserRole(userRole);
              setUserProfile(serverUser);
            }
            return; // Sair aqui, pois temos dados válidos do servidor
          }
          
          // Se não conseguir validar com servidor, usar dados locais
          const userJson = localStorage.getItem('currentUser');
          console.log('[MainLayout] Checking localStorage...', { 
            hasLocalData: !!userJson 
          });
          
          if (userJson) {
            try {
              const user = JSON.parse(userJson);
              console.log('[MainLayout] Local user data:', {
                username: user?.username,
                role: user?.role,
                isCriticalRole: user?.role ? ['admin', 'approver'].includes(user.role.toLowerCase()) : false
              });
              
              // Se o componente está montado, podemos atualizar o estado
              if (mounted) {
                // Para roles não-críticas, pode usar do localStorage
                if (user && user.role && !['admin', 'approver'].includes(user.role.toLowerCase())) {
                  setUserRole(user.role.toLowerCase());
                  setUserProfile(user);
                  console.log('[MainLayout] Using non-critical role from localStorage:', user.role);
                } else {
                  // Para roles críticas, usar padrão seguro
                  setUserRole('user');
                  setUserProfile({ ...user, role: 'user' });
                  console.warn('[MainLayout] Critical role not validated, using safe default. User:', {
                    username: user?.username,
                    originalRole: user?.role
                  });
                }
              }
            } catch (e) {
              console.error('[MainLayout] Error parsing user data:', e);
              if (mounted) {
                setUserRole('user');
              }
            }
          } else {
            console.log('[MainLayout] No user data in localStorage, using default role');
            if (mounted) {
              setUserRole('user');
            }
          }
        }
      } catch (error) {
        console.error('[MainLayout] Error getting user role:', error);
        console.error('[MainLayout] Error details:', {
          message: error instanceof Error ? error.message : String(error),
          stack: error instanceof Error ? error.stack : undefined,
          type: error instanceof Error ? error.constructor.name : typeof error
        });
        // Em caso de erro, usar role mais restritiva
        setUserRole('user');
      }
    };
    
    // Executar a verificação inicial
    getUserInfo();
    
    // Adiciona listener para atualização de dados do usuário no localStorage
    const handleStorageChange = (e: StorageEvent) => {
      if (e.key === 'currentUser' && e.newValue) {
        // Se o currentUser foi atualizado, atualizar o perfil local
        try {
          const updatedUser = JSON.parse(e.newValue);
          if (mounted) {
            setUserProfile(updatedUser);
            console.log('User profile updated from storage event', {
              avatar_url: updatedUser.avatar_url,
              username: updatedUser.username
            });
          }
        } catch (err) {
          console.error('Error parsing user data from storage event:', err);
        }
      }
    };
    
    // Adiciona listener para quando o documento ficar visível novamente
    // Isso permite atualizar dados quando o usuário retorna para a aplicação
    const handleVisibilityChange = () => {
      if (document.visibilityState === 'visible') {
        // Atualizar apenas a contagem de notificações não lidas ao retornar para a aplicação
        fetchUnreadCount();
        // Também recarregar o perfil do usuário ao retornar à visibilidade
        getUserInfo();
      }
    };
    
    // Listener para evento customizado de atualização de perfil
    const handleUserProfileUpdated = (e: CustomEvent) => {
      if (e.detail && mounted) {
        getUserInfo(); // Recarregar dados do usuário
        console.log('User profile updated from custom event');
      }
    };
    
    // Registrar os listeners
    window.addEventListener('storage', handleStorageChange);
    window.addEventListener('userProfileUpdated', handleUserProfileUpdated as EventListener);
    document.addEventListener('visibilitychange', handleVisibilityChange);
    
    // Polling para detectar mudanças no mesmo tab (onde storage events não funcionam)
    const checkUserProfileInterval = setInterval(() => {
      const currentUserJson = localStorage.getItem('currentUser');
      if (currentUserJson) {
        try {
          const currentUser = JSON.parse(currentUserJson);
          // Comparar apenas o avatar_url para evitar atualizações desnecessárias
          if (currentUser.avatar_url !== userProfile?.avatar_url) {
            setUserProfile(currentUser);
            console.log('User avatar updated from localStorage polling', {
              old_avatar_url: userProfile?.avatar_url,
              new_avatar_url: currentUser.avatar_url,
              full_user: currentUser
            });
          }
        } catch (err) {
          console.error('Error parsing user data during polling:', err);
        }
      }
    }, 1000); // Verificar a cada 1 segundo
    
    // Limpeza ao desmontar
    return () => {
      mounted = false;
      window.removeEventListener('storage', handleStorageChange);
      window.removeEventListener('userProfileUpdated', handleUserProfileUpdated as EventListener);
      document.removeEventListener('visibilitychange', handleVisibilityChange);
      clearInterval(checkUserProfileInterval);
    };
  }, [userProfile?.avatar_url]);
  
  // Effect to filter menu items based on user role
  useEffect(() => {
    if (userRole === null) {
      // Show only items available to all users while role is being determined
      setMenuItems(allMenuItems.filter(item => item.roles.length === 0));
      return;
    }
    
    // Filter menu items based on role
    const filteredItems = allMenuItems.filter(item => {
      // Items with empty roles array are accessible to all
      if (item.roles.length === 0) return true;
      
      // Otherwise, check if user role matches any of the allowed roles
      // Make case-insensitive comparison and account for substring matching
      return item.roles.some(role => 
        userRole.toLowerCase().includes(role.toLowerCase()) || 
        role.toLowerCase().includes(userRole.toLowerCase())
      );
    });
    
    setMenuItems(filteredItems);
  }, [userRole, allMenuItems]); // Added allMenuItems as dependency

  const isActive = (path: string) => {
    return location.pathname === path || location.pathname.startsWith(`${path}/`);
  };

  return (
    <Box sx={{ display: 'flex', minHeight: '100vh' }}>
      <CssBaseline />
      <AppBar
        position="fixed"
        sx={{
          zIndex: theme.zIndex.drawer + 1,
          transition: theme.transitions.create(['width', 'margin'], {
            easing: theme.transitions.easing.sharp,
            duration: theme.transitions.duration.leavingScreen,
          }),
          background: 'white',
          color: theme.palette.text.primary,
          boxShadow: '0px 2px 4px rgba(0, 0, 0, 0.1)',
          ...(open && {
            width: { md: `calc(100% - ${drawerWidth}px)` },
            marginLeft: { md: `${drawerWidth}px` },
            transition: theme.transitions.create(['width', 'margin'], {
              easing: theme.transitions.easing.sharp,
              duration: theme.transitions.duration.enteringScreen,
            }),
          }),
        }}
      >
        <Toolbar sx={{ height: '70px', minHeight: '70px' }}>
          <IconButton
            edge="start"
            aria-label="open drawer"
            onClick={handleDrawerToggle}
            sx={{ 
              mr: 2,
              color: theme.palette.primary.main
            }}
          >
            {open ? <ChevronLeftIcon /> : <MenuIcon />}
          </IconButton>
          
          {/* Breadcrumb navigation */}
          <Breadcrumbs 
            aria-label="breadcrumb" 
            separator={<NavigateNextIcon fontSize="small" color="primary" />}
            sx={{ 
              display: 'flex', 
              alignItems: 'center',
              flexGrow: 1,
              color: theme.palette.text.primary,
              '& .MuiBreadcrumbs-separator': {
                color: alpha(theme.palette.primary.main, 0.7)
              },
              '& a': {
                color: theme.palette.primary.main,
                '&:hover': {
                  color: theme.palette.primary.dark
                }
              }
            }}
          >
            <MuiLink
              component={RouterLink}
              to="/dashboard"
              color="inherit"
              sx={{ 
                display: 'flex', 
                alignItems: 'center',
                textDecoration: 'none'
              }}
            >
              <HomeIcon sx={{ mr: 0.5 }} fontSize="small" />
              {t('navigation:dashboard')}
            </MuiLink>
            
            {/* Render current page path based on location */}
            {(() => {
              const path = location.pathname;
              
              if (path.includes('/requests')) {
                return (
                  <Typography color="inherit" sx={{ display: 'flex', alignItems: 'center' }}>
                    <ListAltIcon sx={{ mr: 0.5 }} fontSize="small" />
                    {t('navigation:requests')}
                  </Typography>
                );
              } else if (path === '/user_permissions') {
                return (
                  <Typography color="inherit" sx={{ display: 'flex', alignItems: 'center' }}>
                    <VpnKeyIcon sx={{ mr: 0.5 }} fontSize="small" />
                    {t('permissions:userPermissions.title')}
                  </Typography>
                );
              } else if (path.includes('/permissions')) {
                return (
                  <Typography color="inherit" sx={{ display: 'flex', alignItems: 'center' }}>
                    <VpnKeyIcon sx={{ mr: 0.5 }} fontSize="small" />
                    {t('navigation:permissions')}
                  </Typography>
                );
              } else if (path.includes('/servers')) {
                return (
                  <Typography color="inherit" sx={{ display: 'flex', alignItems: 'center' }}>
                    <StorageIcon sx={{ mr: 0.5 }} fontSize="small" />
                    {t('navigation:servers')}
                  </Typography>
                );
              } else if (path.includes('/databases')) {
                return (
                  <Typography color="inherit" sx={{ display: 'flex', alignItems: 'center' }}>
                    <StorageIcon sx={{ mr: 0.5 }} fontSize="small" />
                    {t('navigation:databases')}
                  </Typography>
                );
              } else if (path.includes('/users')) {
                return (
                  <Typography color="inherit" sx={{ display: 'flex', alignItems: 'center' }}>
                    <PeopleIcon sx={{ mr: 0.5 }} fontSize="small" />
                    {t('navigation:users')}
                  </Typography>
                );
              } else if (path.includes('/logs')) {
                return (
                  <Typography color="inherit" sx={{ display: 'flex', alignItems: 'center' }}>
                    <HistoryIcon sx={{ mr: 0.5 }} fontSize="small" />
                    {t('navigation:logs')}
                  </Typography>
                );
              } else if (path.includes('/sync')) {
                return (
                  <Typography color="inherit" sx={{ display: 'flex', alignItems: 'center' }}>
                    <SyncIcon sx={{ mr: 0.5 }} fontSize="small" />
                    {t('navigation:sync')}
                  </Typography>
                );
              } else if (path.includes('/settings')) {
                return (
                  <Typography color="inherit" sx={{ display: 'flex', alignItems: 'center' }}>
                    <SettingsIcon sx={{ mr: 0.5 }} fontSize="small" />
                    {t('navigation:settings')}
                  </Typography>
                );
              } else if (path.includes('/profile')) {
                return (
                  <Typography color="inherit" sx={{ display: 'flex', alignItems: 'center' }}>
                    <PersonIcon sx={{ mr: 0.5 }} fontSize="small" />
                    {t('navigation:profile')}
                  </Typography>
                );
              }
              
              return null;
            })()}
          </Breadcrumbs>

          <Box sx={{ display: 'flex' }}>
            <Tooltip title="Change Language">
              <IconButton
                onClick={handleLanguageMenuOpen}
                sx={{ color: theme.palette.primary.main }}
              >
                <LanguageIcon />
              </IconButton>
            </Tooltip>
            <Tooltip title="Notifications">
              <IconButton
                onClick={handleNotificationMenuOpen}
                sx={{ color: theme.palette.primary.main }}
              >
                <Badge badgeContent={unreadCount} color="error">
                  <NotificationsIcon />
                </Badge>
              </IconButton>
            </Tooltip>
            <Tooltip title="User Profile">
              <IconButton
                edge="end"
                onClick={handleProfileMenuOpen}
                sx={{ color: theme.palette.primary.main }}
              >
                <Avatar
                  src={(() => {
                    console.log('[MainLayout] Avatar render check:', {
                      userProfile: userProfile,
                      hasUserProfile: !!userProfile,
                      avatar_url: userProfile?.avatar_url,
                      hasAvatarUrl: !!userProfile?.avatar_url
                    });
                    
                    if (!userProfile?.avatar_url) return '';
                    
                    // Avatar URLs já vêm com /uploads/avatars/, não precisa do baseUrl
                    const avatarUrl = `${userProfile.avatar_url}?t=${Date.now()}`;
                    
                    console.log('[MainLayout] Avatar URL generated:', avatarUrl);
                    return avatarUrl;
                  })()}
                  imgProps={{
                    onError: (e) => {
                      console.error('Failed to load avatar image in header');
                      // Fallback to initials on error
                      const target = e.target as HTMLImageElement;
                      target.onerror = null; // Prevent recursion
                      target.src = ''; // Clear the src
                    }
                  }}
                  sx={{ 
                    width: 32, 
                    height: 32,
                    border: `2px solid ${theme.palette.secondary.main}`,
                    background: `linear-gradient(135deg, ${theme.palette.primary.light}, ${theme.palette.primary.main})`,
                  }}
                >
                  {/* Mostrar a primeira letra do nome se não tiver foto de perfil */}
                  {(() => {
                    if (userProfile) {
                      // Obter nome completo para iniciais
                      const fullName = userProfile.name || userProfile.username || '';
                      // Se tem nome completo, mostrar iniciais do primeiro e último nome
                      if (fullName.includes(' ')) {
                        const nameParts = fullName.split(' ');
                        return (nameParts[0].charAt(0) + nameParts[nameParts.length - 1].charAt(0)).toUpperCase();
                      }
                      // Caso contrário, mostrar apenas a primeira letra do username
                      return userProfile.username ? userProfile.username.charAt(0).toUpperCase() : 'U';
                    }
                    return 'U';
                  })()}
                </Avatar>
              </IconButton>
            </Tooltip>
          </Box>
        </Toolbar>
      </AppBar>

      <Box
        component="nav"
        sx={{
          width: { md: drawerWidth },
          flexShrink: { md: 0 },
        }}
      >
        <Drawer
          variant={isMobile ? 'temporary' : 'persistent'}
          open={open}
          onClose={handleDrawerToggle}
          sx={{
            '& .MuiDrawer-paper': {
              width: drawerWidth,
              boxSizing: 'border-box',
              background: `linear-gradient(180deg, ${theme.palette.primary.dark} 0%, ${theme.palette.primary.main} 100%)`,
              color: theme.palette.primary.contrastText,
              boxShadow: '0px 0px 20px rgba(0, 0, 0, 0.15)',
            },
          }}
        >
          <Box
            sx={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              padding: theme.spacing(2),
              background: 'white',
              width: '100%',
              height: '70px', // Aumentado para acomodar o logo maior
              boxShadow: '0px 2px 4px rgba(0, 0, 0, 0.1)',
              borderBottom: `1px solid ${alpha(theme.palette.primary.main, 0.1)}`
            }}
          >
            <Box 
              component="img"
              src="/dbmanager_logo.png"
              alt="DB-Manager Logo"
              sx={{ 
                height: '50px', // 25% maior (de 40px para 50px)
                filter: 'drop-shadow(0px 2px 4px rgba(0, 0, 0, 0.2))'
              }}
            />
          </Box>
          <Divider sx={{ backgroundColor: 'rgba(255, 255, 255, 0.1)' }} />
          <Box sx={{ mt: 2 }}>
            <List component="nav">
              {menuItems.map((item) => (
                <Box
                  key={item.path}
                >
                  <ListItem disablePadding>
                    <ListItemButton
                      onClick={() => navigateTo(item.path)}
                      selected={isActive(item.path)}
                      sx={{
                        borderRadius: 2,
                        my: 0.5,
                        mx: 1,
                        color: '#fff',
                        '&.Mui-selected': {
                          backgroundColor: 'rgba(255, 255, 255, 0.15)',
                          backdropFilter: 'blur(10px)',
                          '&:hover': {
                            backgroundColor: 'rgba(255, 255, 255, 0.25)',
                          },
                          '&::before': {
                            content: '""',
                            position: 'absolute',
                            left: 0,
                            top: '25%',
                            height: '50%',
                            width: 4,
                            backgroundColor: theme.palette.secondary.main,
                            borderRadius: '0 4px 4px 0',
                          },
                        },
                      }}
                    >
                      <ListItemIcon sx={{ 
                        color: isActive(item.path) ? theme.palette.secondary.light : '#fff', 
                        minWidth: 40 
                      }}>
                        {item.icon}
                      </ListItemIcon>
                      <ListItemText 
                        primary={item.text} 
                        primaryTypographyProps={{ 
                          fontWeight: isActive(item.path) ? 600 : 400,
                        }}
                      />
                    </ListItemButton>
                  </ListItem>
                </Box>
              ))}
            </List>
          </Box>
          <Box sx={{ flexGrow: 1 }} />
          <Box
            sx={{
              p: 2,
              backgroundColor: alpha(theme.palette.secondary.main, 0.15),
              margin: 2,
              borderRadius: 2,
            }}
          >
            <Typography variant="subtitle2" color="rgba(255, 255, 255, 0.7)">
              Version {appVersion}
            </Typography>
          </Box>
        </Drawer>
      </Box>

      <Box
        component="main"
        sx={{
          backgroundColor: theme.palette.background.default,
          flexGrow: 1,
          minHeight: 'calc(100vh - 64px)', // Ajustado para considerar o zoom e AppBar
          overflow: 'auto',
          display: 'flex',
          flexDirection: 'column',
          pt: { xs: 9, sm: 10 }, // Aumentado para compensar a altura maior do AppBar
        }}
      >
        {/* AnimatePresence removed until framer-motion is installed */}
          <Box
            key={location.pathname}
            sx={{ 
              flex: 1, 
              display: 'flex', 
              flexDirection: 'column' 
            }}
          >
            <Box sx={{ flex: 1, display: 'flex', flexDirection: 'column' }}>
              {/* Banner de aviso quando não houver licença */}
              {showLicenseBanner && (
                <Paper 
                  elevation={0} 
                  sx={{ 
                    p: 2, 
                    m: 2,
                    mb: 0,
                    backgroundColor: theme.palette.error.main,
                    color: 'white',
                    borderRadius: 2,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between'
                  }}
                >
                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                    <ShieldIcon />
                    <Typography variant="body1" sx={{ fontWeight: 600 }}>
                      Sistema em modo demonstração - Solicite uma licença trial para desbloquear todos os recursos
                    </Typography>
                  </Box>
                  <Box sx={{ display: 'flex', gap: 1 }}>
                    <Button 
                      variant="contained" 
                      size="small"
                      onClick={() => navigate('/settings/license')}
                      sx={{ 
                        backgroundColor: 'white',
                        color: theme.palette.error.main,
                        '&:hover': {
                          backgroundColor: alpha(theme.palette.common.white, 0.9)
                        }
                      }}
                    >
                      Gerenciar Licença
                    </Button>
                    <IconButton 
                      size="small" 
                      onClick={() => setShowLicenseBanner(false)}
                      sx={{ color: 'white' }}
                    >
                      <CloseIcon fontSize="small" />
                    </IconButton>
                  </Box>
                </Paper>
              )}
              
              <Box sx={{ p: { xs: 2, sm: 3 }, flex: 1 }}>
                {children}
              </Box>
            </Box>
          </Box>
        {/* End of AnimatePresence replacement */}
      </Box>

      <Menu
        anchorEl={anchorEl}
        open={Boolean(anchorEl)}
        onClose={handleMenuClose}
        transformOrigin={{ horizontal: 'right', vertical: 'top' }}
        anchorOrigin={{ horizontal: 'right', vertical: 'bottom' }}
        PaperProps={{
          sx: {
            borderRadius: 2,
            minWidth: 180,
            mt: 1,
            boxShadow: '0px 8px 20px rgba(42, 49, 67, 0.1)',
          }
        }}
      >
        <MenuItem onClick={() => { handleMenuClose(); navigate('/profile'); }}>
          <ListItemIcon>
            <PersonIcon fontSize="small" />
          </ListItemIcon>
          <ListItemText primary={t('navigation:profile')} />
        </MenuItem>
        <MenuItem onClick={() => { handleMenuClose(); navigate('/documentation'); }}>
          <ListItemIcon>
            <HelpOutlineIcon fontSize="small" />
          </ListItemIcon>
          <ListItemText primary={t('navigation:documentation')} />
        </MenuItem>
        <MenuItem onClick={() => { handleMenuClose(); navigate('/settings'); }}>
          <ListItemIcon>
            <SettingsIcon fontSize="small" />
          </ListItemIcon>
          <ListItemText primary={t('navigation:settings')} />
        </MenuItem>
        <Divider />
        <MenuItem onClick={handleLogout}>
          <ListItemIcon>
            <LogoutIcon fontSize="small" />
          </ListItemIcon>
          <ListItemText primary={t('navigation:logout')} />
        </MenuItem>
      </Menu>

      <Menu
        anchorEl={notificationAnchorEl}
        open={Boolean(notificationAnchorEl)}
        onClose={handleNotificationMenuClose}
        transformOrigin={{ horizontal: 'right', vertical: 'top' }}
        anchorOrigin={{ horizontal: 'right', vertical: 'bottom' }}
        PaperProps={{
          sx: {
            borderRadius: 2,
            minWidth: 280,
            maxWidth: 320,
            mt: 1,
            boxShadow: '0px 8px 20px rgba(42, 49, 67, 0.1)',
          }
        }}
      >
        <Box sx={{ p: 2, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <Typography variant="h6" sx={{ fontSize: '1rem', fontWeight: 600 }}>
            {t('notifications:title')}
          </Typography>
          {unreadCount > 0 && (
            <Badge badgeContent={unreadCount} color="error" sx={{ ml: 1 }}>
              <NotificationsIcon fontSize="small" />
            </Badge>
          )}
        </Box>
        <Divider />
        
        {loading ? (
          <Box sx={{ display: 'flex', justifyContent: 'center', py: 2 }}>
            <CircularProgress size={24} />
          </Box>
        ) : notifications.length > 0 ? (
          <>
            {notifications.map((notification) => (
              <MenuItem 
                key={notification.id} 
                onClick={() => handleNotificationClick(notification.id)} 
                sx={{ 
                  py: 1.5,
                  backgroundColor: notification.isRead ? 'inherit' : alpha(theme.palette.primary.light, 0.1),
                  '&:hover': {
                    backgroundColor: notification.isRead ? alpha(theme.palette.primary.light, 0.05) : alpha(theme.palette.primary.light, 0.15),
                  }
                }}
              >
                <Box sx={{ display: 'flex', alignItems: 'flex-start', width: '100%' }}>
                  <Box sx={{ flexGrow: 1 }}>
                    <Typography variant="body2" sx={{ fontWeight: notification.isRead ? 400 : 600 }}>
                      {notification.title}
                    </Typography>
                    <Typography variant="caption" component="div" color="text.secondary" sx={{ display: 'block', mt: 0.5 }}>
                      {notification.message && notification.message.length > 60 
                        ? `${notification.message.substring(0, 60)}...` 
                        : notification.message}
                    </Typography>
                    <Typography variant="caption" component="div" color="text.secondary" sx={{ display: 'block', mt: 0.5 }}>
                      {new Date(notification.createdAt).toLocaleString()}
                    </Typography>
                  </Box>
                  {notification.isRead && (
                    <Box sx={{ ml: 1, color: theme.palette.success.main }}>
                      <CheckCircleIcon fontSize="small" />
                    </Box>
                  )}
                </Box>
              </MenuItem>
            ))}
          </>
        ) : (
          <Box sx={{ py: 2, px: 2, textAlign: 'center' }}>
            <Typography variant="body2" color="text.secondary">
              {t('notifications:empty')}
            </Typography>
          </Box>
        )}
        
        <Divider />
        <MenuItem sx={{ justifyContent: 'center' }} onClick={handleViewAllNotifications}>
          <Typography variant="body2" color="primary">
            {t('notifications:viewAll')}
          </Typography>
        </MenuItem>
      </Menu>

      <Menu
        anchorEl={languageAnchorEl}
        open={Boolean(languageAnchorEl)}
        onClose={handleLanguageMenuClose}
        transformOrigin={{ horizontal: 'right', vertical: 'top' }}
        anchorOrigin={{ horizontal: 'right', vertical: 'bottom' }}
        PaperProps={{
          sx: {
            borderRadius: 2,
            minWidth: 150,
            mt: 1,
            boxShadow: '0px 8px 20px rgba(42, 49, 67, 0.1)',
          }
        }}
      >
        <MenuItem onClick={() => changeLanguage('en')}>
          English
        </MenuItem>
        <MenuItem onClick={() => changeLanguage('pt')}>
          Português
        </MenuItem>
        <MenuItem onClick={() => changeLanguage('es')}>
          Español
        </MenuItem>
      </Menu>
    </Box>
  );
};

export default MainLayout;
