// Tipos de banco de dados suportados
export enum DatabaseType {
  MYSQL = 'mysql',
  POSTGRESQL = 'postgres',
  MSSQL = 'mssql',
  ORACLE = 'oracle',
}

// Tipos de acesso
export enum AccessType {
  READ = 'read',
  READWRITE = 'readwrite',
  ADMIN = 'admin',
}

// Interface de usuário
export interface User {
  id: string;
  username: string;
  email?: string;
}

// Interface de servidor
export interface DatabaseServer {
  id: string;
  name: string;
  type: string; // mysql, postgres, mssql, etc.
  host?: string;
  port?: number;
  databases?: DatabaseInfo[]; // Novo: lista de bancos disponíveis no servidor
  environment?: 'dev' | 'qa' | 'prod'; // Ambiente do servidor
}

// Interface para informações de banco de dados
export interface DatabaseInfo {
  name: string;
  schemas?: string[]; // Schemas disponíveis (apenas PostgreSQL)
}

// Interface de banco de dados para o formulário
export interface Database {
  id: string;
  name: string;
  serverId: string;
  type?: string;       // Tipo de banco de dados (postgres, mysql, mssql)
  server_id?: string;  // Para compatibilidade com APIs legadas
  server_name?: string; // Para compatibilidade com APIs legadas
}

// Interface de schema para o formulário
export interface Schema {
  name: string;
  databaseName: string;
}

// Interface de tabela
export interface Table {
  name: string;
  serverId: string;
  databaseName?: string; // Nome do banco para referência
  schemaName?: string;   // Nome do schema para PostgreSQL
}

// Estado do formulário
export interface RequestFormState {
  userId: string;
  serverId: string;
  databaseName: string;  // Nome do banco selecionado
  schemaName: string;    // Schema selecionado (para PostgreSQL)
  tables: string[];
  accessType: AccessType;
  justification: string;
  expirationDate: string;
  isPermanent: boolean;

  // Metadados para controle de fluxo
  databaseType: DatabaseType | null;
  currentStep: number;
  previousStep: number;
  direction: 'left' | 'right' | 'none';
  errors: Record<string, string>;
  isLoading: boolean;

  // Dados auxiliares
  users: User[];
  servers: DatabaseServer[];
  databases: Database[];
  tablesList: Table[];
  schemas: string[];
  schemasMap: Record<string, string[]>; // Mapa de schemas para PostgreSQL (database => schemas[])
  
  // Service user fields
  isServiceUser: boolean;
  serviceUserName: string;
  serviceUserDescription: string;
}

// Ações para o reducer
export type RequestFormAction =
  | { type: 'SET_USER'; payload: string }
  | { type: 'SET_SERVER'; payload: string }
  | { type: 'SET_DATABASE_NAME'; payload: string } // Novo: definir nome do banco
  | { type: 'SET_DATABASE'; payload: string } // Mantido para compatibilidade
  | { type: 'SET_SCHEMA'; payload: string }
  | { type: 'SET_TABLES'; payload: string[] }
  | { type: 'SET_ACCESS_TYPE'; payload: AccessType }
  | { type: 'SET_JUSTIFICATION'; payload: string }
  | { type: 'SET_EXPIRATION_DATE'; payload: string }
  | { type: 'SET_IS_PERMANENT'; payload: boolean }
  | { type: 'SET_DATABASE_TYPE'; payload: DatabaseType | null }
  | { type: 'SET_CURRENT_STEP'; payload: number }
  | { type: 'SET_PREVIOUS_STEP'; payload: number }
  | { type: 'SET_DIRECTION'; payload: 'left' | 'right' | 'none' }
  | { type: 'SET_ERRORS'; payload: Record<string, string> }
  | { type: 'SET_LOADING'; payload: boolean }
  | { type: 'SET_USERS'; payload: User[] }
  | { type: 'SET_SERVERS'; payload: DatabaseServer[] }
  | { type: 'SET_DATABASES'; payload: Database[] }
  | { type: 'SET_TABLES_DATA'; payload: Table[] }
  | { type: 'SET_SCHEMAS'; payload: string[] }
  | { type: 'SET_SCHEMAS_MAP'; payload: Record<string, string[]> }
  | { type: 'SET_SERVICE_USER_INFO'; payload: { isServiceUser: boolean; serviceUserName: string; serviceUserDescription: string } }
  | { type: 'RESET_FORM' }
  | { type: 'INITIALIZE_FORM'; payload: Partial<RequestFormState> };

// Props para o componente principal
export interface RequestFormProps {
  open: boolean;
  onClose: () => void;
  onSubmit: (formData?: any) => void;
  currentUser?: User;
  defaultServer?: {
    id: string;
    name: string;
    type: string;
  };
  defaultDatabase?: Database; // Para compatibilidade com código existente
  editingPermission?: any;
}

// Props compartilhadas para os componentes de etapa
export interface StepProps {
  state: RequestFormState;
  dispatch: React.Dispatch<RequestFormAction>;
  onNext: () => void;
  onBack: () => void;
}