    '0px 18px 40px rgba(42, 49, 67, 0.22)',
    '0px 20px 44px rgba(42, 49, 67, 0.24)',
    '0px 22px 48px rgba(42, 49, 67, 0.26)',
    '0px 24px 52px rgba(42, 49, 67, 0.28)',
    '0px 26px 56px rgba(42, 49, 67, 0.3)',
    '0px 28px 60px rgba(42, 49, 67, 0.32)',
    '0px 30px 64px rgba(42, 49, 67, 0.34)',
