// Componentes comuns para todos os temas
const getComponentOverrides = (mode: PaletteMode) => {
  const isDark = mode === 'dark';
  const primaryColor = isDark ? '#5A6978' : '#36404A';
  const primaryDarkColor = isDark ? '#455A64' : '#1E272E';
  const secondaryColor = isDark ? '#FFA270' : '#FF7043';
  const secondaryDarkColor = isDark ? '#FF5722' : '#C63F17';
  const backgroundColor = isDark ? '#1E1E1E' : '#FFFFFF';
  const textPrimaryColor = isDark ? '#FFFFFF' : '#2A3143';
  
  return {
    components: {
      MuiAppBar: {
        styleOverrides: {
          root: {
            backgroundColor: isDark ? '#1A1A1A' : '#FFFFFF',
            color: textPrimaryColor,
            boxShadow: isDark 
              ? '0px 2px 8px rgba(0, 0, 0, 0.3)' 
              : '0px 2px 8px rgba(42, 49, 67, 0.05)',
          },
        },
      },
      MuiButton: {
        styleOverrides: {
          root: {
            borderRadius: 8,
            padding: '10px 20px',
            boxShadow: 'none',
            transition: 'all 0.2s ease-in-out',
            '&:hover': {
              transform: 'translateY(-2px)',
              boxShadow: isDark 
                ? '0px 4px 12px rgba(0, 0, 0, 0.3)' 
                : '0px 4px 12px rgba(42, 49, 67, 0.08)',
            },
          },
          contained: {
            '&:hover': {
              boxShadow: isDark 
                ? '0px 6px 16px rgba(0, 0, 0, 0.4)' 
                : '0px 6px 16px rgba(42, 49, 67, 0.12)',
            },
          },
          containedPrimary: {
            backgroundImage: `linear-gradient(135deg, ${primaryColor} 0%, ${primaryDarkColor} 100%)`,
            '&:hover': {
              backgroundImage: `linear-gradient(135deg, ${primaryColor} 20%, ${primaryDarkColor} 120%)`,
            },
          },
          containedSecondary: {
            backgroundImage: `linear-gradient(135deg, ${secondaryColor} 0%, ${secondaryDarkColor} 100%)`,
            '&:hover': {
              backgroundImage: `linear-gradient(135deg, ${secondaryColor} 20%, ${secondaryDarkColor} 120%)`,
            },
          },
          outlined: {
            borderWidth: 2,
            '&:hover': {
              borderWidth: 2,
            },
          },
        },
      },
      MuiCard: {
        styleOverrides: {
          root: {
            borderRadius: 16,
            boxShadow: isDark 
              ? '0px 4px 20px rgba(0, 0, 0, 0.3)' 
              : '0px 4px 20px rgba(42, 49, 67, 0.08)',
            transition: 'all 0.3s ease-in-out',
            '&:hover': {
              boxShadow: isDark 
                ? '0px 8px 30px rgba(0, 0, 0, 0.4)' 
                : '0px 8px 30px rgba(42, 49, 67, 0.12)',
            },
          },
        },
      },
      MuiCardHeader: {
        styleOverrides: {
          root: {
            padding: 20,
          },
        },
      },
      MuiCardContent: {
        styleOverrides: {
          root: {
            padding: 20,
            '&:last-child': {
              paddingBottom: 20,
            },
          },
        },
      },
      MuiChip: {
        styleOverrides: {
          root: {
            borderRadius: 8,
            fontWeight: 500,
          },
          colorPrimary: {
            backgroundColor: alpha(primaryColor, isDark ? 0.2 : 0.1),
            color: primaryColor,
          },
          colorSecondary: {
            backgroundColor: alpha(secondaryColor, isDark ? 0.2 : 0.1),
            color: secondaryColor,
          },
        },
      },
      MuiTextField: {
        defaultProps: {
          variant: 'outlined',
        },
        styleOverrides: {
          root: {
            '& .MuiOutlinedInput-root': {
              borderRadius: 12,
              transition: 'all 0.2s ease-in-out',
              '&:hover .MuiOutlinedInput-notchedOutline': {
                borderColor: primaryColor,
              },
              '&.Mui-focused .MuiOutlinedInput-notchedOutline': {
                borderWidth: 2,
              },
            },
          },
        },
      },
      MuiSelect: {
        styleOverrides: {
          outlined: {
            borderRadius: 12,
          },
        },
      },
      MuiTableContainer: {
        styleOverrides: {
          root: {
            borderRadius: 16,
            boxShadow: isDark 
              ? '0px 4px 20px rgba(0, 0, 0, 0.2)' 
              : '0px 4px 20px rgba(42, 49, 67, 0.05)',
            overflow: 'hidden',
          },
        },
      },
      MuiTableHead: {
        styleOverrides: {
          root: {
            backgroundColor: alpha(primaryColor, isDark ? 0.15 : 0.05),
            '& .MuiTableCell-head': {
              color: primaryColor,
              fontWeight: 600,
            },
          },
        },
      },
      MuiTableRow: {
        styleOverrides: {
          root: {
            transition: 'background-color 0.2s ease-in-out',
            '&:hover': {
              backgroundColor: alpha(primaryColor, isDark ? 0.05 : 0.02),
            },
            '&:last-child td': {
              borderBottom: 0,
            },
          },
        },
      },
      MuiTableCell: {
        styleOverrides: {
          root: {
            padding: '16px 20px',
            borderColor: isDark ? '#303030' : '#E4E9F2',
          },
        },
      },
      MuiTabs: {
        styleOverrides: {
          indicator: {
            height: 3,
            borderTopLeftRadius: 3,
            borderTopRightRadius: 3,
          },
        },
      },
      MuiTab: {
        styleOverrides: {
          root: {
            textTransform: 'none',
            fontWeight: 600,
            padding: '12px 20px',
            minHeight: 48,
          },
        },
      },
      MuiDialog: {
        styleOverrides: {
          paper: {
            borderRadius: 16,
            boxShadow: isDark 
              ? '0px 10px 40px rgba(0, 0, 0, 0.4)' 
              : '0px 10px 40px rgba(42, 49, 67, 0.1)',
          },
        },
      },
      MuiDialogTitle: {
        styleOverrides: {
          root: {
            fontSize: '1.25rem',
            fontWeight: 600,
            padding: '20px 24px',
          },
        },
      },
      MuiDialogContent: {
        styleOverrides: {
          root: {
            padding: 24,
          },
        },
      },
      MuiDialogActions: {
        styleOverrides: {
          root: {
            padding: '16px 24px',
          },
        },
      },
      MuiPaper: {
        styleOverrides: {
          elevation1: {
            boxShadow: isDark 
              ? '0px 4px 20px rgba(0, 0, 0, 0.2)' 
              : '0px 4px 20px rgba(42, 49, 67, 0.05)',
          },
        },
      },
      MuiDrawer: {
        styleOverrides: {
          paper: {
            border: 'none',
            backgroundImage: isDark 
              ? `linear-gradient(180deg, #1A1A1A 0%, #121212 100%)` 
              : `linear-gradient(180deg, ${primaryDarkColor} 0%, ${primaryColor} 95%, ${secondaryColor} 100%)`,
            color: isDark ? '#FFFFFF' : '#FFFFFF',
            boxShadow: '0px 0px 20px rgba(0, 0, 0, 0.15)',
          },
        },
      },
      MuiListItemButton: {
        styleOverrides: {
          root: {
            borderRadius: 8,
            margin: '4px 8px',
            '&.Mui-selected': {
              backgroundColor: alpha('#ffffff', isDark ? 0.1 : 0.15),
              '&:hover': {
                backgroundColor: alpha('#ffffff', isDark ? 0.15 : 0.25),
              },
            },
            '&:hover': {
              backgroundColor: alpha('#ffffff', isDark ? 0.05 : 0.1),
            },
          },
        },
      },
      MuiAlert: {
        styleOverrides: {
          root: {
            borderRadius: 12,
            boxShadow: isDark 
              ? '0px 4px 15px rgba(0, 0, 0, 0.3)' 
              : '0px 4px 15px rgba(42, 49, 67, 0.05)',
          },
          standardSuccess: {
            backgroundColor: alpha('#2ACE7E', isDark ? 0.15 : 0.1),
            color: isDark ? '#66D9A2' : '#1F9D60',
            '& .MuiAlert-icon': {
              color: '#2ACE7E',
            },
          },
          standardError: {
            backgroundColor: alpha('#FF4D4D', isDark ? 0.15 : 0.1),
            color: isDark ? '#FF7A7A' : '#C73F3F',
            '& .MuiAlert-icon': {
              color: '#FF4D4D',
            },
          },
          standardWarning: {
            backgroundColor: alpha('#FFA319', isDark ? 0.15 : 0.1),
            color: isDark ? '#FFB74D' : '#C67916',
            '& .MuiAlert-icon': {
              color: '#FFA319',
            },
          },
          standardInfo: {
            backgroundColor: alpha('#3BADF9', isDark ? 0.15 : 0.1),
            color: isDark ? '#6DC1FA' : '#2B87C6',
            '& .MuiAlert-icon': {
              color: '#3BADF9',
            },
          },
        },
      },
    },
  };
};

// Função para criar o tema baseado no modo
export const createAppTheme = (mode: PaletteMode) => {
  const designTokens = getDesignTokens(mode);
  const componentsOverrides = getComponentOverrides(mode);
  
  return createTheme(designTokens as any, componentsOverrides as any);
};

// Tema padrão (para compatibilidade)
const theme = createAppTheme('light');

export default theme;