import React, { useState, useEffect, useCallback, useRef } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  Stepper,
  Step,
  StepLabel,
  StepConnector,
  Box,
  Typography,
  CircularProgress,
  styled,
  Paper
} from '@mui/material';
import { useTranslation } from 'react-i18next';
import { useRequestForm } from './hooks/useRequestForm';
import { RequestFormProps, DatabaseType } from './types';
import { serverService } from '../../services/api';
import ActionButtons from './components/shared/ActionButtons';

// Importar componentes de etapa
import UserStep from './components/steps/UserStep';
import ServerStep from './components/steps/ServerStep';
import DatabaseStep from './components/steps/DatabaseStep';
import SchemaStep from './components/steps/SchemaStep';
import TableStep from './components/steps/TableStep';
import AccessTypeStep from './components/steps/AccessTypeStep';
import DurationStep from './components/steps/DurationStep';
import JustificationStep from './components/steps/JustificationStep';
import ReviewStep from './components/steps/ReviewStep';

// Componentes estilizados
const ColoredStepConnector = styled(StepConnector)(({ theme }) => ({
  [`&.MuiStepConnector-active`]: {
    [`& .MuiStepConnector-line`]: {
      borderColor: theme.palette.primary.main,
    },
  },
  [`&.MuiStepConnector-completed`]: {
    [`& .MuiStepConnector-line`]: {
      borderColor: theme.palette.primary.main,
    },
  },
}));

// Estilizando o step label
const AnimatedStepLabel = styled(StepLabel)(({ theme }) => ({
  [`& .MuiStepLabel-label`]: {
    transition: 'all 0.3s ease-in-out',
  },
  [`& .MuiStepLabel-label.Mui-active`]: {
    color: theme.palette.primary.main,
    fontWeight: 'bold',
    transform: 'scale(1.05)',
  },
  [`& .MuiStepLabel-label.Mui-completed`]: {
    color: theme.palette.primary.dark,
  },
}));

/**
 * Componente principal do formulário de solicitação - Versão otimizada
 */
const RequestForm: React.FC<RequestFormProps> = ({
  open,
  onClose,
  onSubmit,
  currentUser,
  defaultServer,
  defaultDatabase,
  editingPermission,
}) => {
  // Evitar múltiplas montagens e renderizações
  const didInitialize = useRef(false);
  
  // Debug log
  console.log('=== RequestForm component rendered ===');
  console.log('RequestForm props:', { open, currentUser, defaultServer, editingPermission });
  
  // Uso básico de i18n para tradução
  const { t } = useTranslation(['requests', 'common', 'error']);
  
  // Usar hook personalizado para gerenciar o estado (centralizado)
  const {
    state,
    dispatch,
    nextStep,
    prevStep,
    validateForm,
    prepareSubmitData,
    resetForm,
    fetchDatabases,
    fetchSchemas,
    fetchTables,
  } = useRequestForm(currentUser, defaultServer);

  // Efeito de inicialização, executado apenas uma vez quando o modal abre
  useEffect(() => {
    // Inicialização apenas uma vez quando o modal é aberto
    if (open && !didInitialize.current) {
      resetForm();
      didInitialize.current = true;
      
      // Se estiver editando uma permissão existente, inicializar os campos
      if (editingPermission) {
        console.log("Inicializando formulário com dados existentes:", editingPermission);
        
        // Determinar o tipo de permissão baseado nas operações
        let accessType = 'read';
        if (editingPermission.operations) {
          const ops = Array.isArray(editingPermission.operations) ? 
            editingPermission.operations.map((op: string) => op.toUpperCase()) : 
            [editingPermission.operations.toUpperCase()];
            
          if (ops.includes('DELETE')) {
            accessType = 'admin';
          } else if (ops.includes('UPDATE') || ops.includes('INSERT')) {
            accessType = 'readwrite';
          }
        }
        
        // Determinar se é permanente
        const isPermanent = !editingPermission.expires_at || 
          editingPermission.expires_at === "0001-01-01T00:00:00Z" || 
          editingPermission.expires_at === "0001-01-01T00:00:00" ||
          new Date(editingPermission.expires_at).getFullYear() <= 1;
        
        // Formatar data de expiração se necessário
        const expirationDate = isPermanent ? '' : 
          editingPermission.expires_at ? 
          editingPermission.expires_at.substring(0, 10) : '';
        
        // Determinar tabelas
        const tables = Array.isArray(editingPermission.tables) ? 
          editingPermission.tables : 
          [editingPermission.table];
        
        // Inicializar valores no formulário sem usar setTimeout
        dispatch({
          type: 'INITIALIZE_FORM',
          payload: {
            userId: editingPermission.user_id || '',
            serverId: editingPermission.server_id || editingPermission.database_id || '',
            tables,
            accessType: accessType as any,
            justification: editingPermission.reason || '',
            expirationDate,
            isPermanent,
            schemaName: editingPermission.schema_name || 'public'
          },
        });
        
        // Definir o tipo de banco de dados
        const dbType = editingPermission.server_type?.toLowerCase() === 'postgres' || 
          editingPermission.type?.toLowerCase() === 'postgres'
          ? DatabaseType.POSTGRESQL 
          : editingPermission.server_type?.toLowerCase() === 'mssql' || 
            editingPermission.type?.toLowerCase() === 'mssql'
          ? DatabaseType.MSSQL
          : editingPermission.server_type?.toLowerCase() === 'oracle' || 
            editingPermission.type?.toLowerCase() === 'oracle'
          ? DatabaseType.ORACLE
          : DatabaseType.MYSQL;
        
        dispatch({ type: 'SET_DATABASE_TYPE', payload: dbType });
        
        // Carregar dados relacionados (sem setTimeout)
        if (editingPermission.server_id || editingPermission.database_id) {
          const serverId = editingPermission.server_id || editingPermission.database_id;
          fetchDatabases(serverId);
          
          if (editingPermission.database_id && dbType) {
            // Verificar se é PostgreSQL/MSSQL/Oracle ou outro tipo
            if (dbType === DatabaseType.POSTGRESQL || dbType === DatabaseType.MSSQL || dbType === DatabaseType.ORACLE) {
              // Para PostgreSQL/MSSQL/Oracle, precisamos do schema também
              const schema = editingPermission.schema || (dbType === DatabaseType.POSTGRESQL ? 'public' : dbType === DatabaseType.MSSQL ? 'dbo' : 'HR_dbmanager');
              dispatch({ type: 'SET_SCHEMA', payload: schema });
              serverService.getTables(editingPermission.server_id || editingPermission.database_id,
                                     editingPermission.database_name || '',
                                     schema)
                .then(response => {
                  if (response && response.tables) {
                    const tables = response.tables.map((tableName: string) => ({
                      name: tableName,
                      serverId: editingPermission.server_id || editingPermission.database_id,
                      databaseName: editingPermission.database_name || '',
                      schemaName: schema
                    }));
                    dispatch({ type: 'SET_TABLES_DATA', payload: tables });
                  }
                })
                .catch(err => console.error("Error fetching tables:", err));
            } else {
              // Para outros tipos, buscar tabelas diretamente
              serverService.getTables(editingPermission.server_id || editingPermission.database_id,
                                     editingPermission.database_name || '')
                .then(response => {
                  if (response && response.tables) {
                    const tables = response.tables.map((tableName: string) => ({
                      name: tableName,
                      serverId: editingPermission.server_id || editingPermission.database_id,
                      databaseName: editingPermission.database_name || ''
                    }));
                    dispatch({ type: 'SET_TABLES_DATA', payload: tables });
                  }
                })
                .catch(err => console.error("Error fetching tables:", err));
            }
          }
        }
      }
    }
    
    // Limpar o flag quando o modal é fechado
    if (!open) {
      didInitialize.current = false;
    }
  }, [open, editingPermission, resetForm, fetchDatabases, fetchTables]);

  // Determinar as etapas baseado no tipo de banco de dados
  const getSteps = useCallback(() => {
    const commonStepsStart = [
      { label: t('wizard.steps.user') },
      { label: t('wizard.steps.server') },
      { label: t('wizard.steps.database') },
    ];
    
    const commonStepsEnd = [
      { label: t('wizard.steps.accessType') },
      { label: t('wizard.steps.duration') },
      { label: t('wizard.steps.justification') },
      { label: t('wizard.steps.review') },
    ];
    
    // Se for PostgreSQL, MSSQL ou Oracle, adicionar a etapa de schema após o banco de dados
    if (state.databaseType === DatabaseType.POSTGRESQL || state.databaseType === DatabaseType.MSSQL || state.databaseType === DatabaseType.ORACLE) {
      return [
        ...commonStepsStart,
        { label: t('wizard.steps.schema') },
        { label: t('wizard.steps.table') },
        ...commonStepsEnd,
      ];
    }
    
    // Para MySQL ou quando o tipo de banco não foi definido ainda
    return [
      ...commonStepsStart,
      { label: t('wizard.steps.table') },
      ...commonStepsEnd,
    ];
  }, [state.databaseType, t]);
  
  // Obter as etapas atuais com base no tipo de banco
  const steps = getSteps();
  
  // Função para lidar com o envio do formulário
  const handleSubmit = useCallback(() => {
    if (validateForm()) {
      const formData = prepareSubmitData();
      console.log('Submitting form data:', formData);
      
      // Chamar o callback de sucesso, passando os dados do formulário
      onSubmit(formData);
    }
  }, [validateForm, prepareSubmitData, onSubmit]);
  
  // Renderizar o conteúdo da etapa atual com base no passo atual
  const renderCurrentStep = useCallback(() => {
    // Verificar se o banco de dados usa schemas (PostgreSQL, MSSQL e Oracle)
    const usesSchemas = state.databaseType === DatabaseType.POSTGRESQL || state.databaseType === DatabaseType.MSSQL || state.databaseType === DatabaseType.ORACLE;
    
    // Verificar se o botão próximo deve estar desabilitado na etapa de justificativa
    const isJustificationStep = 
      (usesSchemas && state.currentStep === 7) || 
      (!usesSchemas && state.currentStep === 6);
    
    const isNextDisabled = isJustificationStep && 
      (!state.justification.trim() || state.justification.trim().length < 10);
    
    // Renderizar o componente adequado com base na etapa atual e tipo de banco
    switch (state.currentStep) {
      case 0: // UserStep
        return <UserStep state={state} dispatch={dispatch} onNext={nextStep} onBack={prevStep} />;
        
      case 1: // ServerStep
        return <ServerStep state={state} dispatch={dispatch} onNext={nextStep} onBack={prevStep} />;
        
      case 2: // DatabaseStep
        return <DatabaseStep state={state} dispatch={dispatch} onNext={nextStep} onBack={prevStep} />;
        
      case 3: // SchemaStep (PostgreSQL/MSSQL) ou TableStep (MySQL)
        if (usesSchemas) {
          return <SchemaStep state={state} dispatch={dispatch} onNext={nextStep} onBack={prevStep} />;
        } else {
          return <TableStep state={state} dispatch={dispatch} onNext={nextStep} onBack={prevStep} />;
        }
        
      case 4: // TableStep (PostgreSQL/MSSQL) ou AccessTypeStep (MySQL)
        if (usesSchemas) {
          return <TableStep state={state} dispatch={dispatch} onNext={nextStep} onBack={prevStep} />;
        } else {
          return <AccessTypeStep state={state} dispatch={dispatch} onNext={nextStep} onBack={prevStep} />;
        }
        
      case 5: // AccessTypeStep (PostgreSQL/MSSQL) ou DurationStep (MySQL)
        if (usesSchemas) {
          return <AccessTypeStep state={state} dispatch={dispatch} onNext={nextStep} onBack={prevStep} />;
        } else {
          return <DurationStep state={state} dispatch={dispatch} onNext={nextStep} onBack={prevStep} />;
        }
        
      case 6: // DurationStep (PostgreSQL/MSSQL) ou JustificationStep (MySQL)
        if (usesSchemas) {
          return <DurationStep state={state} dispatch={dispatch} onNext={nextStep} onBack={prevStep} />;
        } else {
          return <JustificationStep state={state} dispatch={dispatch} onNext={nextStep} onBack={prevStep} />;
        }
        
      case 7: // JustificationStep (PostgreSQL/MSSQL) ou ReviewStep (MySQL)
        if (usesSchemas) {
          return <JustificationStep state={state} dispatch={dispatch} onNext={nextStep} onBack={prevStep} />;
        } else {
          return <ReviewStep state={state} dispatch={dispatch} onNext={handleSubmit} onBack={prevStep} />;
        }
        
      case 8: // ReviewStep (PostgreSQL apenas)
        return <ReviewStep state={state} dispatch={dispatch} onNext={handleSubmit} onBack={prevStep} />;
        
      default:
        return (
          <Box display="flex" justifyContent="center" alignItems="center" minHeight={300}>
            <Typography variant="h6" color="error">
              {t('error:invalidStep', {step: state.currentStep})}
            </Typography>
          </Box>
        );
    }
  }, [
    state.currentStep, 
    state.databaseType,
    state, 
    dispatch, 
    nextStep, 
    prevStep, 
    handleSubmit,
    t
  ]);

  // Verificar se o componente ainda está montado
  const isMounted = useRef(true);
  useEffect(() => {
    return () => {
      isMounted.current = false;
    };
  }, []);

  return (
    <Dialog
      open={open}
      onClose={onClose}
      maxWidth="lg"
      fullWidth
      scroll="paper"
      aria-labelledby="request-form-dialog-title"
      disableEnforceFocus
      disableRestoreFocus
    >
      <DialogTitle id="request-form-dialog-title">
        {editingPermission 
          ? t('editTitle')
          : t('newTitle')}
      </DialogTitle>

      <DialogContent dividers sx={{ 
        height: '75vh', 
        overflow: 'hidden',
        display: 'flex',
        flexDirection: 'column'
      }}>
        {/* Stepper para mostrar o progresso */}
        <Stepper 
          activeStep={state.currentStep} 
          alternativeLabel
          connector={<ColoredStepConnector />}
        >
          {steps.map((step, index) => (
            <Step key={step.label} completed={index < state.currentStep}>
              <AnimatedStepLabel>{step.label}</AnimatedStepLabel>
            </Step>
          ))}
        </Stepper>

        {/* Conteúdo da etapa atual */}
        <Paper 
          elevation={0} 
          sx={{ 
            p: 2, 
            mt: 2, 
            mb: 2, 
            flex: 1,
            minHeight: 0,
            display: 'flex',
            alignItems: state.isLoading ? 'center' : 'stretch',
            justifyContent: state.isLoading ? 'center' : 'flex-start',
            overflow: 'hidden'
          }}
        >
          {state.isLoading ? (
            <CircularProgress />
          ) : (
            <Box width="100%" height="100%">
              {renderCurrentStep()}
            </Box>
          )}
        </Paper>

        {/* Botões de ação (anterior, próximo, enviar) */}
        <ActionButtons
          currentStep={state.currentStep}
          totalSteps={steps.length}
          onBack={prevStep}
          onNext={state.currentStep === steps.length - 1 ? handleSubmit : nextStep}
          onCancel={onClose}
          isLastStep={state.currentStep === steps.length - 1}
          isLoading={state.isLoading}
          nextDisabled={
            // Verificar se o botão próximo deve estar desabilitado na etapa de justificativa
            (((state.databaseType === DatabaseType.POSTGRESQL || state.databaseType === DatabaseType.MSSQL || state.databaseType === DatabaseType.ORACLE) && state.currentStep === 7) || 
            (state.databaseType !== DatabaseType.POSTGRESQL && state.databaseType !== DatabaseType.MSSQL && state.databaseType !== DatabaseType.ORACLE && state.currentStep === 6)) && 
            (!state.justification.trim() || state.justification.trim().length < 10)
          }
          backLabel={String(t('common:back'))}
          nextLabel={state.currentStep === steps.length - 1 
            ? String(t('common:confirm'))
            : String(t('common:next'))}
          cancelLabel={String(t('common:cancel'))}
        />
      </DialogContent>
    </Dialog>
  );
};

export default React.memo(RequestForm);
