import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useTranslation } from '../../i18n/i18n';
import {
  Box,
  Typography,
  Paper,
  TextField,
  Button,
  CircularProgress,
  Alert,
  Grid,
  Container,
  LinearProgress,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
  Fade
} from '@mui/material';
import {
  AccountCircle as UserIcon,
  VpnKey as PasswordIcon,
  Check as CheckIcon,
  Error as ErrorIcon,
  Lock as LockIcon,
  LockOpen as LockOpenIcon,
  SecurityOutlined as SecurityIcon
} from '@mui/icons-material';
import { userService } from '../../services/api';

// Interface for user activation form data
interface ActivationFormData {
  fullName: string;
  password: string;
  confirmPassword: string;
}

// Interface for password strength requirements
interface PasswordRequirement {
  id: string;
  label: string;
  met: boolean;
  regex: RegExp;
}

const UserActivationPage: React.FC = () => {
  const { token } = useParams<{ token: string }>();
  const navigate = useNavigate();
  const { t } = useTranslation(['activation', 'common']);
  const [loading, setLoading] = useState(false);
  const [validToken, setValidToken] = useState(false);
  const [tokenChecked, setTokenChecked] = useState(false);
  const [tokenData, setTokenData] = useState<any>(null);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);
  const [formData, setFormData] = useState<ActivationFormData>({
    fullName: '',
    password: '',
    confirmPassword: ''
  });
  const [passwordStrength, setPasswordStrength] = useState(0);
  const [formErrors, setFormErrors] = useState<{[key: string]: string}>({});
  // Add state for password requirements
  const [passwordReqs, setPasswordReqs] = useState<PasswordRequirement[]>([]);

  // Initialize password requirements
  useEffect(() => {
    setPasswordReqs([
      {
        id: 'length',
        label: t('passwordRequirements.minLength'),
        met: false,
        regex: /.{12,}/
      },
      {
        id: 'uppercase',
        label: t('passwordRequirements.uppercase'),
        met: false,
        regex: /[A-Z]/
      },
      {
        id: 'number',
        label: t('passwordRequirements.number'),
        met: false,
        regex: /[0-9]/
      }
    ]);
  }, [t]);

  // Check the token validity on component mount
  useEffect(() => {
    if (token) {
      validateToken();
    } else {
      setError(t('tokenMissing'));
      setTokenChecked(true);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [token]);

  // Validate activation token
  const validateToken = async () => {
    setLoading(true);
    try {
      // API call to validate token
      const response = await userService.validateActivationToken(token || '');
      console.log('Token validation response:', response);
      
      if (response && response.valid) {
        setValidToken(true);
        setTokenData(response.data || {});
      } else {
        setError(t('tokenInvalid'));
      }
    } catch (err) {
      console.error('Error validating token:', err);
      setError(t('tokenError'));
    } finally {
      setLoading(false);
      setTokenChecked(true);
    }
  };

  // Handle form input changes
  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
    
    // Clear errors while typing
    if (formErrors[name]) {
      setFormErrors(prev => ({ ...prev, [name]: '' }));
    }
    
    // Check password strength and requirements
    if (name === 'password') {
      updatePasswordRequirements(value);
    }
    
    // Check confirm password match
    if (name === 'confirmPassword' && formData.password !== value) {
      setFormErrors(prev => ({
        ...prev,
        confirmPassword: t('passwordRequirements.mismatch')
      }));
    } else if (name === 'confirmPassword') {
      setFormErrors(prev => ({ ...prev, confirmPassword: '' }));
    }
  };

  // Update password requirements and strength
  const updatePasswordRequirements = (password: string) => {
    let metCount = 0;
    
    // Create a new array with updated requirements
    const updatedReqs = passwordReqs.map(req => {
      const isMet = req.regex.test(password);
      
      // Log for debugging
      console.log(`Password requirement: ${req.id}, Regex: ${req.regex}, Met: ${isMet}, Password: ${password.substring(0, 1)}***`);
      
      if (isMet) metCount++;
      
      // Return a new object with the updated met status
      return { ...req, met: isMet };
    });
    
    // Update the state with the new array
    setPasswordReqs(updatedReqs);
    
    // Calculate strength percentage
    const strengthPercentage = (metCount / updatedReqs.length) * 100;
    setPasswordStrength(strengthPercentage);
    
    // Log overall result
    console.log(`Password strength: ${strengthPercentage}%, Met requirements: ${metCount}/${updatedReqs.length}`);
  };

  // Get color for password strength indicator
  const getStrengthColor = () => {
    if (passwordStrength <= 33) return 'error';
    if (passwordStrength <= 66) return 'warning';
    return 'success';
  };

  // Validate the form before submission
  const validateForm = (): boolean => {
    const errors: {[key: string]: string} = {};
    
    if (!formData.fullName || formData.fullName.trim() === '') {
      errors.fullName = t('common:validation.required');
    }
    
    if (!formData.password || formData.password.trim() === '') {
      errors.password = t('common:validation.required');
    } else {
      // Check if all password requirements are met directly - don't rely on passwordReqs state
      const lengthMet = /.{12,}/.test(formData.password);
      const uppercaseMet = /[A-Z]/.test(formData.password);
      const numberMet = /[0-9]/.test(formData.password);
      
      console.log("Form validation - password requirements:");
      console.log(`- Length (12+ chars): ${lengthMet}`);
      console.log(`- Uppercase: ${uppercaseMet}`);
      console.log(`- Number: ${numberMet}`);
      
      const allRequirementsMet = lengthMet && uppercaseMet && numberMet;
      
      // Also log the current state of requirements
      console.log("Requirements from state:", passwordReqs.map(r => ({ 
        id: r.id, 
        met: r.met 
      })));
      
      if (!allRequirementsMet) {
        errors.password = t('passwordRequirements.requirementsNotMet');
        console.log("Validation failed: Password does not meet all requirements");
      } else {
        console.log("All password requirements met!");
      }
    }
    
    if (!formData.confirmPassword || formData.confirmPassword.trim() === '') {
      errors.confirmPassword = t('common:validation.required');
    } else if (formData.password !== formData.confirmPassword) {
      errors.confirmPassword = t('passwordRequirements.mismatch');
    }
    
    console.log("Form errors:", errors);
    setFormErrors(errors);
    return Object.keys(errors).length === 0;
  };

  // Handle form submission
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!validateForm()) {
      return;
    }
    
    setLoading(true);
    try {
      const activationData = {
        token: token,
        fullName: formData.fullName,
        password: formData.password
      };
      
      console.log('Submitting activation data:', activationData);
      
      // API call to activate account
      const response = await userService.activateAccount(token, activationData);
      console.log('Activation response:', response);
      
      setSuccess(true);
      
      // Redirect to login page after a delay
      setTimeout(() => {
        navigate('/login');
      }, 3000);
      
    } catch (err) {
      console.error('Error activating account:', err);
      setError(t('activationError'));
    } finally {
      setLoading(false);
    }
  };

  // Loading state
  if (!tokenChecked) {
    return (
      <Container maxWidth="sm">
        <Box sx={{ mt: 8, textAlign: 'center' }}>
          <CircularProgress />
          <Typography variant="h6" sx={{ mt: 2 }}>
            {t('checkingToken')}
          </Typography>
        </Box>
      </Container>
    );
  }

  // Error state - invalid token
  if (!validToken) {
    return (
      <Container maxWidth="sm">
        <Paper sx={{ p: 4, mt: 8, textAlign: 'center' }}>
          <ErrorIcon color="error" sx={{ fontSize: 64 }} />
          <Typography variant="h4" color="error" sx={{ mt: 2 }}>
            {t('invalidToken')}
          </Typography>
          <Typography variant="body1" sx={{ mt: 2 }}>
            {error || t('tokenInvalid')}
          </Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mt: 2, mb: 2 }}>
            Error code: {token}
          </Typography>
          <Button 
            variant="contained" 
            sx={{ mt: 3 }}
            onClick={() => navigate('/login')}
          >
            {t('backToLogin')}
          </Button>
        </Paper>
      </Container>
    );
  }

  // Success state - account activated
  if (success) {
    return (
      <Container maxWidth="sm">
        <Paper sx={{ p: 4, mt: 8, textAlign: 'center' }}>
          <CheckIcon color="success" sx={{ fontSize: 64 }} />
          <Typography variant="h4" sx={{ mt: 2, color: 'success.main' }}>
            {t('success')}
          </Typography>
          <Typography variant="body1" sx={{ mt: 2 }}>
            {t('successMessage')}
          </Typography>
          <LinearProgress sx={{ mt: 3 }} />
          <Button 
            variant="contained" 
            sx={{ mt: 3 }}
            onClick={() => navigate('/login')}
          >
            {t('goToLogin')}
          </Button>
        </Paper>
      </Container>
    );
  }

  // Render activation form
  return (
    <Container maxWidth="md">
      <Paper sx={{ p: 4, mt: 8 }}>
        <Grid container spacing={4}>
          <Grid item xs={12} md={5} sx={{ display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center' }}>
            <SecurityIcon sx={{ fontSize: 80, color: 'primary.main', mb: 3 }} />
            <Typography variant="h4" align="center" gutterBottom>
              {t('activateAccount')}
            </Typography>
            <Typography variant="body1" align="center" color="text.secondary">
              {t('welcome')}
            </Typography>
            
            {tokenData && (
              <Box sx={{ mt: 3, width: '100%' }}>
                <Alert severity="info" sx={{ mb: 2 }}>
                  <Typography variant="subtitle2">
                    {t('invitedEmail')}
                  </Typography>
                  <Typography variant="body2" sx={{ fontWeight: 'bold' }}>
                    {tokenData.email}
                  </Typography>
                  
                  <Typography variant="subtitle2" sx={{ mt: 1 }}>
                    {t('username')}
                  </Typography>
                  <Typography variant="body2" sx={{ fontWeight: 'bold' }}>
                    {tokenData.username}
                  </Typography>
                </Alert>
              </Box>
            )}
          </Grid>
          
          <Grid item xs={12} md={7}>
            {error && (
              <Alert severity="error" sx={{ mb: 3 }}>
                {error}
              </Alert>
            )}
            
            <Box component="form" onSubmit={handleSubmit}>
              <TextField
                margin="normal"
                required
                fullWidth
                label={t('fullName')}
                name="fullName"
                value={formData.fullName}
                onChange={handleInputChange}
                disabled={loading}
                error={Boolean(formErrors.fullName)}
                helperText={formErrors.fullName}
                InputProps={{
                  startAdornment: <UserIcon sx={{ color: 'primary.main', mr: 1 }} />
                }}
              />
              
              <TextField
                margin="normal"
                required
                fullWidth
                label={t('password')}
                name="password"
                type="password"
                value={formData.password}
                onChange={handleInputChange}
                disabled={loading}
                error={Boolean(formErrors.password)}
                helperText={formErrors.password}
                InputProps={{
                  startAdornment: <LockIcon sx={{ color: 'primary.main', mr: 1 }} />
                }}
              />
              
              {/* Password strength indicator */}
              {formData.password && (
                <>
                  <Box sx={{ width: '100%', mt: 1 }}>
                    <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                      <Typography variant="caption" color="text.secondary">
                        {t('passwordRequirements.strength')}
                      </Typography>
                      <Typography 
                        variant="caption" 
                        color={`${getStrengthColor()}.main`} 
                        sx={{ fontWeight: 'bold' }}
                      >
                        {passwordStrength <= 33 && t('passwordRequirements.weak')}
                        {passwordStrength > 33 && passwordStrength <= 66 && t('passwordRequirements.medium')}
                        {passwordStrength > 66 && t('passwordRequirements.strong')}
                      </Typography>
                    </Box>
                    <LinearProgress 
                      variant="determinate" 
                      value={passwordStrength} 
                      color={getStrengthColor() as 'error' | 'warning' | 'success'}
                      sx={{ height: 5, borderRadius: 5 }}
                    />
                  </Box>
                  
                  <List dense sx={{ mt: 1 }}>
                    {passwordReqs.map((req) => (
                      <Fade key={req.id} in={true}>
                        <ListItem dense sx={{ py: 0 }}>
                          <ListItemIcon sx={{ minWidth: 32 }}>
                            {req.met ? (
                              <CheckIcon fontSize="small" color="success" />
                            ) : (
                              <ErrorIcon fontSize="small" color="error" />
                            )}
                          </ListItemIcon>
                          <ListItemText 
                            primary={req.label} 
                            sx={{ 
                              '& .MuiListItemText-primary': { 
                                fontSize: '0.8rem',
                                color: req.met ? 'success.main' : 'text.secondary',
                                fontWeight: req.met ? 'bold' : 'normal',
                                textDecoration: req.met ? 'line-through' : 'none'
                              } 
                            }}
                          />
                        </ListItem>
                      </Fade>
                    ))}
                  </List>
                </>
              )}
              
              <TextField
                margin="normal"
                required
                fullWidth
                label={t('confirmPassword')}
                name="confirmPassword"
                type="password"
                value={formData.confirmPassword}
                onChange={handleInputChange}
                disabled={loading}
                error={Boolean(formErrors.confirmPassword)}
                helperText={formErrors.confirmPassword}
                InputProps={{
                  startAdornment: <LockOpenIcon sx={{ color: 'primary.main', mr: 1 }} />
                }}
              />
              
              <Button
                type="submit"
                fullWidth
                variant="contained"
                size="large"
                disabled={loading || !/.{12,}/.test(formData.password) || !/[A-Z]/.test(formData.password) || !/[0-9]/.test(formData.password)}
                sx={{ mt: 3, mb: 2, py: 1.5 }}
                startIcon={loading ? <CircularProgress size={20} /> : null}
              >
                {loading ? 
                  t('activating') :
                  t('activate')}
              </Button>
            </Box>
          </Grid>
        </Grid>
      </Paper>
    </Container>
  );
};

export default UserActivationPage;