import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import {
  Box,
  Typography,
  Paper,
  Button,
  TextField,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  FormControl,
  InputLabel,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Snackbar,
  Alert,
  IconButton,
  Tooltip,
  CircularProgress,
  Divider,
  useTheme,
  alpha,
  Grid,
  Chip
} from '@mui/material';
import { Edit as EditIcon, Key as KeyIcon, Sync as SyncIcon, VpnKey as PasswordIcon } from '@mui/icons-material';
import { formatDistanceToNow } from 'date-fns';
import { ptBR, enUS } from 'date-fns/locale';
import { syncService } from '../../services/syncService';
import { userService } from '../../services/api';

interface Database {
  id: string;
  name: string;
  type: string;
  host: string;
  port: number;
}

interface UniversalCredential {
  username: string;
  lastUpdated: string;
}

const DatabaseCredentialsSection: React.FC = () => {
  const { t, i18n } = useTranslation(['profile', 'common']);
  const theme = useTheme();
  const [universalCredential, setUniversalCredential] = useState<UniversalCredential | null>(null);
  const [databases, setDatabases] = useState<Database[]>([]);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [successMessage, setSuccessMessage] = useState('');
  const [errorMessage, setErrorMessage] = useState('');
  const [snackbarOpen, setSnackbarOpen] = useState(false);
  
  // Função helper para obter o locale correto do date-fns
  const getDateLocale = () => {
    return i18n.language === 'pt' ? ptBR : enUS;
  };

  // Using t() hook for translations now

  const [userId, setUserId] = useState<string>('');

  useEffect(() => {
    const fetchUserInfo = async () => {
      try {
        const response = await userService.getUserById('me');
        setUserId(response.user.id);
        // Também definir o nome de usuário para usá-lo no formulário
        setUsername(response.user.username || '');
        
        // Check for universal credentials updated timestamp from user response
        console.log("User data received:", response.user);
        if (response.user.universal_credentials_updated_at) {
          console.log("Universal credentials timestamp found:", response.user.universal_credentials_updated_at);
          setUniversalCredential({
            username: response.user.username,
            lastUpdated: response.user.universal_credentials_updated_at
          });
        } else {
          console.log("No universal credentials timestamp found in user data");
          setUniversalCredential(null);
        }
        
        setIsLoading(false);
        fetchDatabases();
      } catch (err) {
        console.error('Error fetching user information:', err);
        setIsLoading(false);
      }
    };

    fetchUserInfo();
  }, []);

  // This function is now obsolete as we get universal credentials directly from user object
  // Keeping an empty function for compatibility until all references are removed
  const fetchUniversalCredential = async (id: string) => {
    // No longer needed as we get this information directly from the user object
  };

  const fetchDatabases = async () => {
    try {
      const response = await syncService.getDatabases();
      setDatabases(response.databases || []);
    } catch (error) {
      console.error('Error fetching databases:', error);
    }
  };

  const handleOpenDialog = () => {
    // Não permitir alteração do username - manter o que foi carregado do usuário atual
    setPassword('');
    setDialogOpen(true);
  };

  const handleCloseDialog = () => {
    setDialogOpen(false);
  };

  // Validação da senha
  const [passwordValid, setPasswordValid] = useState(true);
  const [passwordErrors, setPasswordErrors] = useState<string[]>([]);
  
  const validatePassword = (password: string) => {
    const errors = [];
    
    if (password.length < 8) {
      errors.push(t('common:validation.password.tooShort') as string);
    }
    
    if (!/[A-Z]/.test(password)) {
      errors.push(t('common:validation.password.noUppercase') as string);
    }
    
    if (!/[a-z]/.test(password)) {
      errors.push(t('common:validation.password.noLowercase') as string);
    }
    
    if (!/[0-9]/.test(password)) {
      errors.push(t('common:validation.password.noNumber') as string);
    }
    
    if (!/[^A-Za-z0-9]/.test(password)) {
      errors.push(t('common:validation.password.noSpecial') as string);
    }
    
    setPasswordErrors(errors);
    setPasswordValid(errors.length === 0);
    
    return errors.length === 0;
  };
  
  // Atualizar validação quando a senha mudar
  useEffect(() => {
    if (password) {
      validatePassword(password);
    } else {
      setPasswordValid(true);
      setPasswordErrors([]);
    }
  }, [password]);

  const handleUpdateCredentials = async () => {
    if (!username || !password) {
      setErrorMessage(t('credentialsForm.error.fieldsRequired') as string);
      setSnackbarOpen(true);
      return;
    }
    
    // Validar senha
    if (!validatePassword(password)) {
      setErrorMessage(t('credentialsForm.error.invalidPassword') as string);
      setSnackbarOpen(true);
      return;
    }

    try {
      // We're now updating universal credentials - not specific to a database
      const response = await syncService.updateUniversalCredentials(userId, {
        username,
        password
      });
      
      // Update the universal credential in state with the new timestamp
      setUniversalCredential({
        username: username,
        lastUpdated: new Date().toISOString() // Use current time as we just updated
      });
      
      // Show success message, including info about database sync if available
      if (response && response.message && response.message.includes("sync")) {
        setSuccessMessage(response.message);
      } else {
        setSuccessMessage(t('credentialsSuccess') as string);
      }
      setSnackbarOpen(true);
      handleCloseDialog();
      
    } catch (error) {
      console.error('Error updating universal credentials:', error);
      setErrorMessage(t('credentialsError') as string);
      setSnackbarOpen(true);
    }
  };

  const handleSnackbarClose = () => {
    setSnackbarOpen(false);
  };

  return (
    <>
      <Paper sx={{ p: 3, mt: 3 }}>
        <Box display="flex" justifyContent="space-between" alignItems="center" mb={2}>
          <Typography variant="h6">
            {t('universalCredentials')}
          </Typography>
          <Button
            variant="contained"
            startIcon={<KeyIcon />}
            onClick={handleOpenDialog}
            sx={{ 
              fontWeight: 'bold',
              color: 'white',
              '&:hover': {
                backgroundColor: theme => theme.palette.primary.dark,
              },
              '&.Mui-disabled': {
                backgroundColor: theme => alpha(theme.palette.primary.main, 0.5),
                color: 'rgba(255, 255, 255, 0.8)',
              }
            }}
          >
            {universalCredential 
              ? t('credentialsForm.updateButton')
              : t('credentialsForm.addButton')}
          </Button>
        </Box>

        <Typography variant="body2" color="text.secondary" paragraph>
          {t('universalCredentialsDescription')}
        </Typography>

        {isLoading ? (
          <Box display="flex" justifyContent="center" my={2}>
            <CircularProgress size={24} />
          </Box>
        ) : !universalCredential ? (
          <Typography variant="body2" align="center" sx={{ py: 3 }}>
            {t('noUniversalCredentials')}
          </Typography>
        ) : (
          <Box sx={{ mt: 3 }}>
            <Paper variant="outlined" sx={{ p: 2 }}>
              <Grid container spacing={2}>
                <Grid item xs={12}>
                  <Box display="flex" alignItems="center" mb={1}>
                    <PasswordIcon color="primary" sx={{ mr: 1 }} />
                    <Typography variant="subtitle1" fontWeight="medium">
                      {t('universalCredentialDetails')}
                    </Typography>
                  </Box>
                  <Divider sx={{ mb: 2 }} />
                </Grid>
                
                <Grid item xs={12} sm={6}>
                  <Box>
                    <Typography variant="body2" color="text.secondary">
                      {t('credentialsTable.username')}:
                    </Typography>
                    <Typography variant="body1" fontWeight="medium">
                      {universalCredential.username}
                    </Typography>
                  </Box>
                </Grid>
                
                <Grid item xs={12} sm={6}>
                  <Box>
                    <Typography variant="body2" color="text.secondary">
                      {t('credentialsTable.lastUpdated')}:
                    </Typography>
                    <Typography variant="body1">
                      {formatDistanceToNow(new Date(universalCredential.lastUpdated), { addSuffix: true, locale: getDateLocale() })}
                    </Typography>
                  </Box>
                </Grid>
                
                <Grid item xs={12}>
                  <Box sx={{ mt: 1 }}>
                    <Typography variant="body2" color="text.secondary">
                      {t('credentialsTable.connectedDatabases')}:
                    </Typography>
                    <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5, mt: 1 }}>
                      {databases.length > 0 ? (
                        databases.map((db, index) => (
                          <Chip 
                            key={`${db.name}-${index}`} 
                            label={db.name} 
                            variant="outlined" 
                            size="small"
                            icon={<SyncIcon fontSize="small" />}
                            sx={{ my: 0.5 }}
                          />
                        ))
                      ) : (
                        <Typography variant="body2" color="text.secondary">
                          {t('noDatabases')}
                        </Typography>
                      )}
                    </Box>
                  </Box>
                </Grid>
              </Grid>
            </Paper>
          </Box>
        )}
      </Paper>

      {/* Update Credentials Dialog */}
      <Dialog open={dialogOpen} onClose={handleCloseDialog} maxWidth="sm" fullWidth>
        <DialogTitle>
          {universalCredential 
            ? t('universalCredentialsForm.updateTitle')
            : t('universalCredentialsForm.addTitle')}
        </DialogTitle>
        <DialogContent>
          <Box sx={{ mt: 2 }}>
            <Typography variant="body2" color="text.secondary" paragraph>
              {t('universalCredentialsForm.description')}
            </Typography>
            
            <TextField
              label={t('credentialsForm.username')}
              fullWidth
              value={username}
              disabled={true} // Desabilitar a edição do username
              margin="normal"
              sx={{ mb: 2 }}
              helperText={t('credentialsForm.usernameHelp') as string}
            />

            <TextField
              label={t('credentialsForm.password')}
              type="password"
              fullWidth
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              margin="normal"
              error={!passwordValid && password.length > 0}
              helperText={
                password.length > 0 && !passwordValid ? (
                  <Box component="span">
                    {t('common:validation.password.requirements') as string}
                    <ul style={{ margin: '4px 0', paddingLeft: '20px' }}>
                      {passwordErrors.map((error, index) => (
                        <li key={index}>{error}</li>
                      ))}
                    </ul>
                  </Box>
                ) : (
                  t('credentialsForm.passwordHelp') as string
                )
              }
            />
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseDialog}>
            {t('common:cancel')}
          </Button>
          <Button 
            onClick={handleUpdateCredentials} 
            variant="contained" 
            color="primary"
            disabled={!username || !password || !passwordValid}
            sx={{ 
              fontWeight: 'bold',
              color: 'white',
              '&:hover': {
                backgroundColor: theme => theme.palette.primary.dark,
              },
              '&.Mui-disabled': {
                backgroundColor: theme => alpha(theme.palette.primary.main, 0.5),
                color: 'rgba(255, 255, 255, 0.8)',
              }
            }}
          >
            {universalCredential 
              ? t('credentialsForm.updateButton')
              : t('credentialsForm.saveButton')}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Success/Error Snackbar */}
      <Snackbar
        open={snackbarOpen}
        autoHideDuration={5000}
        onClose={handleSnackbarClose}
        anchorOrigin={{ vertical: 'top', horizontal: 'center' }}
      >
        <Alert 
          onClose={handleSnackbarClose} 
          severity={errorMessage ? 'error' : 'success'}
          sx={{ width: '100%' }}
        >
          {errorMessage || successMessage}
        </Alert>
      </Snackbar>
    </>
  );
};

export default DatabaseCredentialsSection;
