import React, { useEffect, useState } from 'react';
import {
  Box,
  Card,
  CardContent,
  Typography,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
  CircularProgress,
  Alert,
  Chip,
  Divider,
  Button,
  Collapse,
  IconButton,
} from '@mui/material';
import {
  CheckCircle as CheckCircleIcon,
  Cancel as CancelIcon,
  Warning as WarningIcon,
  Info as InfoIcon,
  ExpandMore as ExpandMoreIcon,
  ExpandLess as ExpandLessIcon,
  Refresh as RefreshIcon,
} from '@mui/icons-material';
import { useTranslation } from 'react-i18next';
import queryAuditService from '../../services/queryAuditService';

interface PrerequisiteCheck {
  id: string;
  name: string;
  description: string;
  status: 'checking' | 'passed' | 'failed' | 'warning';
  message?: string;
  solution?: string;
  details?: any;
}

interface QueryAuditPrerequisitesProps {
  serverId: string;
  serverType: string;
  onRefresh?: () => void;
}

export const QueryAuditPrerequisites: React.FC<QueryAuditPrerequisitesProps> = ({
  serverId,
  serverType,
  onRefresh,
}) => {
  const { t } = useTranslation(['queryAudit', 'common']);
  const [checks, setChecks] = useState<PrerequisiteCheck[]>([]);
  const [loading, setLoading] = useState(true);
  const [expanded, setExpanded] = useState(true);
  const [overallStatus, setOverallStatus] = useState<'checking' | 'ready' | 'partial' | 'failed'>('checking');

  useEffect(() => {
    checkPrerequisites();
  }, [serverId]);

  const checkPrerequisites = async () => {
    setLoading(true);
    setChecks([]);
    
    // Inicializa os checks com status "checking"
    const initialChecks: PrerequisiteCheck[] = [
      {
        id: 'server_connection',
        name: t('queryAudit:prerequisites.serverConnection'),
        description: t('queryAudit:prerequisites.serverConnectionDesc'),
        status: 'checking',
      },
      {
        id: 'audit_enabled',
        name: t('queryAudit:prerequisites.auditEnabled'),
        description: t('queryAudit:prerequisites.auditEnabledDesc'),
        status: 'checking',
      },
      {
        id: 'collector_running',
        name: t('queryAudit:prerequisites.collectorRunning'),
        description: t('queryAudit:prerequisites.collectorRunningDesc'),
        status: 'checking',
      },
    ];

    // Adiciona checks específicos por tipo de banco
    if (serverType === 'mysql' || serverType === 'mariadb') {
      initialChecks.push({
        id: 'performance_schema',
        name: t('queryAudit:prerequisites.performanceSchema'),
        description: t('queryAudit:prerequisites.performanceSchemaDesc'),
        status: 'checking',
      });
    } else if (serverType === 'postgres') {
      initialChecks.push({
        id: 'pg_stat_statements',
        name: t('queryAudit:prerequisites.pgStatStatements'),
        description: t('queryAudit:prerequisites.pgStatStatementsDesc'),
        status: 'checking',
      });
    } else if (serverType === 'mssql') {
      initialChecks.push({
        id: 'query_store',
        name: t('queryAudit:prerequisites.queryStore'),
        description: t('queryAudit:prerequisites.queryStoreDesc'),
        status: 'checking',
      });
    }

    setChecks(initialChecks);

    try {
      // Faz a verificação real dos pré-requisitos
      const response = await queryAuditService.checkPrerequisites(serverId);
      
      console.log('Prerequisites response:', response);
      
      if (!response || !response.checks) {
        throw new Error('Invalid response format');
      }
      
      const updatedChecks = initialChecks.map(check => {
        const result = response.checks[check.id];
        if (result) {
          return {
            ...check,
            status: (result.passed ? 'passed' : result.warning ? 'warning' : 'failed') as PrerequisiteCheck['status'],
            message: result.message,
            solution: result.solution,
            details: result.details,
          };
        }
        return check;
      });

      setChecks(updatedChecks);
      
      // Determina o status geral
      const failedCount = updatedChecks.filter(c => c.status === 'failed').length;
      const warningCount = updatedChecks.filter(c => c.status === 'warning').length;
      
      if (failedCount > 0) {
        setOverallStatus('failed');
      } else if (warningCount > 0) {
        setOverallStatus('partial');
      } else {
        setOverallStatus('ready');
      }
    } catch (error) {
      console.error('Error checking prerequisites:', error);
      setChecks(initialChecks.map(check => ({
        ...check,
        status: 'failed' as PrerequisiteCheck['status'],
        message: t('queryAudit:prerequisites.checkError') as string,
      })));
      setOverallStatus('failed');
    } finally {
      setLoading(false);
    }
  };

  const getStatusIcon = (status: PrerequisiteCheck['status']) => {
    switch (status) {
      case 'checking':
        return <CircularProgress size={24} />;
      case 'passed':
        return <CheckCircleIcon color="success" />;
      case 'failed':
        return <CancelIcon color="error" />;
      case 'warning':
        return <WarningIcon color="warning" />;
      default:
        return null;
    }
  };

  const getOverallStatusColor = () => {
    switch (overallStatus) {
      case 'ready':
        return 'success';
      case 'partial':
        return 'warning';
      case 'failed':
        return 'error';
      default:
        return 'default';
    }
  };

  const getOverallStatusText = () => {
    switch (overallStatus) {
      case 'ready':
        return t('queryAudit:prerequisites.statusReady');
      case 'partial':
        return t('queryAudit:prerequisites.statusPartial');
      case 'failed':
        return t('queryAudit:prerequisites.statusFailed');
      default:
        return t('queryAudit:prerequisites.statusChecking');
    }
  };

  return (
    <Card>
      <CardContent>
        <Box display="flex" alignItems="center" justifyContent="space-between" mb={2}>
          <Box display="flex" alignItems="center" gap={2}>
            <Typography variant="h6">
              {t('queryAudit:prerequisites.title')}
            </Typography>
            <Chip
              label={getOverallStatusText()}
              color={getOverallStatusColor()}
              size="small"
            />
          </Box>
          <Box display="flex" alignItems="center" gap={1}>
            <IconButton
              size="small"
              onClick={() => {
                checkPrerequisites();
                onRefresh?.();
              }}
              disabled={loading}
            >
              <RefreshIcon />
            </IconButton>
            <IconButton
              size="small"
              onClick={() => setExpanded(!expanded)}
            >
              {expanded ? <ExpandLessIcon /> : <ExpandMoreIcon />}
            </IconButton>
          </Box>
        </Box>

        <Collapse in={expanded}>
          <Divider sx={{ mb: 2 }} />
          
          {overallStatus === 'failed' && (
            <Alert severity="error" sx={{ mb: 2 }}>
              {t('queryAudit:prerequisites.failedAlert')}
            </Alert>
          )}
          
          {overallStatus === 'partial' && (
            <Alert severity="warning" sx={{ mb: 2 }}>
              {t('queryAudit:prerequisites.partialAlert')}
            </Alert>
          )}
          
          {overallStatus === 'ready' && (
            <Alert severity="success" sx={{ mb: 2 }}>
              {t('queryAudit:prerequisites.readyAlert')}
            </Alert>
          )}

          <List>
            {checks.map((check, index) => (
              <React.Fragment key={check.id}>
                <ListItem>
                  <ListItemIcon>
                    {getStatusIcon(check.status)}
                  </ListItemIcon>
                  <ListItemText
                    primary={check.name}
                    secondary={
                      <Box>
                        <Typography variant="body2" color="text.secondary">
                          {check.description}
                        </Typography>
                        {check.message && (
                          <Typography
                            variant="body2"
                            color={check.status === 'failed' ? 'error' : 'text.primary'}
                            sx={{ mt: 0.5 }}
                          >
                            {check.message}
                          </Typography>
                        )}
                        {check.solution && check.status === 'failed' && (
                          <Alert
                            severity="info"
                            icon={<InfoIcon />}
                            sx={{ mt: 1 }}
                          >
                            <Typography variant="body2">
                              {t('queryAudit:prerequisites.solution')}: {check.solution}
                            </Typography>
                          </Alert>
                        )}
                      </Box>
                    }
                  />
                </ListItem>
                {index < checks.length - 1 && <Divider variant="inset" component="li" />}
              </React.Fragment>
            ))}
          </List>

          {overallStatus === 'ready' && (
            <Box mt={2} display="flex" justifyContent="center">
              <Button
                variant="contained"
                color="primary"
                onClick={() => window.location.href = `/query-audit?serverId=${serverId}&tab=logs`}
              >
                {t('queryAudit:prerequisites.viewLogs')}
              </Button>
            </Box>
          )}
        </Collapse>
      </CardContent>
    </Card>
  );
};