import React from 'react';
import {
  FormControl,
  FormControlLabel,
  FormHelperText,
  Radio,
  RadioGroup,
  Typography,
  Grid,
  Card,
  CardContent,
  Box,
  TextField,
  Chip,
  CardActionArea, 
  alpha,
  useTheme
} from '@mui/material';
import {
  AccessTime as AccessTimeIcon,
  CalendarToday as CalendarIcon,
  AllInclusive as AllInclusiveIcon,
  Timer as TimerIcon
} from '@mui/icons-material';
import { useTranslation } from 'react-i18next';
import { StepProps } from '../../types';
import StepLayout from '../shared/StepLayout';

/**
 * Componente para a etapa de seleção da duração do acesso
 */
const DurationStep: React.FC<StepProps> = ({ state, dispatch, onNext }) => {
  const { t, i18n } = useTranslation(['requests', 'common', 'error']);
  const theme = useTheme();

  // Função para selecionar o tipo de acesso
  const handleSelectPermanent = (isPermanent: boolean) => {
    dispatch({ type: 'SET_IS_PERMANENT', payload: isPermanent });
    
    // Se mudar para permanente, limpa a data de expiração
    if (isPermanent) {
      dispatch({ type: 'SET_EXPIRATION_DATE', payload: '' });
    }
  };

  // Manipulador para mudança de data de expiração
  const handleExpirationDateChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const date = event.target.value;
    dispatch({ type: 'SET_EXPIRATION_DATE', payload: date });
  };

  // Obter a data mínima (hoje + 1 dia)
  const getMinDate = () => {
    const tomorrow = new Date();
    tomorrow.setDate(tomorrow.getDate() + 1);
    return tomorrow.toISOString().slice(0, 10);
  };

  // Removida a função handleNext para evitar duplicação de botões
  // A validação é feita no useRequestForm

  return (
    <StepLayout
      title={String(t('wizard.steps.duration'))}
      subtitle={String(t('wizard.durationStepSubtitle'))}
      icon="duration"
    >
      <Grid container spacing={2}>
        <Grid item xs={12} md={6}>
          <Card 
            variant={state.isPermanent ? "elevation" : "outlined"}
            elevation={state.isPermanent ? 3 : 0}
            sx={{ 
              height: '100%',
              transition: 'all 0.2s ease',
              border: state.isPermanent ? `2px solid ${theme.palette.success.main}` : `1px solid ${theme.palette.divider}`,
              bgcolor: state.isPermanent ? alpha(theme.palette.success.main, 0.05) : 'background.paper',
            }}
          >
            <CardActionArea 
              onClick={() => handleSelectPermanent(true)}
              sx={{ height: '100%' }}
            >
              <CardContent sx={{ p: 2 }}>
                <Box display="flex" alignItems="center" mb={1.5}>
                  <Box 
                    sx={{ 
                      width: 40, 
                      height: 40, 
                      borderRadius: '50%', 
                      display: 'flex', 
                      alignItems: 'center', 
                      justifyContent: 'center',
                      bgcolor: state.isPermanent ? theme.palette.success.main : alpha(theme.palette.success.main, 0.1),
                      mr: 1.5
                    }}
                  >
                    <AllInclusiveIcon sx={{ color: state.isPermanent ? 'white' : theme.palette.success.main }} />
                  </Box>
                  <Typography variant="h6" color={state.isPermanent ? 'success.main' : 'text.primary'}>
                    {t('wizard.permanent')}
                  </Typography>
                  
                  <Box ml="auto">
                    <Radio 
                      checked={state.isPermanent} 
                      color="success"
                      size="small"
                    />
                  </Box>
                </Box>
                
                <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                  {t('wizard.permanentAccessDesc')}
                </Typography>
                
                <Box display="flex" alignItems="center" mt={2}>
                  <Chip 
                    label={t('wizard.neverExpires')}
                    color="success"
                    size="small"
                    icon={<AllInclusiveIcon sx={{ fontSize: '0.9rem' }} />}
                  />
                </Box>
              </CardContent>
            </CardActionArea>
          </Card>
        </Grid>
        
        <Grid item xs={12} md={6}>
          <Card 
            variant={!state.isPermanent ? "elevation" : "outlined"}
            elevation={!state.isPermanent ? 3 : 0}
            sx={{ 
              height: '100%',
              transition: 'all 0.2s ease',
              border: !state.isPermanent ? `2px solid ${theme.palette.info.main}` : `1px solid ${theme.palette.divider}`,
              bgcolor: !state.isPermanent ? alpha(theme.palette.info.main, 0.05) : 'background.paper',
            }}
          >
            <CardActionArea 
              onClick={() => handleSelectPermanent(false)}
              sx={{ height: 'auto' }}
            >
              <CardContent sx={{ p: 2 }}>
                <Box display="flex" alignItems="center" mb={1.5}>
                  <Box 
                    sx={{ 
                      width: 40, 
                      height: 40, 
                      borderRadius: '50%', 
                      display: 'flex', 
                      alignItems: 'center', 
                      justifyContent: 'center',
                      bgcolor: !state.isPermanent ? theme.palette.info.main : alpha(theme.palette.info.main, 0.1),
                      mr: 1.5
                    }}
                  >
                    <TimerIcon sx={{ color: !state.isPermanent ? 'white' : theme.palette.info.main }} />
                  </Box>
                  <Typography variant="h6" color={!state.isPermanent ? 'info.main' : 'text.primary'}>
                    {t('wizard.temporary')}
                  </Typography>
                  
                  <Box ml="auto">
                    <Radio 
                      checked={!state.isPermanent} 
                      color="info"
                      size="small"
                    />
                  </Box>
                </Box>
                
                <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                  {t('wizard.temporaryAccessDesc')}
                </Typography>
                
                <TextField
                  fullWidth
                  label={t('wizard.expirationDate')}
                  type="date"
                  value={state.expirationDate}
                  onChange={handleExpirationDateChange}
                  InputLabelProps={{
                    shrink: true,
                  }}
                  inputProps={{
                    min: getMinDate(),
                  }}
                  error={!!state.errors.expirationDate}
                  helperText={state.errors.expirationDate || ''}
                  required
                  size="small"
                  sx={{ mt: 1 }}
                  disabled={state.isPermanent}
                />
                
                {!state.isPermanent && state.expirationDate && (
                  <Box mt={2} display="flex" alignItems="center">
                    <Chip 
                      label={`${t('request.expiresOn')}: ${new Date(state.expirationDate).toLocaleDateString()}`}
                      color="info"
                      size="small"
                      icon={<CalendarIcon sx={{ fontSize: '0.9rem' }} />}
                    />
                  </Box>
                )}
              </CardContent>
            </CardActionArea>
            
            {!state.isPermanent && (
              <CardContent sx={{ pt: 0, pb: 2 }}>
                <Box sx={{ mt: 1, display: 'flex', alignItems: 'flex-start' }}>
                  <CalendarIcon color="info" sx={{ mr: 1, fontSize: '1rem', mt: 0.3 }} />
                  <Typography variant="caption" color="text.secondary">
                    {t('wizard.expirationDateInfo')}
                  </Typography>
                </Box>
                
                <Box sx={{ mt: 1, display: 'flex', alignItems: 'flex-start' }}>
                  <AccessTimeIcon color="info" sx={{ mr: 1, fontSize: '1rem', mt: 0.3 }} />
                  <Typography variant="caption" color="text.secondary">
                    {t('wizard.autoRevocationNote')}
                  </Typography>
                </Box>
              </CardContent>
            )}
          </Card>
        </Grid>
      </Grid>
    </StepLayout>
  );
};

export default DurationStep;
