import React, { createContext, useState, useContext, useEffect, useMemo } from 'react';
import { ThemeProvider as MUIThemeProvider } from '@mui/material';
import { PaletteMode } from '@mui/material';
import { createAppTheme } from '../theme/theme';

interface ThemeContextType {
  mode: PaletteMode;
  setMode: (mode: PaletteMode) => void;
  toggleColorMode: () => void;
  systemPreference: PaletteMode | null;
}

const ThemeContext = createContext<ThemeContextType>({
  mode: 'light',
  setMode: () => {},
  toggleColorMode: () => {},
  systemPreference: null,
});

export const useTheme = () => useContext(ThemeContext);

interface ThemeProviderProps {
  children: React.ReactNode;
}

export const ThemeProvider: React.FC<ThemeProviderProps> = ({ children }) => {
  // Verificar se há uma preferência salvada no localStorage
  const getSavedMode = (): PaletteMode => {
    const savedTheme = localStorage.getItem('userTheme');
    
    if (savedTheme === 'dark') return 'dark';
    if (savedTheme === 'light') return 'light';
    if (savedTheme === 'system') return getSystemPreference();
    
    // Padrão: light
    return 'light';
  };

  // Obter preferência do sistema
  const getSystemPreference = (): PaletteMode => {
    if (typeof window !== 'undefined') {
      return window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches 
        ? 'dark' 
        : 'light';
    }
    return 'light';
  };

  const [mode, setMode] = useState<PaletteMode>(getSavedMode());
  const [systemPreference, setSystemPreference] = useState<PaletteMode | null>(getSystemPreference());

  // Gerenciar mudanças no modo
  const handleModeChange = (newMode: PaletteMode) => {
    setMode(newMode);
    localStorage.setItem('userTheme', newMode);
  };

  // Alternar entre light e dark
  const toggleColorMode = () => {
    handleModeChange(mode === 'light' ? 'dark' : 'light');
  };

  // Monitorar alterações na preferência do sistema
  useEffect(() => {
    const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
    
    const handleChange = (e: MediaQueryListEvent) => {
      const newSystemPreference = e.matches ? 'dark' : 'light';
      setSystemPreference(newSystemPreference);
      
      // Se o usuário escolheu "system", atualizar o tema conforme a preferência do sistema
      if (localStorage.getItem('userTheme') === 'system') {
        setMode(newSystemPreference);
      }
    };
    
    // Adicionar listener para mudanças na preferência do sistema
    mediaQuery.addEventListener('change', handleChange);
    
    return () => {
      mediaQuery.removeEventListener('change', handleChange);
    };
  }, []);

  // Criar o tema MUI com base no modo atual
  const theme = useMemo(() => createAppTheme(mode), [mode]);

  const contextValue = {
    mode,
    setMode: handleModeChange,
    toggleColorMode,
    systemPreference
  };

  return (
    <ThemeContext.Provider value={contextValue}>
      <MUIThemeProvider theme={theme}>
        {children}
      </MUIThemeProvider>
    </ThemeContext.Provider>
  );
};

export default ThemeProvider;