import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  TextField,
  Box,
  Typography,
  Chip,
  Grid,
  Divider,
  Alert,
  Card,
  CardContent,
  IconButton,
  Paper,
  useTheme,
  Avatar
} from '@mui/material';
import {
  Person as PersonIcon,
  Storage as StorageIcon,
  Dataset as DatabaseIcon,
  TableChart as TableIcon,
  ManageAccounts as OperationsIcon,
  AccessTime as TimeIcon,
  Description as DescriptionIcon,
  Info as InfoIcon,
  Code as CodeIcon,
  Close as CloseIcon
} from '@mui/icons-material';
import { requestService } from '../../services/api';

interface RequestActionFormProps {
  open: boolean;
  onClose: () => void;
  onAction: (newStatus?: string, success?: boolean) => void;
  request: {
    id: string;
    user: string;
    database: string;
    tables: string;
    operations: string;
    status: string;
    requestDate: string;
    justification?: string;
  } | null;
  action: 'approve' | 'reject' | 'view' | 'cancel' | 'revoke' | 'delete';
}

const RequestActionForm: React.FC<RequestActionFormProps> = ({
  open,
  onClose,
  onAction,
  request,
  action
}) => {
  const { t } = useTranslation(['requests', 'wizard', 'common', 'permissions']);
  const theme = useTheme();
  const [reason, setReason] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [errorSeverity, setErrorSeverity] = useState<'error' | 'warning' | 'info' | 'success'>('error');

  if (!request) {
    return null;
  }

  const handleReasonChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setReason(event.target.value);
  };

  const handleApprove = async () => {
    setLoading(true);
    setError(null);
    try {
      // Call the actual API service
      const response = await requestService.approveRequest(request.id, {
        // Fornecer objeto vazio ou comentários se necessário
        comments: '' // Campo opcional para comentários de aprovação
      });
      
      // Verificar se a API reportou erro de sincronização ou qualquer outro erro
      if (response && !response.success) {
        // Houve falha na sincronização ou outro problema
        console.error('Request approval failed:', response.message);
        setError(response.message || String(t('requests:action.approveError')));
        // Indica explicitamente que a operação falhou
        onAction('', false);
        // Mantém o modal aberto para o usuário ver a mensagem de erro
        return;
      }
      
      // Aprovação bem-sucedida
      onAction('approved', true);
      onClose();
    } catch (error: any) {
      console.error('Error approving request:', error);
      
      // Verificar se é erro de limite de licença
      if (error.response?.status === 403) {
        // Extrair a mensagem do corpo da resposta
        const errorBody = error.response?.data;
        let errorMessage = '';
        
        // O backend está retornando texto simples no body
        if (typeof errorBody === 'string') {
          errorMessage = errorBody;
        } else if (errorBody?.message) {
          errorMessage = errorBody.message;
        } else if (errorBody?.error) {
          errorMessage = errorBody.error;
        }
        
        // Se a mensagem contém informação sobre limite de licença
        if (errorMessage.includes('Limite') || errorMessage.includes('limite') || errorMessage.includes('licença')) {
          setError(errorMessage);
          // Definir tipo de alerta como warning para mensagens de limite
          setErrorSeverity('warning');
        } else {
          setError(errorMessage || String(t('requests:action.approveError')));
          setErrorSeverity('error');
        }
      } else {
        // Outros erros
        const errorMessage = error.response?.data?.message || 
                            error.response?.data?.error || 
                            error.message || 
                            String(t('requests:action.approveError'));
        setError(errorMessage);
        setErrorSeverity('error');
      }
      
      // Informa que a operação falhou completamente
      onAction('', false);
    } finally {
      setLoading(false);
    }
  };

  const handleReject = async () => {
    if (action === 'reject' && !reason.trim()) {
      setError(String(t('requests:action.reasonRequired')));
      return;
    }

    setLoading(true);
    setError(null);
    try {
      // Call the actual API service com o formato correto
      const response = await requestService.rejectRequest(request.id, { 
        reason: reason // Enviar como um objeto com a propriedade reason
      });
      
      // Verificar se a API reportou erro
      if (response && !response.success) {
        // Houve algum problema na rejeição
        console.error('Request rejection failed:', response.message);
        setError(response.message || String(t('requests:action.rejectError')));
        // Informa que a operação falhou
        onAction('', false);
        // Deixamos o modal aberto para o usuário ver a mensagem de erro
        return;
      }
      
      // Rejeição bem-sucedida
      onAction('rejected', true);
      onClose();
    } catch (error: any) {
      console.error('Error rejecting request:', error);
      // Extrair mensagem detalhada se disponível
      const errorMessage = error.response?.data?.message || 
                          error.response?.data?.error || 
                          error.message || 
                          String(t('requests:action.rejectError'));
      setError(errorMessage);
      // Informa que a operação falhou
      onAction('', false);
    } finally {
      setLoading(false);
    }
  };
  
  const handleRevoke = async () => {
    if (action === 'revoke' && !reason.trim()) {
      setError(String(t('requests:action.reasonRequired')));
      return;
    }

    setLoading(true);
    setError(null);
    try {
      const response = await requestService.revokeRequest(request.id, { 
        reason: reason
      });
      
      if (response && !response.success) {
        console.error('Request revocation failed:', response.message);
        setError(response.message || String(t('requests:action.revokeError')));
        // Informa que a operação falhou
        onAction('', false);
        // Deixamos o modal aberto para o usuário ver a mensagem de erro
        return;
      }
      
      // Revogação bem-sucedida
      onAction('revoked', true);
      onClose();
    } catch (error: any) {
      console.error('Error revoking request:', error);
      // Extrair mensagem detalhada se disponível
      const errorMessage = error.response?.data?.message || 
                          error.response?.data?.error || 
                          error.message || 
                          String(t('requests:action.revokeError'));
      setError(errorMessage);
      // Informa que a operação falhou
      onAction('', false);
    } finally {
      setLoading(false);
    }
  };
  
  const handleDelete = async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await requestService.deleteRequest(request.id);
      
      if (response && !response.success) {
        console.error('Request deletion failed:', response.message);
        setError(response.message || String(t('requests:action.deleteError')));
        // Informa que a operação falhou
        onAction('', false);
        // Deixamos o modal aberto para o usuário ver a mensagem de erro
        return;
      }
      
      // Exclusão bem-sucedida
      onAction('deleted', true);
      onClose();
    } catch (error: any) {
      console.error('Error deleting request:', error);
      // Extrair mensagem detalhada se disponível
      const errorMessage = error.response?.data?.message || 
                          error.response?.data?.error || 
                          error.message || 
                          String(t('requests:action.deleteError'));
      setError(errorMessage);
      // Informa que a operação falhou
      onAction('', false);
    } finally {
      setLoading(false);
    }
  };

  const getDialogTitle = () => {
    switch (action) {
      case 'approve':
        return String(t('requests:action.approveTitle'));
      case 'reject':
        return String(t('requests:action.rejectTitle'));
      case 'view':
        return String(t('requests:action.viewTitle'));
      case 'cancel':
        return String(t('requests:action.cancelTitle'));
      case 'revoke':
        return String(t('requests:action.revokeTitle'));
      case 'delete':
        return String(t('requests:action.deleteTitle'));
      default:
        return '';
    }
  };

  return (
    <Dialog 
      open={open} 
      onClose={onClose} 
      maxWidth="md" 
      fullWidth
      disableEnforceFocus
      disableRestoreFocus
      PaperProps={{
        sx: {
          borderRadius: 2,
          overflow: 'hidden'
        }
      }}
    >
      {/* Cabeçalho estilizado */}
      <DialogTitle
        sx={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          bgcolor: theme.palette.primary.main,
          color: 'white',
          py: 2
        }}
      >
        <Box display="flex" alignItems="center">
          <InfoIcon sx={{ mr: 1 }} />
          <Typography variant="h6">
            {getDialogTitle()}
          </Typography>
        </Box>
        <IconButton
          edge="end"
          color="inherit"
          onClick={onClose}
          aria-label="close"
        >
          <CloseIcon />
        </IconButton>
      </DialogTitle>

      <DialogContent sx={{ p: 3 }}>
        {error && (
          <Alert 
            severity={errorSeverity} 
            sx={{ 
              mb: 3,
              '& .MuiAlert-message': {
                fontSize: '0.95rem',
                fontWeight: errorSeverity === 'warning' ? 500 : 400
              }
            }}
          >
            {error}
          </Alert>
        )}

        <Box sx={{ mb: 3 }}>
          {/* Display cards em grid layout */}
          <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 2 }}>
            {/* Usuário */}
            <Paper 
              elevation={2} 
              sx={{ 
                p: 2, 
                flex: '1 0 calc(50% - 8px)',
                borderRadius: 2,
                display: 'flex',
                alignItems: 'center',
                transition: 'transform 0.2s',
                '&:hover': {
                  transform: 'translateY(-4px)',
                  boxShadow: 4
                }
              }}
            >
              <PersonIcon color="primary" sx={{ mr: 1 }} />
              <Box>
                <Typography variant="caption" color="textSecondary">
                  {String(t('requests:table.user'))}
                </Typography>
                <Typography variant="subtitle1" sx={{ fontWeight: 'medium' }}>
                  {request.user}
                </Typography>
              </Box>
            </Paper>

            {/* ID da Solicitação com Data */}
            <Paper 
              elevation={2} 
              sx={{ 
                p: 2, 
                flex: '1 0 calc(50% - 8px)',
                borderRadius: 2,
                display: 'flex',
                alignItems: 'center',
                transition: 'transform 0.2s',
                '&:hover': {
                  transform: 'translateY(-4px)',
                  boxShadow: 4
                }
              }}
            >
              <TimeIcon color="primary" sx={{ mr: 1 }} />
              <Box>
                <Typography variant="caption" color="textSecondary">
                  {String(t('requests:table.requestDate'))}
                </Typography>
                <Typography variant="subtitle1" sx={{ fontWeight: 'medium' }}>
                  {request.requestDate}
                </Typography>
                <Typography variant="caption" color="textSecondary" display="block">
                  ID: {request.id.length > 10 ? `REQ-${request.id.substring(0, 8)}...` : request.id}
                </Typography>
              </Box>
            </Paper>

            {/* Banco de Dados */}
            <Paper 
              elevation={2} 
              sx={{ 
                p: 2, 
                flex: '1 0 calc(50% - 8px)',
                borderRadius: 2,
                display: 'flex',
                alignItems: 'center',
                transition: 'transform 0.2s',
                '&:hover': {
                  transform: 'translateY(-4px)',
                  boxShadow: 4
                }
              }}
            >
              <DatabaseIcon color="primary" sx={{ mr: 1 }} />
              <Box>
                <Typography variant="caption" color="textSecondary">
                  {String(t('requests:table.database'))}
                </Typography>
                <Typography variant="subtitle1" sx={{ fontWeight: 'medium' }}>
                  {request.database}
                </Typography>
              </Box>
            </Paper>

            {/* Status */}
            <Paper 
              elevation={2} 
              sx={{ 
                p: 2, 
                flex: '1 0 calc(50% - 8px)',
                borderRadius: 2,
                display: 'flex',
                alignItems: 'center',
                transition: 'transform 0.2s',
                '&:hover': {
                  transform: 'translateY(-4px)',
                  boxShadow: 4
                }
              }}
            >
              <InfoIcon color="primary" sx={{ mr: 1 }} />
              <Box>
                <Typography variant="caption" color="textSecondary">
                  {String(t('requests:table.status'))}
                </Typography>
                <Box sx={{ mt: 0.5 }}>
                  <Chip 
                    label={String(t(`requests:status.${request.status}`))} 
                    color={
                      request.status === 'approved' ? 'success' :
                      request.status === 'rejected' ? 'error' :
                      'warning'
                    }
                    size="small"
                  />
                </Box>
              </Box>
            </Paper>

            {/* Tabelas */}
            <Paper 
              elevation={2} 
              sx={{ 
                p: 2, 
                flex: '1 0 calc(50% - 8px)',
                borderRadius: 2,
                display: 'flex',
                alignItems: 'flex-start',
                transition: 'transform 0.2s',
                '&:hover': {
                  transform: 'translateY(-4px)',
                  boxShadow: 4
                }
              }}
            >
              <TableIcon color="primary" sx={{ mr: 1, mt: 0.5 }} />
              <Box>
                <Typography variant="caption" color="textSecondary">
                  {String(t('requests:table.tables'))}
                </Typography>
                <Typography variant="subtitle1" sx={{ fontWeight: 'medium', wordBreak: 'break-word' }}>
                  {request.tables}
                </Typography>
              </Box>
            </Paper>

            {/* Operações */}
            <Paper 
              elevation={2} 
              sx={{ 
                p: 2, 
                flex: '1 0 calc(50% - 8px)',
                borderRadius: 2,
                display: 'flex',
                alignItems: 'flex-start',
                transition: 'transform 0.2s',
                '&:hover': {
                  transform: 'translateY(-4px)',
                  boxShadow: 4
                }
              }}
            >
              <OperationsIcon color="primary" sx={{ mr: 1, mt: 0.5 }} />
              <Box>
                <Typography variant="caption" color="textSecondary">
                  {String(t('requests:table.operations'))}
                </Typography>
                <Box sx={{ mt: 0.5, display: 'flex', flexWrap: 'wrap', gap: 0.5 }}>
                  {request.operations.split(',').map((op, index) => (
                    <Chip
                      key={index}
                      label={String(t(`permissions:operations.${op.trim()}`))}
                      color={
                        op.trim().toUpperCase() === 'SELECT' ? 'success' :
                        op.trim().toUpperCase() === 'INSERT' || op.trim().toUpperCase() === 'UPDATE' ? 'warning' :
                        op.trim().toUpperCase() === 'DELETE' ? 'error' :
                        op.trim() === 'read' ? 'success' :  // Backward compatibility with old format
                        op.trim() === 'write' ? 'warning' : // Backward compatibility with old format
                        'default'
                      }
                      size="small"
                    />
                  ))}
                </Box>
              </Box>
            </Paper>
          </Box>

          {/* Justificativa */}
          {request.justification && (
            <Paper 
              elevation={2} 
              sx={{ 
                p: 2, 
                mt: 2, 
                borderRadius: 2,
                transition: 'transform 0.2s',
                '&:hover': {
                  transform: 'translateY(-4px)',
                  boxShadow: 4
                }
              }}
            >
              <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                <DescriptionIcon color="primary" sx={{ mr: 1 }} />
                <Typography variant="subtitle1" sx={{ fontWeight: 'medium' }}>
                  {String(t('requests:form.justification'))}
                </Typography>
              </Box>
              <Typography variant="body2" sx={{ whiteSpace: 'pre-wrap' }}>
                {request.justification}
              </Typography>
            </Paper>
          )}
        </Box>

        {/* Área de rejeição/revogação */}
        {(action === 'reject' || action === 'revoke') && (
          <Paper elevation={2} sx={{ p: 2, borderRadius: 2 }}>
            <TextField
              fullWidth
              label={action === 'reject' 
                ? String(t('requests:action.rejectReason'))
                : String(t('requests:action.revokeReason'))}
              value={reason}
              onChange={handleReasonChange}
              multiline
              rows={4}
              error={!!error && !reason.trim()}
              helperText={!reason.trim() ? String(t('requests:action.reasonRequired')) : ''}
            />
          </Paper>
        )}
      </DialogContent>

      <DialogActions sx={{ p: 2, borderTop: `1px solid ${theme.palette.divider}` }}>
        <Button onClick={onClose} disabled={loading}>
          {action === 'view' ? String(t('common:close')) : String(t('common:cancel'))}
        </Button>
        {action === 'approve' && (
          <Button
            onClick={handleApprove}
            variant="contained"
            color="success"
            disabled={loading}
            startIcon={<InfoIcon />}
          >
            {String(t('common:approve'))}
          </Button>
        )}
        {action === 'reject' && (
          <Button
            onClick={handleReject}
            variant="contained"
            color="error"
            disabled={loading}
          >
            {String(t('common:reject'))}
          </Button>
        )}
        {action === 'revoke' && (
          <Button
            onClick={handleRevoke}
            variant="contained"
            color="error"
            disabled={loading}
          >
            {String(t('common:revoke'))}
          </Button>
        )}
        {action === 'delete' && (
          <Button
            onClick={handleDelete}
            variant="contained"
            color="error"
            disabled={loading}
          >
            {String(t('common:delete'))}
          </Button>
        )}
      </DialogActions>
    </Dialog>
  );
};

export default RequestActionForm;
