import React, { useState, useEffect } from 'react';
import {
  Box,
  Container,
  Typography,
  Tabs,
  Tab,
  Paper,
  Grid,
  Card,
  CardContent,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  SelectChangeEvent,
  Alert,
  Chip,
} from '@mui/material';
import {
  Settings as SettingsIcon,
  Storage as StorageIcon,
  Notifications as NotificationsIcon,
  Assessment as AssessmentIcon,
  Circle as CircleIcon,
} from '@mui/icons-material';
import { useTranslation } from 'react-i18next';
import { useParams, useNavigate, useLocation } from 'react-router-dom';
import QueryAuditConfig from '../components/QueryAudit/QueryAuditConfig';
import QueryAuditLogs from '../components/QueryAudit/QueryAuditLogs';
import QueryAuditStatistics from '../components/QueryAudit/QueryAuditStatistics';
import QueryAuditAlerts from '../components/QueryAudit/QueryAuditAlerts';
import { serverService } from '../services/api';
import queryAuditService, { CollectionStatus } from '../services/queryAuditService';

interface TabPanelProps {
  children?: React.ReactNode;
  index: number;
  value: number;
}

function TabPanel(props: TabPanelProps) {
  const { children, value, index, ...other } = props;

  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`query-audit-tabpanel-${index}`}
      aria-labelledby={`query-audit-tab-${index}`}
      {...other}
    >
      {value === index && <Box sx={{ py: 3 }}>{children}</Box>}
    </div>
  );
}

function a11yProps(index: number) {
  return {
    id: `query-audit-tab-${index}`,
    'aria-controls': `query-audit-tabpanel-${index}`,
  };
}

const QueryAudit: React.FC = () => {
  const { t } = useTranslation(['queryAudit', 'common']);
  const { serverId } = useParams<{ serverId?: string }>();
  const navigate = useNavigate();
  const location = useLocation();
  const [selectedTab, setSelectedTab] = useState(0);
  const [servers, setServers] = useState<any[]>([]);
  const [selectedServerId, setSelectedServerId] = useState(serverId || '');
  const [selectedServer, setSelectedServer] = useState<any>(null);
  const [collectionStatus, setCollectionStatus] = useState<CollectionStatus | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadServers();
    loadCollectionStatus();
  }, []);

  useEffect(() => {
    if (selectedServerId && servers.length > 0) {
      const server = servers.find((s) => s.id === selectedServerId);
      setSelectedServer(server);
    }
  }, [selectedServerId, servers]);

  useEffect(() => {
    // Handle tab from URL
    const searchParams = new URLSearchParams(location.search);
    const tab = searchParams.get('tab');
    if (tab === 'config') setSelectedTab(0);
    else if (tab === 'logs') setSelectedTab(1);
    else if (tab === 'stats') setSelectedTab(2);
    else if (tab === 'alerts') setSelectedTab(3);
  }, [location]);

  const loadServers = async () => {
    try {
      const response = await serverService.getServers();
      console.log('Servers response:', response);
      let serversArray = response.servers || response;
      console.log('Servers array:', serversArray);
      
      // Garantir que sempre temos um array
      if (!Array.isArray(serversArray)) {
        serversArray = [];
      }
      
      setServers(serversArray);
      if (!selectedServerId && serversArray.length > 0) {
        setSelectedServerId(serversArray[0].id);
      }
    } catch (error) {
      console.error('Failed to load servers:', error);
      setServers([]); // Definir array vazio em caso de erro
    }
  };

  const loadCollectionStatus = async () => {
    try {
      setLoading(true);
      const status = await queryAuditService.getCollectionStatus();
      console.log('Collection status received:', status);
      setCollectionStatus(status);
    } catch (error) {
      console.error('Failed to load collection status:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleServerChange = (event: SelectChangeEvent) => {
    const newServerId = event.target.value;
    setSelectedServerId(newServerId);
    navigate(`/query-audit/${newServerId}${location.search}`);
  };

  const handleTabChange = (event: React.SyntheticEvent, newValue: number) => {
    setSelectedTab(newValue);
    const tabNames = ['config', 'logs', 'stats', 'alerts'];
    const searchParams = new URLSearchParams(location.search);
    searchParams.set('tab', tabNames[newValue]);
    navigate(`${location.pathname}?${searchParams.toString()}`);
  };

  const getServerStatus = (serverId: string) => {
    if (!collectionStatus || !collectionStatus.servers) return null;
    const serverStatus = collectionStatus.servers.find((s) => s.id === serverId);
    return serverStatus;
  };

  return (
    <Container maxWidth="xl">
      <Box sx={{ py: 3 }}>
        <Typography variant="h4" gutterBottom>
          {t('queryAudit:title')}
        </Typography>
        
        {/* Server Selection and Status */}
        <Grid container spacing={2} sx={{ mb: 3 }}>
          <Grid item xs={12} md={6}>
            <FormControl fullWidth>
              <InputLabel>{t('queryAudit:selectServer')}</InputLabel>
              <Select
                value={selectedServerId}
                onChange={handleServerChange}
                label={t('queryAudit:selectServer')}
              >
                {servers && Array.isArray(servers) && servers.map((server) => {
                  const status = getServerStatus(server.id);
                  return (
                    <MenuItem key={server.id} value={server.id}>
                      <Box display="flex" alignItems="center" width="100%">
                        <StorageIcon sx={{ mr: 1 }} />
                        <Box flexGrow={1}>
                          {server.name} ({server.type})
                        </Box>
                        {status && (
                          <Box display="flex" alignItems="center">
                            <CircleIcon
                              sx={{
                                fontSize: 12,
                                color: status.enabled ? 'success.main' : 'text.disabled',
                                mr: 1,
                              }}
                            />
                            <Typography variant="caption">
                              {status.query_count} queries
                            </Typography>
                          </Box>
                        )}
                      </Box>
                    </MenuItem>
                  );
                }) || []}
              </Select>
            </FormControl>
          </Grid>
          <Grid item xs={12} md={6}>
            {collectionStatus && (
              <Card>
                <CardContent>
                  <Box display="flex" justifyContent="space-between">
                    <Box>
                      <Typography variant="body2" color="textSecondary">
                        {t('queryAudit:activeServers')}
                      </Typography>
                      <Typography variant="h6">
                        {collectionStatus.active_count} / {collectionStatus.total_servers}
                      </Typography>
                    </Box>
                    <Box>
                      <Typography variant="body2" color="textSecondary">
                        {t('queryAudit:totalQueries')}
                      </Typography>
                      <Typography variant="h6">
                        {selectedServerId && collectionStatus.servers ? 
                          (collectionStatus.servers.find(s => s.id === selectedServerId)?.query_count || 0).toLocaleString() :
                          (collectionStatus.total_queries || 0).toLocaleString()
                        }
                      </Typography>
                    </Box>
                    <Box>
                      <Typography variant="body2" color="textSecondary">
                        {t('queryAudit:supportedTypes')}
                      </Typography>
                      <Box>
                        {collectionStatus.collector_types && Array.isArray(collectionStatus.collector_types) && collectionStatus.collector_types.map((type) => (
                          <Chip key={type} label={type} size="small" sx={{ m: 0.25 }} />
                        ))}
                      </Box>
                    </Box>
                  </Box>
                </CardContent>
              </Card>
            )}
          </Grid>
        </Grid>

        {selectedServer ? (
          <>
            <Paper sx={{ borderBottom: 1, borderColor: 'divider' }}>
              <Tabs value={selectedTab} onChange={handleTabChange} aria-label="query audit tabs">
                <Tab
                  icon={<SettingsIcon />}
                  iconPosition="start"
                  label={t('queryAudit:tabs.config')}
                  {...a11yProps(0)}
                />
                <Tab
                  icon={<StorageIcon />}
                  iconPosition="start"
                  label={t('queryAudit:tabs.logs')}
                  {...a11yProps(1)}
                />
                <Tab
                  icon={<AssessmentIcon />}
                  iconPosition="start"
                  label={t('queryAudit:tabs.statistics')}
                  {...a11yProps(2)}
                />
                <Tab
                  icon={<NotificationsIcon />}
                  iconPosition="start"
                  label={t('queryAudit:tabs.alerts')}
                  {...a11yProps(3)}
                />
              </Tabs>
            </Paper>

            <TabPanel value={selectedTab} index={0}>
              <QueryAuditConfig
                serverId={selectedServerId}
                serverName={selectedServer.name}
                serverType={selectedServer.type}
              />
            </TabPanel>

            <TabPanel value={selectedTab} index={1}>
              <QueryAuditLogs
                serverId={selectedServerId}
                serverName={selectedServer.name}
              />
            </TabPanel>

            <TabPanel value={selectedTab} index={2}>
              <QueryAuditStatistics
                serverId={selectedServerId}
                serverName={selectedServer.name}
              />
            </TabPanel>

            <TabPanel value={selectedTab} index={3}>
              <QueryAuditAlerts
                serverId={selectedServerId}
                serverName={selectedServer.name}
              />
            </TabPanel>
          </>
        ) : (
          <Alert severity="warning">
            {t('queryAudit:noServerSelected')}
          </Alert>
        )}
      </Box>
    </Container>
  );
};

export default QueryAudit;