import React, { useState } from 'react';
import {
  FormControl,
  FormHelperText,
  Typography,
  Grid,
  Box,
  TextField,
  alpha,
  Paper,
  useTheme
} from '@mui/material';
import {
  Description as DescriptionIcon
} from '@mui/icons-material';
import { useTranslation } from 'react-i18next';
import { StepProps } from '../../types';
import StepLayout from '../shared/StepLayout';

/**
 * Componente simplificado para a etapa de justificativa da solicitação
 */
const JustificationStep: React.FC<StepProps> = ({ state, dispatch, onNext }) => {
  const { t, i18n } = useTranslation(['requests', 'common', 'error']);
  const [charCount, setCharCount] = useState(state.justification.length);
  const theme = useTheme();

  // Manipulador para mudança de justificativa
  const handleJustificationChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const text = event.target.value;
    dispatch({ type: 'SET_JUSTIFICATION', payload: text });
    setCharCount(text.length);
  };

  // Removida a função handleNext para evitar duplicação de botões
  // A validação é feita no componente principal do modal

  // Verificar se o botão "Next" deve estar desabilitado
  const isNextDisabled = !state.justification.trim() || state.justification.trim().length < 10;

  return (
    <StepLayout
      title={String(t('wizard.steps.justification'))}
      subtitle={String(t('wizard.justificationStepSubtitle'))}
      icon="justification"
      nextDisabled={isNextDisabled}
    >
      <Grid container spacing={3}>
        <Grid item xs={12}>
          <Paper
            elevation={0}
            sx={{
              p: 2,
              mb: 3,
              bgcolor: alpha(theme.palette.info.light, 0.1),
              border: `1px solid ${alpha(theme.palette.info.main, 0.2)}`,
              borderRadius: 1
            }}
          >
            <Typography variant="body2" color="text.secondary">
              {t('wizard.justificationInfoText')}
            </Typography>
          </Paper>
          
          <FormControl fullWidth error={!!state.errors.justification}>
            <TextField
              id="justification-text"
              label={t('wizard.justification')}
              multiline
              rows={6}
              value={state.justification}
              onChange={handleJustificationChange}
              error={!!state.errors.justification}
              placeholder={String(t('wizard.justificationPlaceholder'))}
              variant="outlined"
              autoFocus
              required
              InputProps={{
                sx: {
                  transition: 'all 0.3s ease',
                  '&:focus-within': {
                    boxShadow: `0 0 0 2px ${alpha(theme.palette.primary.main, 0.2)}`
                  }
                }
              }}
              helperText={
                state.errors.justification || (
                  <span style={{ display: 'flex', justifyContent: 'space-between', width: '100%' }}>
                    <span>
                      {t('wizard.justificationHelp')}
                    </span>
                    <span>
                      {charCount}/500
                    </span>
                  </span>
                )
              }
              inputProps={{ 
                maxLength: 500,
                required: true
              }}
            />
          </FormControl>
        </Grid>
      </Grid>
    </StepLayout>
  );
};

export default JustificationStep;