import { apiClient } from './api';

// Cache busting timestamp
let cacheBuster = Date.now().toString();

// Function to reset cache
const resetCache = () => {
  cacheBuster = Date.now().toString();
  // Limpar localStorage e sessionStorage para melhoria adicional
  localStorage.removeItem('sync_config_cache');
  localStorage.removeItem('sync_status_cache');
  sessionStorage.removeItem('sync_config_cache');
  sessionStorage.removeItem('sync_status_cache');
};

// Sync service for database synchronization
export const syncService = {
  // Force reload all cached data
  resetCache: () => {
    resetCache();
  },
  
  // Aceitar um usuário não gerenciado como permitido
  acceptUnmanagedUser: async (discrepancyId: string) => {
    try {
      // Tenta usar o endpoint de aceitação de usuários não gerenciados
      const response = await apiClient.post(`/api/sync/accept/${discrepancyId}?cache=${cacheBuster}`);
      return response.data;
    } catch (error) {
      throw error;
    }
  },

  // Aceitar uma discrepância de estrutura (database/table)
  acceptStructureDiscrepancy: async (discrepancyId: string) => {
    try {
      // Usa o endpoint de aceitação de estrutura
      const response = await apiClient.post(`/api/sync/accept-structure/${discrepancyId}?cache=${cacheBuster}`);
      return response.data;
    } catch (error) {
      throw error;
    }
  },

  // Aceitar um usuário não gerenciado diretamente (sem ser via discrepância)
  acceptUnmanagedUserDirect: async (serverId: string, username: string, note?: string) => {
    try {
      // Payload com dados do usuário
      const payload = {
        server_id: serverId,
        username: username,
        note: note || ''
      };

      // Chama o endpoint para aceitar diretamente
      const response = await apiClient.post(`/api/sync/accept-user?cache=${cacheBuster}`, payload);
      return response.data;
    } catch (error) {
      throw error;
    }
  },

  // Remover um usuário não gerenciado do banco de dados
  removeUnmanagedUser: async (serverId: string, username: string) => {
    try {
      // Payload com dados do usuário
      const payload = {
        server_id: serverId,
        username: username
      };

      // Chama o endpoint para remoção direta
      const response = await apiClient.post(`/api/sync/remove-user?cache=${cacheBuster}`, payload);
      return response.data;
    } catch (error) {
      throw error;
    }
  },
  
  // Obter lista de usuários não gerenciados já aceitos
  getAcceptedUsers: async () => {
    try {
      const response = await apiClient.get(`/api/sync/accepted?cache=${cacheBuster}`);
      return response.data;
    } catch (error) {
      throw error;
    }
  },
  
  // Remover um usuário da lista de aceitos
  removeAcceptedUser: async (userId: string) => {
    try {
      const response = await apiClient.delete(`/api/sync/accepted/${userId}?cache=${cacheBuster}`);
      return response.data;
    } catch (error) {
      throw error;
    }
  },
  // Get sync status for all databases
  getSyncStatus: async () => {
    try {
      // Tenta obter status da API
      try {
        const response = await apiClient.get(`/api/sync/status?cache=${cacheBuster}`);
        
        // Verificar campos obrigatórios na resposta
        if (response.data && response.data.statuses) {
          
          return response.data;
        } else {
          throw new Error("Resposta sem campo 'statuses' válido");
        }
      } catch (error) {
        // Se falhar, retornar estrutura vazia mas válida
        return {
          success: true,
          statuses: [],
          summary: {
            total_databases: 0,
            sync_enabled_count: 0,
            sync_disabled_count: 0,
            never_synced_count: 0,
            successful_sync_count: 0,
            failed_sync_count: 0,
            total_discrepancies: 0,
            total_unmanaged_users: 0,
            pending_discrepancies: 0,
            pending_unmanaged_users: 0,
            total_missing_users: 0,
            non_compliant_databases: 0,
            compliant_databases: 0
          }
        };
      }
    } catch (error) {
      console.error("Error fetching sync status:", error);
      // Retornar estrutura vazia válida em vez de lançar exceção
      return {
        success: true,
        statuses: [],
        summary: null,
        message: "Erro interno ao obter status de sincronização"
      };
    }
  },

  // Get all sync results - tentando múltiplos endpoints
  getSyncResults: async () => {
    try {
      // Tentar múltiplos endpoints em sequência
      try {
        const response = await apiClient.get(`/api/sync?cache=${cacheBuster}`);
        return response.data;
      } catch (firstError) {
        try {
          // Endpoint alternativo
          const altResponse = await apiClient.get(`/api/sync/history?cache=${cacheBuster}`);
          return altResponse.data;
        } catch (secondError) {
          try {
            // Último endpoint possível
            const lastResponse = await apiClient.get(`/api/configuration/sync/history?cache=${cacheBuster}`);
            return lastResponse.data;
          } catch (thirdError) {
            // Se todas as tentativas falharem, retornar uma estrutura vazia válida
            console.warn("Não foi possível obter resultados de sincronização de nenhum endpoint.");
            return {
              success: false,
              results: [],
              message: "Não foi possível obter resultados de sincronização"
            };
          }
        }
      }
    } catch (error) {
      // Propagar o erro para ser tratado pela aplicação
      console.error("Erro crítico ao tentar obter resultados de sincronização", error);
      return {
        success: false,
        results: [],
        message: `Erro ao obter resultados: ${error instanceof Error ? error.message : 'Erro desconhecido'}`
      };
    }
  },

  // Get discrepancies for a specific sync result - com múltiplos endpoints
  getDiscrepancies: async (resultId: string) => {
    try {
      // Tentar múltiplos endpoints em sequência
      try {
        const response = await apiClient.get(`/api/sync/discrepancies/${resultId}?cache=${cacheBuster}`);

        // Processar status das discrepâncias para confirmar se alguma já está aceita ou corrigida
        if (response.data && response.data.discrepancies && Array.isArray(response.data.discrepancies)) {
          // Verificar discrepâncias aceitas ou corrigidas no backend
          const processedResponse = {
            ...response.data,
            discrepancies: response.data.discrepancies.map((disc: any) => {
              // Garantir que o campo status seja adequadamente mapeado
              if (disc.status === 'accepted') {
                return { ...disc, corrected: true, status: 'accepted' };
              }
              if (disc.status === 'corrected') {
                return { ...disc, corrected: true };
              }
              return disc;
            })
          };
          return processedResponse;
        }

        return response.data;
      } catch (firstError) {
        try {
          // Endpoint alternativo
          const altResponse = await apiClient.get(`/api/sync/${resultId}/discrepancies?cache=${cacheBuster}`);

          // Processar status das discrepâncias para confirmar se alguma já está aceita
          if (altResponse.data && altResponse.data.discrepancies && Array.isArray(altResponse.data.discrepancies)) {
            // Verificar discrepâncias aceitas no backend
            const processedResponse = {
              ...altResponse.data,
              discrepancies: altResponse.data.discrepancies.map((disc: any) => {
                // Garantir que o campo status seja adequadamente mapeado
                if (disc.status === 'accepted') {
                  return { ...disc, corrected: true, status: 'accepted' };
                }
                if (disc.status === 'corrected') {
                  return { ...disc, corrected: true };
                }
                return disc;
              })
            };
            return processedResponse;
          }

          return altResponse.data;
        } catch (secondError) {
          // Último endpoint possível - tenta buscar dados de todos os resultados e filtrar manualmente
          const allResultsResponse = await apiClient.get(`/api/sync?cache=${cacheBuster}`);

          // Se conseguiu buscar todos os resultados, filtra manualmente por ID
          if (allResultsResponse.data && allResultsResponse.data.results) {
            const targetResult = allResultsResponse.data.results.find((r: any) => r.id === resultId);

            if (targetResult && targetResult.discrepancies) {
              // Processar status das discrepâncias nos resultados encontrados
              const processedDiscrepancies = targetResult.discrepancies.map((disc: any) => {
                // Garantir que o campo status seja adequadamente mapeado
                if (disc.status === 'accepted') {
                  return { ...disc, corrected: true, status: 'accepted' };
                }
                return disc;
              });

              return {
                success: true,
                discrepancies: processedDiscrepancies
              };
            }
          }

          // Se chegar aqui é porque não encontramos as discrepâncias
          throw new Error("Não foi possível encontrar as discrepâncias");
        }
      }
    } catch (error) {
      // Propagar o erro para ser tratado pela aplicação
      throw error;
    }
  },

  // Get all pending discrepancies with optional filters
  getPendingDiscrepancies: async (filters?: { serverId?: string; type?: string }) => {
    try {
      console.log('SYNC SERVICE - Buscando discrepâncias pendentes com filtros:', filters);
      
      // Build query parameters
      let queryParams = `cache=${cacheBuster}`;
      
      if (filters?.serverId && filters.serverId !== 'all') {
        queryParams += `&server_id=${filters.serverId}`;
      }
      
      if (filters?.type && filters.type !== 'all') {
        queryParams += `&type=${filters.type}`;
      }
      
      const response = await apiClient.get(`/api/sync/discrepancies/pending?${queryParams}`);
      
      console.log('SYNC SERVICE - Discrepâncias pendentes recebidas:', response.data);
      
      // Processar status das discrepâncias
      if (response.data && response.data.discrepancies && Array.isArray(response.data.discrepancies)) {
        const processedResponse = {
          ...response.data,
          discrepancies: response.data.discrepancies.map((disc: any) => {
            // Garantir que o campo status seja adequadamente mapeado
            if (disc.status === 'accepted') {
              return { ...disc, corrected: true, status: 'accepted' };
            }
            if (disc.status === 'corrected') {
              return { ...disc, corrected: true };
            }
            return disc;
          })
        };
        return processedResponse;
      }
      
      return response.data;
    } catch (error) {
      console.error('SYNC SERVICE - Erro ao buscar discrepâncias pendentes:', error);
      
      // Se falhar, retornar estrutura vazia
      return {
        success: false,
        discrepancies: [],
        filters: filters || {},
        message: 'Erro ao buscar discrepâncias pendentes'
      };
    }
  },

  // Start synchronization for all databases - versão robusta
  executeSyncAll: async () => {
    try {
      console.log("SYNC SERVICE - Iniciando sincronização de todos os bancos");
      
      // Tentar múltiplos endpoints
      try {
        // Primeiro tenta o endpoint correto com timestamp para evitar cache
        const response = await apiClient.post(`/api/sync?cache=${cacheBuster}`);
        console.log("SYNC SERVICE - Sincronização iniciada com sucesso via endpoint principal");
        return response.data;
      } catch (error) {
        console.warn("SYNC SERVICE - Falha no primeiro endpoint, tentando alternativas:", error);
        
        // Tentar endpoints alternativos em sequência
        try {
          const altResponse = await apiClient.post('/api/sync/trigger');
          console.log("SYNC SERVICE - Sincronização iniciada com sucesso via endpoint alternativo 1");
          return altResponse.data;
        } catch (altError) {
          console.warn("SYNC SERVICE - Falha no segundo endpoint, tentando último endpoint:", altError);
          
          // Último endpoint possível - provavelmente não funcionará, mas mantido por compatibilidade
          const lastResponse = await apiClient.post(`/api/sync/execute?cache=${cacheBuster}`);
          console.log("SYNC SERVICE - Sincronização iniciada com sucesso via endpoint alternativo 2");
          return lastResponse.data;
        }
      }
    } catch (finalError) {
      console.error("SYNC SERVICE - Erro em todos os endpoints de sincronização:", finalError);
      // Propagar o erro para ser tratado pela aplicação
      throw finalError;
    }
  },

  // Start synchronization for a specific server - versão robusta
  executeDatabaseSync: async (serverID: string) => {
    try {
      // Verificar ID de servidor inválido
      if (!serverID || serverID.includes("undefined") || serverID.includes("null") || serverID.length < 5) {
        console.error(`SYNC SERVICE - ID de servidor inválido: "${serverID}"`);
        throw new Error(`ID de servidor inválido: "${serverID}"`);
      }
      
      console.log(`SYNC SERVICE - Iniciando sincronização do servidor ${serverID}`);

      // Usar o endpoint correto diretamente
      try {
        // O endpoint correto é /api/sync/database/{serverID} com POST
        // Não precisamos verificar o formato do ID - confiamos que o ID no card é válido
        const response = await apiClient.post(`/api/sync/database/${serverID}?cache=${cacheBuster}`);
        console.log("SYNC SERVICE - Sincronização de servidor específico iniciada com sucesso");
        return response.data;
      } catch (error) {
        console.warn("SYNC SERVICE - Falha na sincronização do servidor:", error);

        // Tentar endpoint alternativo como último recurso
        try {
          // Payload com dados corretos para o endpoint de configuração
          const payload = {
            database_id: serverID, // Importante: usando database_id em vez de server_id
            direction: 'both'
          };

          // Endpoint alternativo com payload correto
          const lastResponse = await apiClient.post('/api/configuration/sync/trigger', payload);
          console.log("SYNC SERVICE - Sincronização de servidor específico iniciada com sucesso via endpoint alternativo");
          return lastResponse.data;
        } catch (altError) {
          console.error("SYNC SERVICE - Falha em todos os endpoints de sincronização:", altError);
          throw altError;
        }
      }
    } catch (finalError) {
      console.error("SYNC SERVICE - Erro em todos os endpoints de sincronização de servidor específico:", finalError);
      // Propagar o erro para ser tratado pela aplicação
      throw finalError;
    }
  },

  // Correct a specific discrepancy - versão robusta
  correctDiscrepancy: async (discrepancyId: string) => {
    try {
      console.log(`SYNC SERVICE - Corrigindo discrepância ${discrepancyId}`);
      
      try {
        // Primeiro tenta o endpoint principal com timestamp para evitar cache
        const response = await apiClient.post(`/api/sync/correct/${discrepancyId}?cache=${cacheBuster}`);
        console.log("SYNC SERVICE - Discrepância corrigida com sucesso");
        return response.data;
      } catch (error) {
        console.warn("SYNC SERVICE - Falha no endpoint para correção de discrepância:", error);
        
        // Tentar endpoint alternativo
        const altResponse = await apiClient.post(`/api/sync/discrepancies/correct/${discrepancyId}?cache=${cacheBuster}`);
        console.log("SYNC SERVICE - Discrepância corrigida com sucesso via endpoint alternativo");
        return altResponse.data;
      }
    } catch (finalError) {
      console.error("SYNC SERVICE - Erro ao corrigir discrepância:", finalError);
      // Propagar o erro para ser tratado pela aplicação
      throw finalError;
    }
  },

  // Correct all discrepancies for a server - versão robusta
  correctAllDiscrepancies: async (serverID: string) => {
    try {
      // Verificar se o ID do servidor é válido
      if (!serverID || serverID === 'undefined' || serverID === 'null') {
        console.error("SYNC SERVICE - ID do servidor inválido:", serverID);
        throw new Error("ID do servidor é obrigatório para corrigir todas as discrepâncias");
      }

      console.log(`SYNC SERVICE - Corrigindo todas as discrepâncias para o servidor ${serverID}`);

      try {
        // Primeiro tenta o endpoint principal com timestamp para evitar cache
        const response = await apiClient.post(`/api/sync/correct-all/${serverID}?cache=${cacheBuster}`);
        console.log("SYNC SERVICE - Todas as discrepâncias corrigidas com sucesso");
        return response.data;
      } catch (error) {
        console.warn("SYNC SERVICE - Falha no primeiro endpoint para correção em massa, tentando alternativas:", error);

        // Tentar endpoints alternativos
        try {
          const altResponse = await apiClient.post(`/api/sync/correctall/${serverID}?cache=${cacheBuster}`);
          console.log("SYNC SERVICE - Todas as discrepâncias corrigidas com sucesso via endpoint alternativo 1");
          return altResponse.data;
        } catch (altError) {
          console.warn("SYNC SERVICE - Falha no segundo endpoint para correção em massa:", altError);

          // Último endpoint possível
          const lastResponse = await apiClient.post(`/api/sync/discrepancies/correctall/${serverID}?cache=${cacheBuster}`);
          console.log("SYNC SERVICE - Todas as discrepâncias corrigidas com sucesso via endpoint alternativo 2");
          return lastResponse.data;
        }
      }
    } catch (finalError) {
      console.error("SYNC SERVICE - Erro em todos os endpoints de correção em massa:", finalError);
      // Propagar o erro para ser tratado pela aplicação
      throw finalError;
    }
  },

  // Get database credentials for a user
  getDatabaseCredentials: async (userId: string) => {
    const response = await apiClient.get(`/api/sync/credentials/${userId}`);
    return response.data;
  },

  // Get database credentials for a specific server and user
  getDatabaseCredentialsByDatabase: async (userId: string, serverID: string) => {
    const response = await apiClient.get(`/api/sync/credentials/${userId}/${serverID}`);
    return response.data;
  },

  // Update or create database credentials
  updateDatabaseCredentials: async (userId: string, data: any) => {
    const response = await apiClient.post(`/api/sync/credentials/${userId}`, data);
    return response.data;
  },

  // Update or create universal credentials
  updateUniversalCredentials: async (userId: string, data: any) => {
    // Now using the dedicated endpoint for universal credentials
    const payload = {
      username: data.username,
      password: data.password
    };
    const response = await apiClient.post('/api/users/universal-credentials', payload);
    return response.data;
  },

  // Get all databases
  getDatabases: async () => {
    const response = await apiClient.get('/api/databases');
    return response.data;
  },

  // Test database credentials
  testDatabaseCredentials: async (userId: string, data: any) => {
    const response = await apiClient.post(`/api/sync/credentials/${userId}/test`, data);
    return response.data;
  },

  // Get sync configuration
  getSyncConfig: async () => {
    try {
      console.log('SYNC SERVICE - Buscando configuração com cache buster:', cacheBuster);
      const response = await apiClient.get(`/api/configuration/sync?cache=${cacheBuster}`);
      console.log('SYNC SERVICE - Resposta bruta do backend:', response.data);
      
      // O backend agora retorna {sync: {...}} então vamos padronizar para {config: {...}}
      if (response.data && response.data.sync) {
        console.log('SYNC SERVICE - Configuração encontrada em sync:', response.data.sync);
        response.data.config = response.data.sync;
      }
      
      console.log('SYNC SERVICE - Resposta final:', response.data);
      return response.data;
    } catch (error) {
      console.error("Error fetching sync configuration:", error);
      throw error;
    }
  },

  // Update sync configuration
  updateSyncConfig: async (config: any) => {
    try {
      const payload = { sync: config };
      const response = await apiClient.post('/api/configuration/sync', payload);
      
      // Mapear resposta para formato esperado pelo componente
      if (response.data && response.data.sync) {
        response.data.config = response.data.sync;
      }
      
      // Resetar cache após atualização
      resetCache();
      
      // Disparar evento de atualização
      const syncConfigUpdatedEvent = new CustomEvent('syncConfigUpdated', {
        detail: { timestamp: Date.now() }
      });
      window.dispatchEvent(syncConfigUpdatedEvent);
      
      return response.data;
    } catch (error) {
      console.error("Error saving sync configuration:", error);
      resetCache();
      throw error;
    }
  },
  
  // Trigger manual synchronization for a specific server
  triggerSync: async (serverID: string, direction: string = 'both') => {
    try {
      const payload = {
        database_id: serverID,
        direction: direction
      };
      
      const response = await apiClient.post('/api/configuration/sync/trigger', payload);
      resetCache();
      
      return response.data;
    } catch (error) {
      console.error("Error triggering sync:", error);
      resetCache();
      throw error;
    }
  }
};

export default syncService;