import React, { useState, useEffect } from 'react';
import {
  Box,
  Card,
  CardContent,
  Typography,
  Switch,
  TextField,
  FormControlLabel,
  Grid,
  Button,
  Chip,
  IconButton,
  Alert,
  CircularProgress,
  Divider,
  Slider,
  FormGroup,
  Collapse,
  Tooltip,
} from '@mui/material';
import {
  Save as SaveIcon,
  Delete as DeleteIcon,
  Add as AddIcon,
  PlayArrow as PlayIcon,
  Info as InfoIcon,
  ExpandMore as ExpandMoreIcon,
  ExpandLess as ExpandLessIcon,
} from '@mui/icons-material';
import { useTranslation } from 'react-i18next';
import queryAuditService, { QueryAuditConfig } from '../../services/queryAuditService';
import { useNotification } from '../../contexts/NotificationContext';
import { QueryAuditPrerequisites } from './QueryAuditPrerequisites';

interface QueryAuditConfigProps {
  serverId: string;
  serverName: string;
  serverType: string;
}

const QueryAuditConfigComponent: React.FC<QueryAuditConfigProps> = ({
  serverId,
  serverName,
  serverType,
}) => {
  const { t } = useTranslation(['queryAudit', 'common']);
  const { showSuccess, showError } = useNotification();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [config, setConfig] = useState<QueryAuditConfig | null>(null);
  const [newExcludedUser, setNewExcludedUser] = useState('');
  const [newExcludedPattern, setNewExcludedPattern] = useState('');
  const [showAdvanced, setShowAdvanced] = useState(false);

  useEffect(() => {
    loadConfig();
  }, [serverId]);

  const loadConfig = async () => {
    try {
      setLoading(true);
      const data = await queryAuditService.getConfig(serverId);
      setConfig(data);
    } catch (error: any) {
      showError(t('queryAudit:errors.loadConfig'));
    } finally {
      setLoading(false);
    }
  };

  const handleSave = async () => {
    if (!config) return;

    try {
      setSaving(true);
      await queryAuditService.saveConfig(serverId, config);
      showSuccess(t('queryAudit:success.configSaved'));
    } catch (error: any) {
      showError(t('queryAudit:errors.saveConfig'));
    } finally {
      setSaving(false);
    }
  };

  const handleEnable = async () => {
    try {
      setSaving(true);
      await queryAuditService.enableAuditing(serverId);
      await loadConfig();
      showSuccess(t('queryAudit:success.auditingEnabled'));
    } catch (error: any) {
      showError(t('queryAudit:errors.enableAuditing'));
    } finally {
      setSaving(false);
    }
  };

  const addExcludedUser = () => {
    if (newExcludedUser && config) {
      setConfig({
        ...config,
        excluded_users: [...(config.excluded_users || []), newExcludedUser],
      });
      setNewExcludedUser('');
    }
  };

  const removeExcludedUser = (user: string) => {
    if (config) {
      setConfig({
        ...config,
        excluded_users: (config.excluded_users || []).filter((u) => u !== user),
      });
    }
  };

  const addExcludedPattern = () => {
    if (newExcludedPattern && config) {
      setConfig({
        ...config,
        excluded_query_patterns: [...(config.excluded_query_patterns || []), newExcludedPattern],
      });
      setNewExcludedPattern('');
    }
  };

  const removeExcludedPattern = (pattern: string) => {
    if (config) {
      setConfig({
        ...config,
        excluded_query_patterns: (config.excluded_query_patterns || []).filter((p) => p !== pattern),
      });
    }
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" p={3}>
        <CircularProgress />
      </Box>
    );
  }

  if (!config) {
    return (
      <Alert severity="error">{t('queryAudit:errors.noConfig')}</Alert>
    );
  }

  return (
    <>
      {/* Prerequisites Status */}
      <Box mb={3}>
        <QueryAuditPrerequisites
          serverId={serverId}
          serverType={serverType}
          onRefresh={loadConfig}
        />
      </Box>

      <Card>
        <CardContent>
          <Box display="flex" justifyContent="space-between" alignItems="center" mb={3}>
            <Typography variant="h6">
              {t('queryAudit:config.title', { serverName })}
            </Typography>
            <Box>
              {!config.enabled && (
                <Button
                  variant="contained"
                  color="primary"
                  startIcon={<PlayIcon />}
                  onClick={handleEnable}
                  disabled={saving}
                  sx={{ mr: 1 }}
                >
                  {t('queryAudit:config.enableAuditing')}
                </Button>
              )}
              <Button
                variant="contained"
                color="primary"
                startIcon={<SaveIcon />}
                onClick={handleSave}
                disabled={saving}
              >
                {t('common:save')}
              </Button>
            </Box>
          </Box>

        <Grid container spacing={3}>
          {/* Basic Configuration */}
          <Grid item xs={12}>
            <FormControlLabel
              control={
                <Switch
                  checked={config.enabled}
                  onChange={(e) => setConfig({ ...config, enabled: e.target.checked })}
                  color="primary"
                />
              }
              label={t('queryAudit:config.enabled')}
            />
          </Grid>

          <Grid item xs={12} md={6}>
            <Typography gutterBottom>{t('queryAudit:config.retentionDays')}</Typography>
            <Box display="flex" alignItems="center">
              <Slider
                value={config.retention_days}
                onChange={(_, value) => setConfig({ ...config, retention_days: value as number })}
                min={1}
                max={30}
                marks
                valueLabelDisplay="on"
                disabled={!config.enabled}
              />
              <Typography ml={2}>{t('common:days')}</Typography>
            </Box>
          </Grid>

          <Grid item xs={12} md={6}>
            <TextField
              label={t('queryAudit:config.minDuration')}
              type="number"
              value={config.min_duration_ms}
              onChange={(e) => setConfig({ ...config, min_duration_ms: parseInt(e.target.value) || 0 })}
              fullWidth
              disabled={!config.enabled}
              InputProps={{ endAdornment: 'ms' }}
            />
          </Grid>

          {/* Query Types */}
          <Grid item xs={12}>
            <Typography variant="subtitle1" gutterBottom>
              {t('queryAudit:config.captureTypes')}
            </Typography>
            <FormGroup row>
              <FormControlLabel
                control={
                  <Switch
                    checked={config.capture_select}
                    onChange={(e) => setConfig({ ...config, capture_select: e.target.checked })}
                    disabled={!config.enabled}
                  />
                }
                label="SELECT"
              />
              <FormControlLabel
                control={
                  <Switch
                    checked={config.capture_insert}
                    onChange={(e) => setConfig({ ...config, capture_insert: e.target.checked })}
                    disabled={!config.enabled}
                  />
                }
                label="INSERT"
              />
              <FormControlLabel
                control={
                  <Switch
                    checked={config.capture_update}
                    onChange={(e) => setConfig({ ...config, capture_update: e.target.checked })}
                    disabled={!config.enabled}
                  />
                }
                label="UPDATE"
              />
              <FormControlLabel
                control={
                  <Switch
                    checked={config.capture_delete}
                    onChange={(e) => setConfig({ ...config, capture_delete: e.target.checked })}
                    disabled={!config.enabled}
                  />
                }
                label="DELETE"
              />
              <FormControlLabel
                control={
                  <Switch
                    checked={config.capture_ddl}
                    onChange={(e) => setConfig({ ...config, capture_ddl: e.target.checked })}
                    disabled={!config.enabled}
                  />
                }
                label="DDL"
              />
              <FormControlLabel
                control={
                  <Switch
                    checked={config.capture_dcl}
                    onChange={(e) => setConfig({ ...config, capture_dcl: e.target.checked })}
                    disabled={!config.enabled}
                  />
                }
                label="DCL"
              />
            </FormGroup>
          </Grid>

          {/* Excluded Users */}
          <Grid item xs={12} md={6}>
            <Typography variant="subtitle1" gutterBottom>
              {t('queryAudit:config.excludedUsers')}
              <Tooltip title={t('queryAudit:config.excludedUsersHelp') as string}>
                <IconButton size="small">
                  <InfoIcon fontSize="small" />
                </IconButton>
              </Tooltip>
            </Typography>
            <Box display="flex" mb={1}>
              <TextField
                value={newExcludedUser}
                onChange={(e) => setNewExcludedUser(e.target.value)}
                placeholder={t('queryAudit:config.addUser') as string}
                size="small"
                fullWidth
                disabled={!config.enabled}
                onKeyPress={(e) => e.key === 'Enter' && addExcludedUser()}
              />
              <IconButton onClick={addExcludedUser} disabled={!config.enabled}>
                <AddIcon />
              </IconButton>
            </Box>
            <Box>
              {(config.excluded_users || []).map((user) => (
                <Chip
                  key={user}
                  label={user}
                  onDelete={() => removeExcludedUser(user)}
                  size="small"
                  sx={{ m: 0.5 }}
                  disabled={!config.enabled}
                />
              ))}
            </Box>
          </Grid>

          {/* Excluded Patterns */}
          <Grid item xs={12} md={6}>
            <Typography variant="subtitle1" gutterBottom>
              {t('queryAudit:config.excludedPatterns')}
              <Tooltip title={t('queryAudit:config.excludedPatternsHelp') as string}>
                <IconButton size="small">
                  <InfoIcon fontSize="small" />
                </IconButton>
              </Tooltip>
            </Typography>
            <Box display="flex" mb={1}>
              <TextField
                value={newExcludedPattern}
                onChange={(e) => setNewExcludedPattern(e.target.value)}
                placeholder={t('queryAudit:config.addPattern') as string}
                size="small"
                fullWidth
                disabled={!config.enabled}
                onKeyPress={(e) => e.key === 'Enter' && addExcludedPattern()}
              />
              <IconButton onClick={addExcludedPattern} disabled={!config.enabled}>
                <AddIcon />
              </IconButton>
            </Box>
            <Box>
              {(config.excluded_query_patterns || []).map((pattern) => (
                <Chip
                  key={pattern}
                  label={pattern}
                  onDelete={() => removeExcludedPattern(pattern)}
                  size="small"
                  sx={{ m: 0.5 }}
                  disabled={!config.enabled}
                />
              ))}
            </Box>
          </Grid>

          {/* Advanced Settings */}
          <Grid item xs={12}>
            <Divider sx={{ my: 2 }} />
            <Button
              onClick={() => setShowAdvanced(!showAdvanced)}
              endIcon={showAdvanced ? <ExpandLessIcon /> : <ExpandMoreIcon />}
            >
              {t('queryAudit:config.advancedSettings')}
            </Button>
            <Collapse in={showAdvanced}>
              <Alert severity="info" sx={{ mt: 2 }}>
                {serverType === 'postgres' && t('queryAudit:config.postgresInfo')}
                {(serverType === 'mysql' || serverType === 'mariadb') && t('queryAudit:config.mysqlInfo')}
                {serverType === 'mssql' && t('queryAudit:config.mssqlInfo')}
              </Alert>
            </Collapse>
          </Grid>
        </Grid>
      </CardContent>
    </Card>
    </>
  );
};

export default QueryAuditConfigComponent;