import React, { useState } from 'react';
import { useTranslation } from '../../i18n/i18n';
import { 
  Box, 
  Button, 
  Container, 
  TextField, 
  Typography, 
  Paper, 
  Alert,
  IconButton,
  InputAdornment,
  FormControl,
  Select,
  MenuItem,
  SelectChangeEvent,
  useTheme,
  useMediaQuery,
  Fade,
  Stack,
  Card,
  Grid,
  CardContent
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import { 
  Visibility, 
  VisibilityOff, 
  Language, 
  LockOutlined,
  PersonOutlined,
  LoginOutlined,
  ShieldOutlined,
  SecurityOutlined,
  VerifiedUserOutlined,
  GppGoodOutlined,
  PolicyOutlined,
  AdminPanelSettingsOutlined,
  FingerprintOutlined
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';

interface LoginPageProps {
  onLogin: (username: string, password: string) => Promise<boolean>;
}

const LoginPage: React.FC<LoginPageProps> = ({ onLogin }) => {
  const { t, i18n } = useTranslation('auth');
  const { t: tCommon } = useTranslation('common');
  const navigate = useNavigate();
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [language, setLanguage] = useState(i18n.language);
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const isDarkMode = theme.palette.mode === 'dark';


  const handleLanguageChange = (event: SelectChangeEvent) => {
    const newLanguage = event.target.value;
    setLanguage(newLanguage);
    i18n.changeLanguage(newLanguage);
  };

  React.useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    const invalidToken = urlParams.get('invalid_token');
    
    if (invalidToken) {
      document.cookie = 'dbmanager_session=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/;';
      document.cookie = 'csrf_token=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/;';
      
      localStorage.removeItem('auth_token');
      localStorage.removeItem('user_info');
      localStorage.removeItem('currentUser');
      
      setError(t('login.sessionExpired') || 'Sua sessão expirou. Por favor, faça login novamente.');
      
      if (window.location.search) {
        const newUrl = window.location.pathname;
        window.history.replaceState({}, document.title, newUrl);
      }
    }
  }, [t]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!username || !password) {
      setError(t('login.error') as string || 'Invalid email or password');
      return;
    }
    
    setLoading(true);
    setError('');
    
    try {
      const loginSuccess = await onLogin(username, password);
      
      if (loginSuccess) {
        navigate('/dashboard');
      } else {
        setError(t('login.error') as string || 'Invalid email or password');
      }
    } catch (err: any) {
      if (err && err.message) {
        setError(err.message);
      } else {
        setError(tCommon('error') as string || 'Error');
      }
    } finally {
      setLoading(false);
    }
  };

  const handleSSOLogin = async () => {
    setLoading(true);
    setError('');
    
    try {
      // Chamar endpoint SSO init
      const response = await fetch('/api/auth/sso/init', {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      if (!response.ok) {
        const errorText = await response.text();
        throw new Error(errorText || 'SSO não está configurado');
      }

      const data = await response.json();
      
      if (data.authUrl) {
        // Redirecionar para a página de autenticação do provedor SSO
        window.location.href = data.authUrl;
      } else {
        throw new Error('URL de autenticação SSO não encontrada');
      }
    } catch (err: any) {
      setError(err.message || 'Erro ao inicializar SSO');
      setLoading(false);
    }
  };

  const features = [
    {
      icon: <ShieldOutlined fontSize="large" />,
      title: t('login.features.dataProtection.title'),
      description: t('login.features.dataProtection.description')
    },
    {
      icon: <VerifiedUserOutlined fontSize="large" />,
      title: t('login.features.accessControl.title'),
      description: t('login.features.accessControl.description')
    },
    {
      icon: <SecurityOutlined fontSize="large" />,
      title: t('login.features.completeAudit.title'),
      description: t('login.features.completeAudit.description')
    }
  ];

  return (
    <Box
      sx={{
        minHeight: '100vh',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        position: 'relative',
        background: isDarkMode
          ? '#1a1a1a'
          : '#e9ecef',
        overflow: 'hidden',
      }}
    >
      {/* Background com símbolos de proteção */}
      <Box
        sx={{
          position: 'absolute',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          opacity: 0.03,
          backgroundImage: `
            url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23000000' fill-opacity='1'%3E%3Cpath d='M30 1.586l-6.293 6.293a13.932 13.932 0 00-4.121 9.9v14.442c0 8.837 7.163 16 16 16h0c8.837 0 16-7.163 16-16V17.779a13.932 13.932 0 00-4.121-9.9L30 1.586z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E")
          `,
          backgroundSize: '100px 100px',
        }}
      />
      
      {/* Ícones flutuantes de segurança */}
      <GppGoodOutlined sx={{ position: 'absolute', top: '10%', left: '5%', fontSize: 200, opacity: 0.05 }} />
      <PolicyOutlined sx={{ position: 'absolute', bottom: '10%', right: '5%', fontSize: 150, opacity: 0.05 }} />
      <AdminPanelSettingsOutlined sx={{ position: 'absolute', top: '60%', left: '10%', fontSize: 180, opacity: 0.05 }} />

      {/* Language Selector - Floating */}
      <Box
        sx={{
          position: 'absolute',
          top: 30,
          right: 30,
          zIndex: 1000,
        }}
      >
        <Paper
          elevation={0}
          sx={{
            borderRadius: 15,
            background: isDarkMode 
              ? alpha(theme.palette.background.paper, 0.9)
              : '#ffffff',
            backdropFilter: 'blur(10px)',
            border: `1px solid ${alpha(theme.palette.divider, 0.2)}`,
          }}
        >
          <FormControl size="small">
            <Select
              value={language}
              onChange={handleLanguageChange}
              sx={{ 
                padding: '4px 12px',
                '& .MuiOutlinedInput-notchedOutline': { border: 'none' },
              }}
              startAdornment={
                <InputAdornment position="start">
                  <Language fontSize="small" color="primary" />
                </InputAdornment>
              }
            >
              <MenuItem value="en">English</MenuItem>
              <MenuItem value="pt">Português</MenuItem>
              <MenuItem value="es">Español</MenuItem>
            </Select>
          </FormControl>
        </Paper>
      </Box>

      {/* Login Modal Central */}
      <Container maxWidth="md">
        <Paper
          elevation={10}
          sx={{
            maxWidth: 900,
            mx: 'auto',
            borderRadius: 3,
            overflow: 'hidden',
            display: 'flex',
            position: 'relative',
            isolation: 'isolate',
          }}
        >
          <Grid container sx={{ background: '#ffffff' }}>
            {/* Lado esquerdo - Informações */}
            {!isMobile && (
              <Grid 
                item 
                md={5}
                sx={{
                  background: isDarkMode
                    ? 'linear-gradient(135deg, #2c2c2c 0%, #3a3a3a 100%)'
                    : 'linear-gradient(135deg, #e9ecef 0%, #ced4da 100%)',
                  padding: 4,
                  display: 'flex',
                  flexDirection: 'column',
                  justifyContent: 'center',
                  position: 'relative',
                }}
              >
                {/* Logo */}
                <Box sx={{ textAlign: 'center', marginBottom: 4 }}>
                  <Box
                    component="img"
                    src="https://i.ibb.co/KjtdPzvW/dbmanager2.png"
                    alt="DB-Manager Logo"
                    sx={{
                      width: '70%',
                      maxWidth: 200,
                      height: 'auto',
                      marginBottom: 2,
                      filter: isDarkMode ? 'brightness(10) invert(1)' : 'none',
                    }}
                  />
                  <Typography 
                    variant="h5" 
                    sx={{ 
                      color: isDarkMode ? 'white' : '#666',
                      fontWeight: 300,
                      letterSpacing: 1,
                    }}
                  >
                    {tCommon('app.description')}
                  </Typography>
                </Box>

                {/* Feature Cards */}
                <Stack spacing={2}>
                  {features.map((feature, index) => (
                    <Card
                      key={index}
                      sx={{
                        background: isDarkMode
                          ? alpha(theme.palette.common.white, 0.15)
                          : alpha(theme.palette.common.white, 0.4),
                        backdropFilter: 'blur(10px)',
                        border: isDarkMode
                          ? `1px solid ${alpha(theme.palette.common.white, 0.25)}`
                          : `1px solid ${alpha(theme.palette.common.white, 0.6)}`,
                      }}
                    >
                      <CardContent sx={{ display: 'flex', alignItems: 'center', padding: '12px 16px' }}>
                        <Box sx={{ color: isDarkMode ? 'white' : '#495057', marginRight: 2 }}>
                          {feature.icon}
                        </Box>
                        <Box>
                          <Typography variant="body1" sx={{ color: isDarkMode ? 'white' : '#212529', fontWeight: 600 }}>
                            {feature.title}
                          </Typography>
                          <Typography variant="caption" sx={{ color: isDarkMode ? alpha(theme.palette.common.white, 0.8) : '#6c757d' }}>
                            {feature.description}
                          </Typography>
                        </Box>
                      </CardContent>
                    </Card>
                  ))}
                </Stack>
              </Grid>
            )}

            {/* Lado direito - Formulário */}
            <Grid 
              item 
              xs={12} 
              md={7}
              sx={{
                padding: 4,
                display: 'flex',
                flexDirection: 'column',
                justifyContent: 'center',
                background: '#ffffff',
              }}
            >
              {/* Mobile Logo */}
              {isMobile && (
                <Box sx={{ textAlign: 'center', marginBottom: 3 }}>
                  <Box
                    component="img"
                    src="https://i.ibb.co/KjtdPzvW/dbmanager2.png"
                    alt="DB-Manager Logo"
                    sx={{
                      width: '50%',
                      maxWidth: 150,
                      height: 'auto',
                      marginBottom: 2,
                    }}
                  />
                </Box>
              )}

              {/* Subtítulo */}
              <Box sx={{ marginBottom: 3 }}>
                <Typography variant="body1" color="text.secondary">
                  {t('login.subtitle')}
                </Typography>
              </Box>

              {/* Error Alert */}
              {error && (
                <Fade in={true} timeout={300}>
                  <Alert
                    severity="error"
                    sx={{
                      marginBottom: 2,
                      borderRadius: 2,
                    }}
                  >
                    {error}
                  </Alert>
                </Fade>
              )}

              {/* Login Form */}
              <Box component="form" onSubmit={handleSubmit} noValidate>
                <Stack spacing={2.5}>
                  <TextField
                    fullWidth
                    label={t('login.username')}
                    value={username}
                    onChange={(e) => setUsername(e.target.value)}
                    variant="outlined"
                    autoComplete="username"
                    InputProps={{
                      startAdornment: (
                        <InputAdornment position="start">
                          <PersonOutlined color="action" />
                        </InputAdornment>
                      ),
                    }}
                    sx={{
                      '& .MuiOutlinedInput-root': {
                        backgroundColor: isDarkMode ? theme.palette.background.paper : '#ffffff',
                      },
                    }}
                  />

                  <TextField
                    fullWidth
                    label={t('login.password')}
                    type={showPassword ? 'text' : 'password'}
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    variant="outlined"
                    autoComplete="current-password"
                    InputProps={{
                      startAdornment: (
                        <InputAdornment position="start">
                          <LockOutlined color="action" />
                        </InputAdornment>
                      ),
                      endAdornment: (
                        <InputAdornment position="end">
                          <IconButton
                            onClick={() => setShowPassword(!showPassword)}
                            edge="end"
                          >
                            {showPassword ? <VisibilityOff /> : <Visibility />}
                          </IconButton>
                        </InputAdornment>
                      ),
                    }}
                    sx={{
                      '& .MuiOutlinedInput-root': {
                        backgroundColor: isDarkMode ? theme.palette.background.paper : '#ffffff',
                      },
                    }}
                  />

                  {/* Forgot password */}
                  <Box sx={{ textAlign: 'right' }}>
                    <Typography
                      variant="body2"
                      sx={{
                        color: theme.palette.primary.main,
                        cursor: 'pointer',
                        '&:hover': {
                          textDecoration: 'underline',
                        },
                      }}
                    >
                      {t('login.forgotPassword')}
                    </Typography>
                  </Box>

                  {/* Login Button */}
                  <Button
                    type="submit"
                    fullWidth
                    variant="contained"
                    size="large"
                    disabled={loading}
                    startIcon={<LoginOutlined />}
                    sx={{
                      padding: '12px',
                      textTransform: 'none',
                      fontSize: '1.1rem',
                      fontWeight: 600,
                      background: '#4285F4',
                      color: '#ffffff',
                      '&:hover': {
                        background: '#3174e0',
                      },
                    }}
                  >
                    {loading ? t('common:loading') : t('login.loginButton')}
                  </Button>

                  {/* SSO Button */}
                  <Button
                    fullWidth
                    variant="outlined"
                    size="large"
                    startIcon={<FingerprintOutlined />}
                    onClick={handleSSOLogin}
                    sx={{
                      padding: '12px',
                      textTransform: 'none',
                      fontSize: '1rem',
                      fontWeight: 500,
                      borderColor: '#e0e0e0',
                      color: '#5f6368',
                      marginTop: 2,
                      '&:hover': {
                        borderColor: '#dadce0',
                        background: '#f8f9fa',
                      },
                    }}
                  >
                    Single Sign-On (SSO)
                  </Button>
                </Stack>
              </Box>

              {/* Footer */}
              <Box sx={{ textAlign: 'center', marginTop: 4 }}>
                <Typography variant="caption" color="text.secondary">
                  {tCommon('app.name')} © {new Date().getFullYear()}
                </Typography>
              </Box>
            </Grid>
          </Grid>
        </Paper>
      </Container>
    </Box>
  );
};

export default LoginPage;
