import React, { useEffect, useState, useRef } from 'react';
import {
  Typography,
  Grid,
  Card,
  CardContent,
  Box,
  Chip,
  CircularProgress,
  CardActionArea,
  Avatar,
  Paper,
  alpha,
  useTheme,
  styled,
  Zoom,
  Button,
  Collapse
} from '@mui/material';
import {
  Dataset as DatabaseIcon,
  Storage as ServerIcon,
  CheckCircle as CheckCircleIcon,
  ErrorOutline as ErrorIcon,
  ArrowForward as ArrowForwardIcon
} from '@mui/icons-material';
import { useTranslation } from 'react-i18next';
import { StepProps, DatabaseType } from '../../types';
import StepLayout from '../shared/StepLayout';

// Selectable card with hover effects
const StyledCard = styled(Card)(({ theme }) => ({
  transition: 'all 0.3s ease',
  position: 'relative',
  overflow: 'hidden',
  height: '100%',
  cursor: 'pointer',
  '&:hover': {
    transform: 'translateY(-4px)',
    boxShadow: theme.shadows[4],
  },
  '&::after': {
    content: '""',
    position: 'absolute',
    inset: 0,
    transition: 'opacity 0.3s ease',
    opacity: 0,
    background: `linear-gradient(45deg, ${alpha(theme.palette.primary.main, 0.1)}, ${alpha(theme.palette.primary.light, 0.15)})`,
  },
  '&:hover::after': {
    opacity: 1,
  }
}));

// Selected card with highlight effect
const SelectedCard = styled(Card)(({ theme }) => ({
  border: `2px solid ${theme.palette.primary.main}`,
  boxShadow: `0 0 12px ${alpha(theme.palette.primary.main, 0.4)}`,
  position: 'relative',
  overflow: 'hidden',
  height: '100%',
  cursor: 'pointer',
  '&::after': {
    content: '""',
    position: 'absolute',
    inset: 0,
    background: `linear-gradient(45deg, ${alpha(theme.palette.primary.main, 0.15)}, ${alpha(theme.palette.primary.light, 0.2)})`,
  }
}));

// Error container with shake animation
const ErrorContainer = styled(Paper)(({ theme }) => ({
  padding: theme.spacing(1.5),
  marginTop: theme.spacing(2),
  backgroundColor: alpha(theme.palette.error.main, 0.1),
  border: `1px solid ${theme.palette.error.light}`,
  borderRadius: theme.shape.borderRadius,
  '@keyframes shake': {
    '0%, 100%': { transform: 'translateX(0)' },
    '10%, 30%, 50%, 70%, 90%': { transform: 'translateX(-5px)' },
    '20%, 40%, 60%, 80%': { transform: 'translateX(5px)' }
  }
}));

/**
 * Component for database selection step
 */
const DatabaseStep: React.FC<StepProps> = ({ state, dispatch, onNext }) => {
  const { t } = useTranslation(['requests', 'common', 'error']);
  const theme = useTheme();
  const [shakeError, setShakeError] = useState(false);
  const errorRef = useRef<HTMLDivElement>(null);
  const selectedCardRef = useRef<HTMLDivElement>(null);

  // Scroll to selected card when selected
  useEffect(() => {
    if (state.databaseName && selectedCardRef.current) {
      selectedCardRef.current.scrollIntoView({
        behavior: 'smooth',
        block: 'nearest'
      });
    }
  }, [state.databaseName]);

  // Handler for database change
  const handleDatabaseChange = async (dbId: string, dbName: string) => {
    // Show loading state
    dispatch({ type: 'SET_LOADING', payload: true });

    // Clear any previous errors
    if (state.errors.databaseName) {
      dispatch({
        type: 'SET_ERRORS',
        payload: { databaseName: '' }
      });
    }

    try {
      console.log(`Database selected: ${dbName} (ID: ${dbId})`);

      // Update state with selected database
      dispatch({ type: 'SET_DATABASE_NAME', payload: dbName });

      // Reset dependent fields
      dispatch({ type: 'SET_TABLES', payload: [] });

      // Database type specific handling
      if (state.databaseType === DatabaseType.POSTGRESQL || state.databaseType === DatabaseType.MSSQL || state.databaseType === DatabaseType.ORACLE) {
        // Fetch schemas for PostgreSQL, MSSQL or Oracle database using API directly
        try {
          const { serverService } = await import('../../../../services/api');
          console.log(`Fetching schemas for ${state.databaseType} database: ${dbName}`);
          const response = await serverService.getSchemas(state.serverId, dbName);

          if (response && response.schemas && Array.isArray(response.schemas)) {
            console.log(`Schemas found for ${dbName}:`, response.schemas);
            dispatch({ type: 'SET_SCHEMAS', payload: response.schemas });

            // If there's only one schema for PostgreSQL, we can select it automatically
            // For MSSQL, we want the user to see the schema selection step
            if (response.schemas.length === 1 && state.databaseType === DatabaseType.POSTGRESQL) {
              console.log(`Only one schema available (${response.schemas[0]}), selecting automatically`);
              dispatch({ type: 'SET_SCHEMA', payload: response.schemas[0] });
            }
          }
        } catch (error) {
          console.error(`Error fetching schemas for server ${state.serverId}, database ${dbName}:`, error);
          const fallbackSchemas = state.databaseType === DatabaseType.POSTGRESQL 
            ? ['public', 'information_schema', 'pg_catalog']
            : ['dbo']; // Default schema for MSSQL
          dispatch({ type: 'SET_SCHEMAS', payload: fallbackSchemas });
        }

        // Schema step will handle fetching tables when a schema is selected
      } else {
        // For MySQL, fetch tables directly using API
        try {
          const { serverService } = await import('../../../../services/api');
          console.log(`Fetching tables for ${state.databaseType} database: ${dbName}`);
          const response = await serverService.getTables(state.serverId, dbName);

          if (response && response.tables && Array.isArray(response.tables)) {
            const tables = response.tables.map(tableName => ({
              name: tableName,
              serverId: state.serverId,
              databaseName: dbName
            }));

            console.log(`${tables.length} tables found for database ${dbName}`);
            dispatch({ type: 'SET_TABLES_DATA', payload: tables });
          } else {
            console.warn(`No tables found for database ${dbName}`);
            dispatch({ type: 'SET_TABLES_DATA', payload: [] });
          }
        } catch (error) {
          console.error(`Error fetching tables for server ${state.serverId}, database ${dbName}:`, error);
          dispatch({ type: 'SET_TABLES_DATA', payload: [] });
        }
      }
    } catch (error) {
      console.error("Error processing database change:", error);
      dispatch({
        type: 'SET_ERRORS',
        payload: { databaseName: t('error.databaseProcessingError') }
      });
    } finally {
      dispatch({ type: 'SET_LOADING', payload: false });
    }
  };

  // Removida a função handleNext para evitar duplicação de botões
  // A validação é feita no componente principal do modal

  // Get avatar color based on database type
  const getDatabaseColor = (index: number, dbName: string) => {
    // Ensure different colors for each database
    const colors = [
      theme.palette.primary.main,
      theme.palette.secondary.main,
      theme.palette.info.main,
      theme.palette.success.main,
      theme.palette.warning.main
    ];

    // If name contains "pg" or "postgres", use blue
    if (dbName.toLowerCase().includes('pg') || dbName.toLowerCase().includes('postgres')) {
      return '#2B6CB0'; // PostgreSQL blue
    }

    // If name contains "mysql", use orange
    if (dbName.toLowerCase().includes('mysql')) {
      return '#E97E03'; // MySQL orange
    }

    // If name contains "sql server" or "mssql", use blue
    if (dbName.toLowerCase().includes('sql server') || dbName.toLowerCase().includes('mssql')) {
      return '#0078D4'; // SQL Server blue
    }

    // Alternate between colors
    return colors[index % colors.length];
  };

  // Get server name for display
  const getServerName = () => {
    const server = state.servers.find(s => s.id === state.serverId);
    return server ? server.name : '';
  };

  // Get database type name for display
  const getDatabaseTypeName = () => {
    switch (state.databaseType) {
      case DatabaseType.POSTGRESQL:
        return 'PostgreSQL';
      case DatabaseType.MYSQL:
        return 'MySQL';
      case DatabaseType.MSSQL:
        return 'SQL Server';
      default:
        return 'Database';
    }
  };

  return (
    <StepLayout
      title={String(t('wizard.steps.database'))}
      subtitle={String(t('wizard.databaseStepSubtitle'))}
      icon="database"
    >
      <Grid container spacing={3}>
        {state.isLoading ? (
          <Grid item xs={12} display="flex" justifyContent="center">
            <CircularProgress />
          </Grid>
        ) : state.databases.length === 0 ? (
          <Grid item xs={12}>
            <Box
              sx={{
                display: 'flex',
                alignItems: 'center',
                p: 2,
                bgcolor: alpha(theme.palette.error.light, 0.1),
                color: theme.palette.error.main,
                borderRadius: 2,
                boxShadow: '0 2px 8px rgba(0,0,0,0.08)'
              }}
            >
              <ErrorIcon sx={{ mr: 1 }} />
              <Typography>
                {state.errors.databaseName || t('wizard.error.noDatabasesAvailable')}
              </Typography>
            </Box>
          </Grid>
        ) : (
          <Grid item xs={12}>
            <Typography variant="h6" gutterBottom sx={{ mb: 2, fontWeight: 500 }}>
              {t('wizard.selectDatabase')}
            </Typography>

            <Grid container spacing={2}>
              {state.databases.map((database, index) => {
                const isSelected = database.name === state.databaseName;
                const CardComponent = isSelected ? SelectedCard : StyledCard;
                const dbColor = getDatabaseColor(index, database.name);

                return (
                  <Zoom
                    in={true}
                    style={{ transitionDelay: `${index * 50}ms` }}
                    key={database.id}
                  >
                    <Grid item xs={12} sm={6} md={4}
                      ref={isSelected ? selectedCardRef : undefined}
                    >
                      <CardComponent
                        elevation={isSelected ? 3 : 1}
                        onClick={() => handleDatabaseChange(database.id, database.name)}
                      >
                        <CardActionArea
                          sx={{
                            height: '100%',
                            display: 'flex',
                            flexDirection: 'column',
                            alignItems: 'stretch',
                            p: 0.5
                          }}
                        >
                          <CardContent>
                            <Box display="flex" alignItems="center" mb={1}>
                              <Avatar
                                sx={{
                                  bgcolor: dbColor,
                                  color: '#fff',
                                  width: 48,
                                  height: 48,
                                  mr: 1.5,
                                  boxShadow: isSelected ? `0 0 0 2px ${alpha(dbColor, 0.5)}` : 'none'
                                }}
                              >
                                <DatabaseIcon />
                              </Avatar>
                              <Box flex={1}>
                                <Typography variant="h6" component="div" noWrap sx={{ fontWeight: isSelected ? 600 : 500 }}>
                                  {database.name}
                                </Typography>
                                <Box display="flex" alignItems="center" gap={1}>
                                  <ServerIcon fontSize="small" color="disabled" />
                                  <Typography variant="caption" color="text.secondary" noWrap>
                                    {`${getDatabaseTypeName()} | ${getServerName()}`}
                                  </Typography>
                                </Box>
                              </Box>
                            </Box>

                            <Box display="flex" justifyContent="space-between" alignItems="center" mt={1}>
                              <Chip
                                label={getDatabaseTypeName()}
                                size="small"
                                variant={isSelected ? "filled" : "outlined"}
                                color={
                                  state.databaseType === DatabaseType.POSTGRESQL
                                    ? 'primary'
                                    : state.databaseType === DatabaseType.MSSQL
                                      ? 'info'
                                      : 'secondary'
                                }
                              />

                              {isSelected && (
                                <Chip
                                  icon={<CheckCircleIcon fontSize="small" />}
                                  label={t('common:selected')}
                                  size="small"
                                  color="success"
                                />
                              )}
                            </Box>
                          </CardContent>
                        </CardActionArea>
                      </CardComponent>
                    </Grid>
                  </Zoom>
                );
              })}
            </Grid>

            {/* Error message with shake animation */}
            <Collapse in={!!state.errors.databaseName}>
              <Box ref={errorRef}>
                <ErrorContainer
                  sx={{
                    mt: 2,
                    animation: shakeError ? 'shake 0.5s' : 'none'
                  }}
                >
                  <Box display="flex" alignItems="center">
                    <ErrorIcon color="error" fontSize="small" sx={{ mr: 1 }} />
                    <Typography color="error" variant="body2">
                      {state.errors.databaseName}
                    </Typography>
                  </Box>
                </ErrorContainer>
              </Box>
            </Collapse>

            {/* O botão de navegação foi removido para evitar duplicação com os botões do modal principal */}
          </Grid>
        )}
      </Grid>
    </StepLayout>
  );
};

export default React.memo(DatabaseStep);
