import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import {
  Box,
  Typography,
  Paper,
  Button,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Chip,
  Alert,
  Snackbar,
  CircularProgress,
  Tabs,
  Tab,
  Divider,
  Tooltip,
  Zoom,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  IconButton,
  useTheme,
  styled
} from '@mui/material';
import { 
  Add as AddIcon, 
  Refresh as RefreshIcon,
  Visibility as VisibilityIcon,
  Info as InfoIcon,
  Close as CloseIcon,
  Check as CheckIcon,
  Storage as DatabaseIcon,
  TableChart as TableIcon,
  Code as OperationsIcon,
  Person as UserIcon,
  AccessTime as TimeIcon,
  Description as DescriptionIcon
} from '@mui/icons-material';
import RequestActionForm from '../../components/RequestActionForm';
import RequestForm from '../../components/RequestForm';
import { requestService } from '../../services/api';
import { authService } from '../../services/auth';

// Interface para as solicitações
interface Request {
  id: string;
  user: string;
  database: string;
  tables: string;
  operations: string;
  status: string;
  requestDate: string;
  justification?: string;
  // Service user fields
  isServiceUser?: boolean;
  serviceUserName?: string;
  serviceUserDescription?: string;
  requestedBy?: string; // Who requested the service user
}

// Interface para o usuário atual
interface CurrentUser {
  id: string;
  username: string;
  role: string;
}

// Styled button with animations
const AnimatedIconButton = styled(IconButton)(({ theme }) => ({
  transition: 'transform 0.3s ease-in-out, background-color 0.3s',
  '&:hover': {
    transform: 'scale(1.1)',
    backgroundColor: theme.palette.action.hover,
  }
}));

const PendingRequestsPage: React.FC = () => {
  const { t } = useTranslation(['requests', 'common', 'permissions']);
  const theme = useTheme();
  const [pendingRequests, setPendingRequests] = useState<Request[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [showNewRequestForm, setShowNewRequestForm] = useState(false);
  const [selectedRequest, setSelectedRequest] = useState<Request | null>(null);
  const [actionType, setActionType] = useState<'approve' | 'reject' | 'view' | 'details' | 'cancel' | 'revoke' | 'delete' | null>(null);
  const [detailsDialogOpen, setDetailsDialogOpen] = useState(false);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [currentUser, setCurrentUser] = useState<CurrentUser | null>(null);
  const [userRole, setUserRole] = useState<string>('');

  useEffect(() => {
    fetchUserRole();
    fetchRequests();
  }, []);
  
  // Busca o papel do usuário atual
  const fetchUserRole = async () => {
    try {
      const user = await authService.getCurrentUser();
      if (user) {
        setCurrentUser(user);
        setUserRole(user.role.toLowerCase());
      }
    } catch (error) {
      console.error('Error fetching user role:', error);
    }
  };

  const fetchRequests = async () => {
    setLoading(true);
    setError(null);
    try {
      // Chamar a API real para obter as requisições de acesso
      const response = await requestService.getRequests();
      
      if (response && response.success) {
        // Verificar se as solicitações existem e são um array (mesmo que vazio)
        const requestsArray = Array.isArray(response.requests) ? response.requests : [];
        
        if (requestsArray.length === 0) {
          setPendingRequests([]);
        } else {
          // Mapear a resposta da API para o formato esperado pelo componente
          const formattedRequests = requestsArray.map((req: any) => {
            // Converter arrays para strings com vírgulas para exibição na tabela
            const tablesString = Array.isArray(req.tables) 
              ? req.tables.join(', ') 
              : typeof req.tables === 'string' ? req.tables : '';
              
            const operationsString = Array.isArray(req.operations) 
              ? req.operations.map((op: string) => op.toLowerCase()).join(',')
              : typeof req.operations === 'string' ? req.operations : '';
            
            return {
              id: req.id || 'N/A',
              user: req.username || req.user_id || 'N/A',
              database: req.database || req.database_id || 'N/A',
              tables: tablesString,
              operations: operationsString,
              status: req.status || 'pending',
              requestDate: new Date(req.created_at).toLocaleString() || 'N/A',
              justification: req.reason || '',
              // Service user fields
              isServiceUser: req.is_service_user || false,
              serviceUserName: req.service_user_name || '',
              serviceUserDescription: req.service_user_description || '',
              requestedBy: req.is_service_user ? (req.username || req.user_id || 'N/A') : undefined
            };
          });
          
          // Filtrar apenas solicitações pendentes
          let pendingRequestsList = formattedRequests.filter((req: Request) => req.status === 'pending');
          
          // Filtrar solicitações se o usuário for um requester (mostrar apenas as próprias)
          if (userRole === 'requester' && currentUser) {
            pendingRequestsList = pendingRequestsList.filter((req: Request) => 
              req.user === currentUser.username || req.user === currentUser.id
            );
          }
          
          setPendingRequests(pendingRequestsList);
        }
      } else {
        setPendingRequests([]);
      }
    } catch (error) {
      console.error('Error fetching requests:', error);
      setError(t('fetchError') as string);
      setPendingRequests([]);
    } finally {
      setLoading(false);
    }
  };

  const handleNewRequest = () => {
    // Garantir que temos o currentUser antes de abrir o formulário
    if (!currentUser) {
      fetchUserRole().then(() => {
        setShowNewRequestForm(true);
      });
    } else {
      setShowNewRequestForm(true);
    }
  };

  const handleCloseNewRequestForm = () => {
    setShowNewRequestForm(false);
  };

  const handleRequestSubmitted = async (formData?: any) => {
    try {
      if (formData) {
        // Enviar os dados para a API
        console.log('Enviando dados para a API:', formData);
        // Preparar dados no formato esperado pela API
        // Log para debug
        console.log('Formato original do formData:', formData);

        // Garantir que a tabela esteja no formato correto (string ou array)
        const tablesData = Array.isArray(formData.tables) ? formData.tables : [formData.tables];

        // Mapear o tipo de acesso para as operações específicas que o backend espera
        let operations: string[] = [];
        // O accessType pode vir como propriedade direta ou propriedade de permissionType
        const accessType = formData.accessType || formData.permissionType;
        console.log('Tipo de acesso recebido:', accessType);

        switch (accessType) {
          case 'read':
          case 'READ':
            operations = ['SELECT'];
            break;
          case 'readwrite':
          case 'READWRITE':
            operations = ['SELECT', 'INSERT', 'UPDATE'];
            break;
          case 'admin':
          case 'ADMIN':
            operations = ['SELECT', 'INSERT', 'UPDATE', 'DELETE'];
            break;
          default:
            // Para compatibilidade com diferentes formatos, vamos tentar analisar o que recebemos
            if (accessType === 'Leitura' || accessType === 'ReadOnly') {
              operations = ['SELECT'];
            } else if (accessType === 'Escrita' || accessType === 'ReadWrite') {
              operations = ['SELECT', 'INSERT', 'UPDATE'];
            } else if (accessType === 'Admin' || accessType === 'Full') {
              operations = ['SELECT', 'INSERT', 'UPDATE', 'DELETE'];
            } else {
              // Caso já seja um array, usar como está, senão, criar array com o valor
              operations = Array.isArray(accessType) ?
                accessType :
                ['SELECT']; // Valor padrão se nada for identificado
            }
        }

        // Obter IDs do servidor e do banco de dados
        const serverId = formData.serverId;
        const databaseName = formData.databaseName;
        const schemaName = formData.schemaName;

        // Detectar tipo de banco de dados - agora vem incluído no formData
        let databaseType = '';
        
        // Primeiro tentar usar o databaseType enviado pelo formulário
        if (formData.databaseType) {
          const rawDbType = formData.databaseType;
          if (typeof rawDbType === 'string') {
            databaseType = rawDbType.toLowerCase();
          } else if (rawDbType && typeof rawDbType === 'object' && 'toString' in rawDbType) {
            databaseType = rawDbType.toString().toLowerCase();
          }
        }
        
        // Fallback: verificar o tipo no servidor selecionado, se disponível
        if (!databaseType && formData.server && formData.server.type) {
          databaseType = formData.server.type.toLowerCase();
        }
        
        // Corrigir para terminologia padrão
        if (databaseType === 'postgresql') databaseType = 'postgres';
        
        console.log('Tipo do banco de dados detectado:', databaseType);
        console.log('Server ID:', serverId);
        console.log('Database Name:', databaseName);
        console.log('Schema Name:', schemaName);
        
        // Verificar se temos o Database Name
        if (!databaseName) {
          console.error("Database name is required but missing");
          setError("Erro: Nome do banco de dados não fornecido");
          return;
        }

        // Verificar se temos o Server ID
        if (!serverId) {
          console.error("Server ID is required but missing");
          setError("Erro: ID do servidor não fornecido");
          return;
        }
        
        // Verificar se é PostgreSQL e se temos schema_name
        const isPostgres = databaseType === 'postgres';
        // Definimos um valor efetivo para o schema que será usado no requestData
        let effectiveSchemaName = schemaName;
        if (isPostgres && !effectiveSchemaName) {
          console.warn("Schema name is missing for PostgreSQL database, using 'public' as default");
          // Se não temos schema e é PostgreSQL, usar 'public' como padrão
          effectiveSchemaName = 'public';
        }

        // Criar objeto de requisição conforme esperado pelo backend
        const requestData: any = {
          user_id: formData.userId,
          server_id: serverId,
          database_name: databaseName, // Nome do banco de dados é necessário para a tabela access_requests
          // Sempre enviar schema_name para PostgreSQL, MSSQL e Oracle
          schema_name: (isPostgres || databaseType === 'mssql' || databaseType === 'oracle') ? (formData.schemaName || effectiveSchemaName) : undefined,
          tables: tablesData,
          operations: operations, // Array de operações mapeado conforme o tipo de acesso
          reason: formData.justification,
          is_permanent: formData.isPermanent ? true : false,
          expires_at: formData.isPermanent ? null :
            // Formatar a data para o formato ISO 8601 esperado pela API
            formData.expirationDate ?
              (formData.expirationDate + 'T00:00:00Z') :
              null,
        };
        
        // Add service user fields if present
        if (formData.is_service_user || formData.isServiceUser) {
          requestData.is_service_user = true;
          
          // For existing service users
          if (formData.service_user_id || formData.serviceUserId) {
            requestData.service_user_id = formData.service_user_id || formData.serviceUserId;
          }
          
          // For new service users
          if (formData.service_user_name || formData.serviceUserName) {
            requestData.service_user_name = formData.service_user_name || formData.serviceUserName;
          }
          if (formData.service_user_description || formData.serviceUserDescription) {
            requestData.service_user_description = formData.service_user_description || formData.serviceUserDescription;
          }
        }

        console.log('Dados para API:', {
          schema_name: requestData.schema_name,
          database_type: databaseType,
          original_schema: formData.schemaName
        });
        
        console.log('Enviando requisição formatada:', requestData);
        const response = await requestService.createRequest(requestData);
        
        // Verificar se a requisição foi bem-sucedida
        if (response && response.success) {
          console.log('Request criada com sucesso:', response);
          setSuccessMessage(t('createSuccess'));
          
          // Fechar o modal após criação bem-sucedida
          setShowNewRequestForm(false);
        } else {
          console.error('Erro ao criar request:', response);
          setError(t('createError') as string);
        }
      } else {
        console.error('Nenhum dado de formulário fornecido para submissão');
        setError(t('missingDataError') as string);
      }
    } catch (error: any) {
      console.error('Erro ao criar solicitação:', error);

      // Extrair mensagem de erro detalhada se disponível
      let errorMessage = t('createError') as string;

      // Log detalhado para depuração
      console.log('Detalhes do erro:', {
        error,
        errorMessage: error.message,
        response: error.response,
        responseData: error.response?.data,
        status: error.response?.status
      });

      if (error.response && error.response.data) {
        // Se for um erro do axios com uma resposta do servidor
        const serverErrorMsg = typeof error.response.data === 'string'
          ? error.response.data
          : error.response.data.message || error.response.data.error || JSON.stringify(error.response.data);

        console.error('Mensagem de erro do servidor:', serverErrorMsg);

        if (serverErrorMsg.includes('database not found')) {
          errorMessage = 'Banco de dados não encontrado. Verifique as configurações do banco de dados.';
        } else if (serverErrorMsg.includes('user not found')) {
          errorMessage = 'Usuário não encontrado. Verifique se o usuário está cadastrado no sistema.';
        } else if (serverErrorMsg.includes('invalid request')) {
          errorMessage = 'Requisição inválida. Verifique os dados informados.';
        } else {
          // Incluir a mensagem de erro do servidor para ajudar no diagnóstico
          errorMessage = `Erro ao criar solicitação: ${serverErrorMsg}`;
        }
      } else if (error.message) {
        // Se tivermos uma mensagem de erro direta, usamos ela
        errorMessage = `Erro ao criar solicitação: ${error.message}`;
      }

      // Adicionar a mensagem ao estado para exibição e log para depuração
      console.error('Mensagem de erro final:', errorMessage);
      setError(errorMessage);

      // Mesmo com erro, fechar o modal para evitar bloqueio da interface
      setTimeout(() => {
        setShowNewRequestForm(false);
      }, 5000); // Fecha após 5 segundos para o usuário ver a mensagem de erro
    } finally {
      // Atualizar a lista de solicitações independentemente do resultado
      fetchRequests();
    }
  };

  const handleActionClick = (request: Request, action: 'approve' | 'reject' | 'view' | 'details' | 'revoke' | 'delete') => {
    setSelectedRequest(request);
    setActionType(action);
    
    if (action === 'details') {
      setDetailsDialogOpen(true);
    }
  };
  
  const handleCloseDetailsDialog = () => {
    setDetailsDialogOpen(false);
  };

  const handleCloseActionForm = () => {
    setSelectedRequest(null);
    setActionType(null);
  };

  const handleActionCompleted = (newStatus?: string, success?: boolean) => {
    // Apenas atualiza o status na UI se a operação foi bem-sucedida
    if (selectedRequest && success === true) {
      if ((actionType === 'approve' || actionType === 'reject' || actionType === 'revoke' || actionType === 'delete') && newStatus) {
        // Se a solicitação foi aprovada, rejeitada, revogada ou deletada, ela não é mais pendente
        setPendingRequests(prev => 
          prev.filter(req => req.id !== selectedRequest.id)
        );
        
        // Define a mensagem de sucesso
        if (newStatus === 'approved') {
          setSuccessMessage(t('approveSuccess'));
        } else if (newStatus === 'rejected') {
          setSuccessMessage(t('rejectSuccess'));
        } else if (newStatus === 'revoked') {
          setSuccessMessage(t('revokeSuccess'));
        } else if (newStatus === 'deleted') {
          setSuccessMessage(t('deleteSuccess'));
        }
        
        // Limpa os estados de seleção apenas em caso de sucesso
        setSelectedRequest(null);
        setActionType(null);
      } else if (actionType === 'cancel') {
        // Remove a solicitação cancelada da lista
        setPendingRequests(prev => 
          prev.filter(req => req.id !== selectedRequest.id)
        );
        
        // Define a mensagem de sucesso
        setSuccessMessage(t('cancelSuccess'));
        
        // Limpa os estados de seleção
        setSelectedRequest(null);
        setActionType(null);
      }
    } else if (success === false && selectedRequest) {
      // Se explicitamente não foi bem-sucedido, exibe mensagem de erro específica
      // A mensagem de erro já terá sido exibida no modal de ação, então não precisamos
      // exibir outra aqui, mas mantemos o tipo de erro para diagnóstico
      console.error(`Ação ${actionType} falhou para solicitação ${selectedRequest.id}`);
      
      // NÃO limpar os estados de seleção para permitir que o usuário tente novamente
      // ou veja a mensagem de erro no modal
    }
    
    // Busca os dados atualizados da API depois de um breve atraso para sincronizar o estado local
    // Sempre busca dados novos, independente do resultado da operação
    setTimeout(() => {
      fetchRequests();
    }, 500);
  };
  
  // Função para cancelar uma solicitação pendente
  const handleCancelRequest = async (request: Request) => {
    if (request.status !== 'pending') {
      return;
    }
    
    setSelectedRequest(request);
    setActionType('cancel');
    setError(null); // Limpar erros anteriores
    
    try {
      // Chamar a API para cancelar a solicitação 
      const response = await requestService.cancelRequest(request.id, {
        reason: 'Cancelled by user'
      });
      
      // Verificar se a operação foi bem-sucedida
      if (response && !response.success) {
        console.error('Request cancellation failed:', response.message);
        setError(response.message || t('cancelError') as string);
        handleActionCompleted('', false);
        return;
      }
      
      // Operação bem-sucedida
      handleActionCompleted('canceled', true);
    } catch (error: any) {
      console.error('Error canceling request:', error);
      // Extrair mensagem detalhada do erro se disponível
      const errorMessage = error.response?.data?.message || 
                           error.response?.data?.error || 
                           error.message || 
                           t('cancelError') as string;
      setError(errorMessage);
      handleActionCompleted('', false);
    }
  };

  const handleCloseSnackbar = () => {
    setSuccessMessage(null);
  };

  return (
    <Box>
      <Snackbar
        open={!!successMessage}
        autoHideDuration={6000}
        onClose={handleCloseSnackbar}
        anchorOrigin={{ vertical: 'top', horizontal: 'center' }}
      >
        <Alert onClose={handleCloseSnackbar} severity="success" sx={{ width: '100%' }}>
          {successMessage}
        </Alert>
      </Snackbar>

      <Box display="flex" justifyContent="space-between" alignItems="center" mb={3}>
        <Typography variant="h5">
          {t('pending')}
        </Typography>
        <Box>
          <Button
            variant="outlined"
            startIcon={<RefreshIcon />}
            onClick={fetchRequests}
            sx={{ mr: 1 }}
            disabled={loading}
          >
            {t('common:refresh')}
          </Button>
          <Button
            variant="contained"
            startIcon={<AddIcon />}
            onClick={handleNewRequest}
            disabled={loading}
            color="primary"
          >
            {t('newButton')}
          </Button>
        </Box>
      </Box>

      {error && (
        <Alert severity="error" sx={{ mb: 3 }}>
          {error}
        </Alert>
      )}

      <Paper>
        <TableContainer>
          {loading ? (
            <Box display="flex" justifyContent="center" alignItems="center" p={4}>
              <CircularProgress />
            </Box>
          ) : pendingRequests.length === 0 ? (
            <Box p={3} textAlign="center">
              <Typography variant="body1">{t('noPendingRequests')}</Typography>
            </Box>
          ) : (
            <Table>
              <TableHead>
                <TableRow>
                  <TableCell>{t('table.requestId')}</TableCell>
                  <TableCell>{t('table.user')}</TableCell>
                  <TableCell>{t('table.database')}</TableCell>
                  <TableCell>{t('table.tables')}</TableCell>
                  <TableCell>{t('table.operations')}</TableCell>
                  <TableCell>{t('table.requestDate')}</TableCell>
                  <TableCell>{t('table.actions')}</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {pendingRequests.map((request) => (
                  <TableRow key={request.id}>
                    <TableCell>
                      {request.id.length > 10 
                        ? `REQ-${request.id.substring(0, 8)}` 
                        : request.id}
                    </TableCell>
                    <TableCell>
                      {request.isServiceUser ? (
                        <Box>
                          <Typography variant="body2" component="div">
                            <strong>{t('serviceUser')}:</strong> {request.serviceUserName || t('newServiceUser')}
                          </Typography>
                          <Typography variant="caption" color="textSecondary">
                            {t('requestedBy')}: {request.requestedBy}
                          </Typography>
                        </Box>
                      ) : (
                        request.user
                      )}
                    </TableCell>
                    <TableCell>{request.database}</TableCell>
                    <TableCell>{request.tables}</TableCell>
                    <TableCell>
                      {request.operations.split(',').map((op, index) => (
                        <Chip
                          key={index}
                          label={t(`permissions:operations.${op.trim()}`)}
                          color={
                            op.trim().toUpperCase() === 'SELECT' ? 'success' :
                            op.trim().toUpperCase() === 'INSERT' || op.trim().toUpperCase() === 'UPDATE' ? 'warning' :
                            op.trim().toUpperCase() === 'DELETE' ? 'error' :
                            op.trim() === 'read' ? 'success' :  // Backward compatibility with old format
                            op.trim() === 'write' ? 'warning' : // Backward compatibility with old format
                            'default'
                          }
                          size="small"
                          sx={{ mr: 0.5, mb: 0.5 }}
                        />
                      ))}
                    </TableCell>
                    <TableCell>{request.requestDate}</TableCell>
                    <TableCell>
                      {/* Botão "Ver Detalhes" para todos os usuários */}
                      <Tooltip 
                        title={t('actions.view') as string} 
                        placement="top"
                        TransitionComponent={Zoom}
                        arrow
                      >
                        <AnimatedIconButton
                          size="small"
                          color="info"
                          onClick={() => handleActionClick(request, 'details')}
                          sx={{
                            mr: 1,
                            border: '1px solid',
                            borderColor: theme.palette.info.main,
                          }}
                        >
                          <InfoIcon fontSize="small" />
                        </AnimatedIconButton>
                      </Tooltip>

                      {/* Aprovadores e administradores podem aprovar/rejeitar */}
                      {(userRole === 'admin' || userRole === 'administrator' || userRole === 'approver') && (
                        <>
                          <Button
                            size="small"
                            color="success"
                            onClick={() => handleActionClick(request, 'approve')}
                            startIcon={<CheckIcon />}
                            sx={{ mr: 1 }}
                          >
                            {t('common:approve')}
                          </Button>
                          <Button
                            size="small"
                            color="error"
                            onClick={() => handleActionClick(request, 'reject')}
                          >
                            {t('common:reject')}
                          </Button>
                        </>
                      )}
                      
                      {/* Solicitantes só podem cancelar seus próprios pedidos pendentes */}
                      {userRole === 'requester' && currentUser && (
                        <>
                          <Button
                            size="small"
                            color="primary"
                            onClick={() => handleActionClick(request, 'view')}
                            startIcon={<VisibilityIcon />}
                            sx={{ mr: 1 }}
                          >
                            {t('common:view')}
                          </Button>
                          
                          {/* Mostrar botão Cancelar apenas para pedidos do próprio usuário */}
                          {request.user === currentUser.username && (
                            <Button
                              size="small"
                              color="error"
                              onClick={() => handleCancelRequest(request)}
                            >
                              {t('common:cancel')}
                            </Button>
                          )}
                        </>
                      )}
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </TableContainer>
      </Paper>

      {/* Formulário de nova solicitação - versão simplificada */}
      {showNewRequestForm && (
        <RequestForm
          open={showNewRequestForm}
          onClose={handleCloseNewRequestForm}
          onSubmit={handleRequestSubmitted}
          currentUser={currentUser ? {
            id: currentUser.id,
            username: currentUser.username,
            email: ''
          } : undefined}
        />
      )}

      {/* Formulário de ação (aprovar/rejeitar/visualizar) */}
      {selectedRequest && actionType && actionType !== 'details' && (
        <RequestActionForm
          open={true}
          onClose={handleCloseActionForm}
          onAction={handleActionCompleted}
          request={selectedRequest}
          action={actionType}
        />
      )}

      {/* Request Details Dialog */}
      {selectedRequest && (
        <Dialog
          open={detailsDialogOpen}
          onClose={handleCloseDetailsDialog}
          maxWidth="md"
          fullWidth
          disableEnforceFocus
          disableRestoreFocus
          PaperProps={{
            sx: {
              borderRadius: 2,
              overflow: 'hidden'
            }
          }}
        >
          <DialogTitle
            sx={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'space-between',
              bgcolor: theme.palette.primary.main,
              color: 'white',
              py: 2
            }}
          >
            <Box display="flex" alignItems="center">
              <InfoIcon sx={{ mr: 1 }} />
              <Typography variant="h6">
                {t('details.title')}
              </Typography>
            </Box>
            <IconButton
              edge="end"
              color="inherit"
              onClick={handleCloseDetailsDialog}
              aria-label="close"
            >
              <CloseIcon />
            </IconButton>
          </DialogTitle>
          <DialogContent sx={{ p: 3 }}>
            <Box sx={{ mb: 3 }}>
              <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 2 }}>
                {/* User */}
                <Paper 
                  elevation={2} 
                  sx={{ 
                    p: 2, 
                    flex: '1 0 calc(50% - 8px)',
                    borderRadius: 2,
                    display: 'flex',
                    alignItems: 'center',
                    transition: 'transform 0.2s',
                    '&:hover': {
                      transform: 'translateY(-4px)',
                      boxShadow: 4
                    }
                  }}
                >
                  <UserIcon color="primary" sx={{ mr: 1 }} />
                  <Box>
                    <Typography variant="caption" color="textSecondary">
                      {selectedRequest.isServiceUser ? t('serviceUser') : t('table.user')}
                    </Typography>
                    <Typography variant="subtitle1" sx={{ fontWeight: 'medium' }}>
                      {selectedRequest.isServiceUser 
                        ? (selectedRequest.serviceUserName || t('newServiceUser'))
                        : selectedRequest.user}
                    </Typography>
                    {selectedRequest.isServiceUser && (
                      <Typography variant="caption" color="textSecondary">
                        {t('requestedBy')}: {selectedRequest.requestedBy}
                      </Typography>
                    )}
                  </Box>
                </Paper>

                {/* Database */}
                <Paper 
                  elevation={2} 
                  sx={{ 
                    p: 2, 
                    flex: '1 0 calc(50% - 8px)',
                    borderRadius: 2,
                    display: 'flex',
                    alignItems: 'center',
                    transition: 'transform 0.2s',
                    '&:hover': {
                      transform: 'translateY(-4px)',
                      boxShadow: 4
                    }
                  }}
                >
                  <DatabaseIcon color="primary" sx={{ mr: 1 }} />
                  <Box>
                    <Typography variant="caption" color="textSecondary">
                      {t('table.database')}
                    </Typography>
                    <Typography variant="subtitle1" sx={{ fontWeight: 'medium' }}>
                      {selectedRequest.database}
                    </Typography>
                  </Box>
                </Paper>

                {/* Tables */}
                <Paper 
                  elevation={2} 
                  sx={{ 
                    p: 2, 
                    flex: '1 0 calc(50% - 8px)',
                    borderRadius: 2,
                    display: 'flex',
                    alignItems: 'center',
                    transition: 'transform 0.2s',
                    '&:hover': {
                      transform: 'translateY(-4px)',
                      boxShadow: 4
                    }
                  }}
                >
                  <TableIcon color="primary" sx={{ mr: 1 }} />
                  <Box>
                    <Typography variant="caption" color="textSecondary">
                      {t('table.tables')}
                    </Typography>
                    <Typography variant="subtitle1" sx={{ fontWeight: 'medium' }}>
                      {selectedRequest.tables}
                    </Typography>
                  </Box>
                </Paper>

                {/* Operations */}
                <Paper 
                  elevation={2} 
                  sx={{ 
                    p: 2, 
                    flex: '1 0 calc(50% - 8px)',
                    borderRadius: 2,
                    display: 'flex',
                    alignItems: 'center',
                    transition: 'transform 0.2s',
                    '&:hover': {
                      transform: 'translateY(-4px)',
                      boxShadow: 4
                    }
                  }}
                >
                  <OperationsIcon color="primary" sx={{ mr: 1 }} />
                  <Box>
                    <Typography variant="caption" color="textSecondary">
                      {t('table.operations')}
                    </Typography>
                    <Typography variant="subtitle1" sx={{ fontWeight: 'medium' }}>
                      {selectedRequest.operations}
                    </Typography>
                  </Box>
                </Paper>

                {/* Request Date */}
                <Paper 
                  elevation={2} 
                  sx={{ 
                    p: 2, 
                    flex: '1 0 calc(50% - 8px)',
                    borderRadius: 2,
                    display: 'flex',
                    alignItems: 'center',
                    transition: 'transform 0.2s',
                    '&:hover': {
                      transform: 'translateY(-4px)',
                      boxShadow: 4
                    }
                  }}
                >
                  <TimeIcon color="primary" sx={{ mr: 1 }} />
                  <Box>
                    <Typography variant="caption" color="textSecondary">
                      {t('table.requestDate')}
                    </Typography>
                    <Typography variant="subtitle1" sx={{ fontWeight: 'medium' }}>
                      {selectedRequest.requestDate}
                    </Typography>
                  </Box>
                </Paper>

                {/* Status */}
                <Paper 
                  elevation={2} 
                  sx={{ 
                    p: 2, 
                    flex: '1 0 calc(50% - 8px)',
                    borderRadius: 2,
                    display: 'flex',
                    alignItems: 'center',
                    transition: 'transform 0.2s',
                    '&:hover': {
                      transform: 'translateY(-4px)',
                      boxShadow: 4
                    }
                  }}
                >
                  <InfoIcon color="primary" sx={{ mr: 1 }} />
                  <Box>
                    <Typography variant="caption" color="textSecondary">
                      {t('table.status')}
                    </Typography>
                    <Box sx={{ mt: 0.5 }}>
                      <Chip 
                        label={t(`status.${selectedRequest.status}`)} 
                        color={selectedRequest.status === 'pending' ? 'warning' : 'primary'}
                        size="small"
                      />
                    </Box>
                  </Box>
                </Paper>
              </Box>

              {/* Justification */}
              {selectedRequest.justification && (
                <Paper 
                  elevation={2} 
                  sx={{ 
                    p: 2, 
                    mt: 2, 
                    borderRadius: 2,
                    transition: 'transform 0.2s',
                    '&:hover': {
                      transform: 'translateY(-4px)',
                      boxShadow: 4
                    }
                  }}
                >
                  <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                    <DescriptionIcon color="primary" sx={{ mr: 1 }} />
                    <Typography variant="subtitle1" sx={{ fontWeight: 'medium' }}>
                      {t('form.justification')}
                    </Typography>
                  </Box>
                  <Typography variant="body2">
                    {selectedRequest.justification}
                  </Typography>
                </Paper>
              )}
            </Box>
          </DialogContent>
          <DialogActions sx={{ p: 2, borderTop: `1px solid ${theme.palette.divider}` }}>
            <Button onClick={handleCloseDetailsDialog} color="primary">
              {t('common:close')}
            </Button>
          </DialogActions>
        </Dialog>
      )}
    </Box>
  );
};

export default PendingRequestsPage;
