import React from 'react';
import { Box, Button, CircularProgress, Tooltip, Zoom, Typography } from '@mui/material';
import ArrowBackIcon from '@mui/icons-material/ArrowBack';
import ArrowForwardIcon from '@mui/icons-material/ArrowForward';
import CheckIcon from '@mui/icons-material/CheckCircle';
import CancelIcon from '@mui/icons-material/Cancel';
import CloseIcon from '@mui/icons-material/Close';

interface ActionButtonsProps {
  currentStep: number;
  totalSteps: number;
  onBack: () => void;
  onNext: () => void;
  onCancel: () => void;
  isLastStep: boolean;
  isLoading: boolean;
  nextDisabled?: boolean;
  nextLabel?: string;
  backLabel?: string;
  cancelLabel?: string;
}

/**
 * Componente para exibir os botões de navegação entre etapas
 */
const ActionButtons: React.FC<ActionButtonsProps> = ({
  currentStep,
  totalSteps,
  onBack,
  onNext,
  onCancel,
  isLastStep,
  isLoading,
  nextDisabled = false,
  nextLabel,
  backLabel,
  cancelLabel = 'Cancelar'
}) => {
  // Determinar tooltips dos botões
  const nextTooltip = isLastStep 
    ? 'Enviar solicitação de acesso' 
    : `Avançar para a etapa ${currentStep + 2} de ${totalSteps}`;
  
  const backTooltip = `Voltar para a etapa ${currentStep} de ${totalSteps}`;
  
  return (
    <Box
      sx={{
        display: 'flex',
        justifyContent: 'space-between',
        mt: 3,
        pt: 2,
        borderTop: '1px solid',
        borderColor: 'divider',
        position: 'relative'
      }}
    >
      {/* Indicador de progresso */}
      <Box 
        sx={{ 
          position: 'absolute',
          top: -15,
          left: 0,
          right: 0,
          textAlign: 'center'
        }}
      >
        <Typography 
          variant="caption" 
          sx={{ 
            bgcolor: 'background.paper',
            px: 2,
            py: 0.5,
            borderRadius: 10,
            boxShadow: '0 1px 4px rgba(0,0,0,0.1)',
            color: 'text.secondary',
            fontWeight: 500
          }}
        >
          Etapa {currentStep + 1} de {totalSteps}
        </Typography>
      </Box>

      <Tooltip
        title="Cancelar e fechar formulário" 
        arrow
        TransitionComponent={Zoom}
      >
        <Button
          variant="outlined"
          startIcon={<CloseIcon />}
          onClick={onCancel}
          color="inherit"
          sx={{
            borderRadius: 2,
            px: 2.5,
            transition: 'all 0.2s',
            '&:hover': {
              backgroundColor: 'error.light',
              color: 'error.contrastText',
              borderColor: 'error.main'
            }
          }}
        >
          {cancelLabel}
        </Button>
      </Tooltip>

      <Box>
        {currentStep > 0 && (
          <Tooltip 
            title={backTooltip} 
            arrow
            TransitionComponent={Zoom}
          >
            <span> {/* Wrapper span para permitir tooltip em botão desabilitado */}
              <Button
                sx={{ 
                  mr: 1.5,
                  borderRadius: 2,
                  px: 2.5,
                  transition: 'all 0.2s ease'
                }}
                variant="outlined"
                startIcon={<ArrowBackIcon />}
                onClick={onBack}
                disabled={isLoading}
                color="primary"
              >
                {backLabel || 'Anterior'}
              </Button>
            </span>
          </Tooltip>
        )}

        <Tooltip 
          title={nextDisabled ? 'Complete os campos necessários para continuar' : nextTooltip} 
          arrow
          TransitionComponent={Zoom}
        >
          <span> {/* Wrapper span para permitir tooltip em botão desabilitado */}
            <Button
              variant="contained"
              color={isLastStep ? "success" : "primary"}
              endIcon={isLastStep ? <CheckIcon /> : <ArrowForwardIcon />}
              onClick={onNext}
              disabled={isLoading || nextDisabled}
              sx={{
                borderRadius: 2,
                px: 3,
                py: 1,
                fontWeight: isLastStep ? 600 : 500,
                boxShadow: isLastStep ? 4 : 2,
                transition: 'all 0.3s ease',
                '&:hover': {
                  transform: 'translateY(-2px)',
                  boxShadow: isLastStep ? 8 : 4
                }
              }}
            >
              {isLoading ? (
                <CircularProgress size={24} color="inherit" sx={{ mx: 1 }} />
              ) : nextLabel || (isLastStep ? 'Confirmar' : 'Próximo')}
            </Button>
          </span>
        </Tooltip>
      </Box>
    </Box>
  );
};

export default React.memo(ActionButtons);