import React, { useState, useEffect } from 'react';
import {
  Card,
  CardContent,
  CardHeader,
  Typography,
  Switch,
  FormControlLabel,
  TextField,
  Button,
  Box,
  Alert,
  Select,
  MenuItem,
  FormControl,
  InputLabel,
  Tabs,
  Tab,
  IconButton,
  InputAdornment,
  CircularProgress,
  Tooltip,
} from '@mui/material';
import {
  Visibility,
  VisibilityOff,
  CheckCircle,
  Error,
  Info,
} from '@mui/icons-material';
import { useTranslation } from 'react-i18next';
import { api } from '../services/api';

interface SecretManagerConfig {
  enabled: boolean;
  provider: 'aws' | 'azure' | 'local';
  aws?: {
    region: string;
    access_key_id?: string;
    secret_access_key?: string;
    role_arn?: string;
    prefix: string;
  };
  azure?: {
    tenant_id: string;
    client_id: string;
    client_secret?: string;
    key_vault_name: string;
    subscription_id?: string;
    use_msi: boolean;
  };
}

interface TabPanelProps {
  children?: React.ReactNode;
  index: number;
  value: number;
}

function TabPanel(props: TabPanelProps) {
  const { children, value, index, ...other } = props;

  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`secret-manager-tabpanel-${index}`}
      aria-labelledby={`secret-manager-tab-${index}`}
      {...other}
    >
      {value === index && <Box sx={{ p: 3 }}>{children}</Box>}
    </div>
  );
}

const SecretManagersConfig: React.FC = () => {
  const { t } = useTranslation(['settings', 'common']);
  const [config, setConfig] = useState<SecretManagerConfig>({
    enabled: false,
    provider: 'local',
  });
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [testing, setTesting] = useState(false);
  const [testResult, setTestResult] = useState<{ success: boolean; message: string } | null>(null);
  const [saveMessage, setSaveMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null);
  const [tabValue, setTabValue] = useState(0);
  const [showSecrets, setShowSecrets] = useState({
    aws: false,
    azure: false,
  });

  useEffect(() => {
    fetchConfig();
  }, []);

  const fetchConfig = async () => {
    try {
      const response = await api.get('/api/configuration/secret_managers');
      if (response.data) {
        setConfig(response.data);
        // Set tab based on provider
        if (response.data.provider === 'aws') setTabValue(0);
        else if (response.data.provider === 'azure') setTabValue(1);
      }
    } catch (error) {
      console.error('Failed to fetch secret manager config:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleSave = async () => {
    setSaving(true);
    setSaveMessage(null);
    try {
      await api.put('/api/configuration/secret_managers', config);
      setSaveMessage({ type: 'success', text: t('settings:secretManagers.saveSuccess') });
    } catch (error) {
      setSaveMessage({ type: 'error', text: t('settings:secretManagers.saveError') });
    } finally {
      setSaving(false);
    }
  };

  const handleTest = async () => {
    setTesting(true);
    setTestResult(null);
    try {
      await api.post('/api/configuration/secret_managers/test', config);
      setTestResult({ success: true, message: t('settings:secretManagers.testSuccess') });
    } catch (error: any) {
      setTestResult({ 
        success: false, 
        message: error.response?.data?.message || error.message || t('settings:secretManagers.testError') 
      });
    } finally {
      setTesting(false);
    }
  };

  const handleTabChange = (event: React.SyntheticEvent, newValue: number) => {
    setTabValue(newValue);
    // Update provider based on tab
    if (newValue === 0) {
      setConfig({ ...config, provider: 'aws' });
    } else if (newValue === 1) {
      setConfig({ ...config, provider: 'azure' });
    }
  };

  const updateAWSConfig = (field: string, value: any) => {
    setConfig({
      ...config,
      aws: {
        ...config.aws,
        region: config.aws?.region || '',
        prefix: config.aws?.prefix || '',
        [field]: value,
      },
    });
  };

  const updateAzureConfig = (field: string, value: any) => {
    setConfig({
      ...config,
      azure: {
        ...config.azure,
        tenant_id: config.azure?.tenant_id || '',
        client_id: config.azure?.client_id || '',
        key_vault_name: config.azure?.key_vault_name || '',
        use_msi: config.azure?.use_msi || false,
        [field]: value,
      },
    });
  };

  if (loading) {
    return (
      <Card>
        <CardContent sx={{ display: 'flex', justifyContent: 'center', p: 4 }}>
          <CircularProgress />
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader
        title={t('settings:secretManagers.title')}
        subheader={t('settings:secretManagers.description')}
      />
      <CardContent>
        <Box sx={{ mb: 3 }}>
          <FormControlLabel
            control={
              <Switch
                checked={config.enabled}
                onChange={(e) => setConfig({ ...config, enabled: e.target.checked })}
                color="primary"
              />
            }
            label={t('settings:secretManagers.enable')}
          />
        </Box>

        {config.enabled && (
          <>
            <Alert severity="info" sx={{ mb: 3 }}>
              {t('settings:secretManagers.info')}
            </Alert>

            {saveMessage && (
              <Alert 
                severity={saveMessage.type} 
                sx={{ mb: 3 }}
                onClose={() => setSaveMessage(null)}
              >
                {saveMessage.text}
              </Alert>
            )}

            <Box sx={{ borderBottom: 1, borderColor: 'divider' }}>
              <Tabs value={tabValue} onChange={handleTabChange}>
                <Tab label="AWS Secrets Manager" />
                <Tab label="Azure Key Vault" />
              </Tabs>
            </Box>

            <TabPanel value={tabValue} index={0}>
              <Typography variant="h6" gutterBottom>
                AWS Secrets Manager
              </Typography>
              
              <FormControl fullWidth margin="normal" required>
                <InputLabel>{t('settings:secretManagers.aws.region')}</InputLabel>
                <Select
                  value={config.aws?.region || ''}
                  onChange={(e) => updateAWSConfig('region', e.target.value)}
                  label={t('settings:secretManagers.aws.region')}
                >
                  <MenuItem value="">
                    <em>{t('common:select')}</em>
                  </MenuItem>
                  {/* US Regions */}
                  <MenuItem value="us-east-1">US East (N. Virginia)</MenuItem>
                  <MenuItem value="us-east-2">US East (Ohio)</MenuItem>
                  <MenuItem value="us-west-1">US West (N. California)</MenuItem>
                  <MenuItem value="us-west-2">US West (Oregon)</MenuItem>
                  {/* Europe Regions */}
                  <MenuItem value="eu-west-1">EU (Ireland)</MenuItem>
                  <MenuItem value="eu-west-2">EU (London)</MenuItem>
                  <MenuItem value="eu-west-3">EU (Paris)</MenuItem>
                  <MenuItem value="eu-central-1">EU (Frankfurt)</MenuItem>
                  <MenuItem value="eu-north-1">EU (Stockholm)</MenuItem>
                  <MenuItem value="eu-south-1">EU (Milan)</MenuItem>
                  {/* Asia Pacific Regions */}
                  <MenuItem value="ap-south-1">Asia Pacific (Mumbai)</MenuItem>
                  <MenuItem value="ap-northeast-1">Asia Pacific (Tokyo)</MenuItem>
                  <MenuItem value="ap-northeast-2">Asia Pacific (Seoul)</MenuItem>
                  <MenuItem value="ap-northeast-3">Asia Pacific (Osaka)</MenuItem>
                  <MenuItem value="ap-southeast-1">Asia Pacific (Singapore)</MenuItem>
                  <MenuItem value="ap-southeast-2">Asia Pacific (Sydney)</MenuItem>
                  <MenuItem value="ap-southeast-3">Asia Pacific (Jakarta)</MenuItem>
                  <MenuItem value="ap-east-1">Asia Pacific (Hong Kong)</MenuItem>
                  {/* South America */}
                  <MenuItem value="sa-east-1">South America (São Paulo)</MenuItem>
                  {/* Canada */}
                  <MenuItem value="ca-central-1">Canada (Central)</MenuItem>
                  {/* Middle East */}
                  <MenuItem value="me-south-1">Middle East (Bahrain)</MenuItem>
                  <MenuItem value="me-central-1">Middle East (UAE)</MenuItem>
                  {/* Africa */}
                  <MenuItem value="af-south-1">Africa (Cape Town)</MenuItem>
                </Select>
                <Typography variant="caption" color="textSecondary" sx={{ mt: 1, display: 'block' }}>
                  {t('settings:secretManagers.aws.regionHelp')}
                </Typography>
              </FormControl>

              <TextField
                fullWidth
                label={t('settings:secretManagers.aws.prefix')}
                value={config.aws?.prefix || ''}
                onChange={(e) => updateAWSConfig('prefix', e.target.value)}
                margin="normal"
                required
                helperText={t('settings:secretManagers.aws.prefixHelp')}
              />

              <Alert severity="info" sx={{ mt: 2, mb: 2 }}>
                {t('settings:secretManagers.aws.authInfo')}
              </Alert>

              <TextField
                fullWidth
                label={t('settings:secretManagers.aws.accessKeyId')}
                value={config.aws?.access_key_id || ''}
                onChange={(e) => updateAWSConfig('access_key_id', e.target.value)}
                margin="normal"
                helperText={t('settings:secretManagers.aws.accessKeyIdHelp')}
              />

              <TextField
                fullWidth
                label={t('settings:secretManagers.aws.secretAccessKey')}
                type={showSecrets.aws ? 'text' : 'password'}
                value={config.aws?.secret_access_key || ''}
                onChange={(e) => updateAWSConfig('secret_access_key', e.target.value)}
                margin="normal"
                InputProps={{
                  endAdornment: (
                    <InputAdornment position="end">
                      <IconButton
                        onClick={() => setShowSecrets({ ...showSecrets, aws: !showSecrets.aws })}
                        edge="end"
                      >
                        {showSecrets.aws ? <VisibilityOff /> : <Visibility />}
                      </IconButton>
                    </InputAdornment>
                  ),
                }}
                helperText={t('settings:secretManagers.aws.secretAccessKeyHelp')}
              />

              <TextField
                fullWidth
                label={t('settings:secretManagers.aws.roleArn')}
                value={config.aws?.role_arn || ''}
                onChange={(e) => updateAWSConfig('role_arn', e.target.value)}
                margin="normal"
                helperText={t('settings:secretManagers.aws.roleArnHelp')}
              />
            </TabPanel>

            <TabPanel value={tabValue} index={1}>
              <Typography variant="h6" gutterBottom>
                Azure Key Vault
              </Typography>

              <TextField
                fullWidth
                label={t('settings:secretManagers.azure.tenantId')}
                value={config.azure?.tenant_id || ''}
                onChange={(e) => updateAzureConfig('tenant_id', e.target.value)}
                margin="normal"
                required
                helperText={t('settings:secretManagers.azure.tenantIdHelp')}
              />

              <TextField
                fullWidth
                label={t('settings:secretManagers.azure.keyVaultName')}
                value={config.azure?.key_vault_name || ''}
                onChange={(e) => updateAzureConfig('key_vault_name', e.target.value)}
                margin="normal"
                required
                helperText={t('settings:secretManagers.azure.keyVaultNameHelp')}
              />

              <FormControlLabel
                control={
                  <Switch
                    checked={config.azure?.use_msi || false}
                    onChange={(e) => updateAzureConfig('use_msi', e.target.checked)}
                    color="primary"
                  />
                }
                label={t('settings:secretManagers.azure.useMsi')}
                sx={{ mt: 2, mb: 2 }}
              />

              {!config.azure?.use_msi && (
                <>
                  <TextField
                    fullWidth
                    label={t('settings:secretManagers.azure.clientId')}
                    value={config.azure?.client_id || ''}
                    onChange={(e) => updateAzureConfig('client_id', e.target.value)}
                    margin="normal"
                    required
                    helperText={t('settings:secretManagers.azure.clientIdHelp')}
                  />

                  <TextField
                    fullWidth
                    label={t('settings:secretManagers.azure.clientSecret')}
                    type={showSecrets.azure ? 'text' : 'password'}
                    value={config.azure?.client_secret || ''}
                    onChange={(e) => updateAzureConfig('client_secret', e.target.value)}
                    margin="normal"
                    required
                    InputProps={{
                      endAdornment: (
                        <InputAdornment position="end">
                          <IconButton
                            onClick={() => setShowSecrets({ ...showSecrets, azure: !showSecrets.azure })}
                            edge="end"
                          >
                            {showSecrets.azure ? <VisibilityOff /> : <Visibility />}
                          </IconButton>
                        </InputAdornment>
                      ),
                    }}
                    helperText={t('settings:secretManagers.azure.clientSecretHelp')}
                  />
                </>
              )}

              <TextField
                fullWidth
                label={t('settings:secretManagers.azure.subscriptionId')}
                value={config.azure?.subscription_id || ''}
                onChange={(e) => updateAzureConfig('subscription_id', e.target.value)}
                margin="normal"
                helperText={t('settings:secretManagers.azure.subscriptionIdHelp')}
              />
            </TabPanel>

            {testResult && (
              <Alert 
                severity={testResult.success ? 'success' : 'error'} 
                sx={{ mt: 2, mb: 2 }}
                icon={testResult.success ? <CheckCircle /> : <Error />}
              >
                {testResult.message}
              </Alert>
            )}

            <Box sx={{ mt: 3, display: 'flex', gap: 2 }}>
              <Button
                variant="outlined"
                onClick={handleTest}
                disabled={testing || saving}
              >
                {testing ? <CircularProgress size={20} /> : t('common:test')}
              </Button>
              <Button
                variant="contained"
                color="primary"
                onClick={handleSave}
                disabled={saving || testing}
              >
                {saving ? <CircularProgress size={20} /> : t('common:save')}
              </Button>
            </Box>
          </>
        )}
      </CardContent>
    </Card>
  );
};

export default SecretManagersConfig;